// `lini fmt`: reprint a document in canonical style.

use crate::diag::Diag;

pub fn format(src: &str) -> Result<String, Diag> {
    let _ = crate::parser::parse(src)?;
    Ok(src.to_string())
}
mod ast;
mod chart;
mod cli;
mod color;
mod compile;
mod desugar;
mod format;
mod highlight;
mod diag;
mod eval;
mod font;
mod layout;
mod geom;
mod lexer;
mod markers;
mod parser;
mod render;
mod scene;
mod style;
mod theme;
mod types;
mod util;

use std::io::{Read, Write};

#[derive(Default, Clone)]
pub struct Options {
    pub output: Option<String>,
    pub format: String,
    pub static_: bool,
    pub embed_font: bool,
    pub check: bool,
    pub json: bool,
    pub theme: Option<String>,
    pub no_fs: bool,
    pub no_warn: bool,
    pub strict: bool,
    pub watch: bool,
}

fn read_input(path: &str) -> Result<String, String> {
    if path == "-" {
        let mut s = String::new();
        std::io::stdin().read_to_string(&mut s).map_err(|e| format!("error: <stdin>: {}", e))?;
        return Ok(s);
    }
    match std::fs::read(path) {
        Ok(b) => Ok(String::from_utf8_lossy(&b).into_owned()),
        Err(e) => Err(format!("error: {}: {}", path, e)),
    }
}

pub fn compile_src(src: &str, file: &str, opts: &Options) -> Result<(String, Vec<diag::Diag>), (diag::Diag, Vec<diag::Diag>)> {
    let (doc, _comments) = parser::parse(src).map_err(|e| (e, vec![]))?;
    let sheet = scene::build_sheet(&doc).map_err(|e| (e, vec![]))?;
    let root = compile::root_decls_node(&sheet);
    let mut b = scene::Builder::new(&sheet);
    b.add(root, None);
    b.build_stmts(&doc.stmts, 0).map_err(|e| (e, vec![]))?;
    let nodes = std::mem::take(&mut b.nodes);
    drop(b);
    let mut ctx = compile::Ctx {
        src: src.to_string(),
        file: file.to_string(),
        sheet,
        nodes,
        comp: vec![],
        links: vec![],
        warnings: vec![],
        root_font_size: 15.0,
    };
    compile::compute(&mut ctx);
    ctx.root_font_size = ctx.comp[0].font_size;
    layout::measure(&mut ctx, 0, None);
    let svg = render::render(&ctx, opts).map_err(|e| (e, vec![]))?;
    Ok((svg, ctx.warnings))
}

fn write_out(opts: &Options, text: &str) {
    match &opts.output {
        Some(path) if path != "-" => {
            let _ = std::fs::write(path, text.as_bytes());
        }
        _ => {
            let mut so = std::io::stdout();
            let _ = so.write_all(text.as_bytes());
        }
    }
}

fn html_wrap(svg: &str) -> String {
    format!(
        "<!doctype html>\n<html>\n<head>\n  <meta charset=\"utf-8\">\n  <title>lini</title>\n</head>\n<body>\n{}</body>\n</html>\n",
        svg
    )
}

fn run_compile(input: &str, opts: &Options) -> i32 {
    if opts.format != "svg" && opts.format != "html" {
        eprintln!("error: invalid --format '{}' (expected svg|html)", opts.format);
        return 3;
    }
    if let Some(t) = &opts.theme {
        if theme::resolve(t).is_none() {
            eprintln!(
                "error: theme '{}': not a built-in (try: default, light, dark, high-contrast, blueprint), and reading it as a file failed: No such file or directory (os error 2)",
                t
            );
            return 2;
        }
    }
    let src = match read_input(input) {
        Ok(s) => s,
        Err(e) => {
            eprintln!("{}", e);
            return 2;
        }
    };
    let file = if input == "-" { "<stdin>".to_string() } else { input.to_string() };
    let result = compile_src(&src, &file, opts);
    if opts.json {
        let (diags, failed) = match &result {
            Ok((_, w)) => (w.clone(), false),
            Err((e, w)) => {
                let mut d = w.clone();
                d.push(e.clone());
                (d, true)
            }
        };
        print!("{}", diag::render_json(&file, &src, &diags));
        if failed || (opts.strict && !diags.is_empty()) {
            return 1;
        }
        return 0;
    }
    match result {
        Ok((svg, warns)) => {
            if !opts.no_warn {
                for w in &warns {
                    eprintln!("{}", diag::render_text(&file, &src, w));
                }
            }
            if !opts.check {
                let text = if opts.format == "html" { html_wrap(&svg) } else { svg };
                write_out(opts, &text);
            }
            if opts.strict && !warns.is_empty() {
                return 1;
            }
            0
        }
        Err((e, warns)) => {
            if !opts.no_warn {
                for w in &warns {
                    eprintln!("{}", diag::render_text(&file, &src, w));
                }
            }
            eprintln!("{}", diag::render_text(&file, &src, &e));
            1
        }
    }
}

fn run_fmt(input: &str, check: bool, stdout: bool) -> i32 {
    let src = match read_input(input) {
        Ok(s) => s,
        Err(e) => {
            eprintln!("{}", e);
            return 2;
        }
    };
    let file = if input == "-" { "<stdin>".to_string() } else { input.to_string() };
    let out = match format::format(&src) {
        Ok(o) => o,
        Err(e) => {
            eprintln!("{}", diag::render_text(&file, &src, &e));
            return 1;
        }
    };
    if check {
        if out != src {
            eprintln!("{}: would reformat", file);
            return 1;
        }
        return 0;
    }
    if stdout || input == "-" {
        print!("{}", out);
        return 0;
    }
    if out != src {
        let _ = std::fs::write(input, out.as_bytes());
    }
    0
}

fn run_theme(name: &Option<String>) -> i32 {
    match name {
        None => {
            print!("{}", theme::LIST);
            0
        }
        Some(n) => match theme::css_of(n) {
            Some(css) => {
                print!("{}", css);
                0
            }
            None => {
                eprintln!("error: unknown theme '{}' (try one of: default, light, dark, high-contrast, blueprint)", n);
                3
            }
        },
    }
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let code = match cli::parse(&args) {
        cli::Outcome::Print(s) => {
            print!("{}", s);
            0
        }
        cli::Outcome::Fail(s) => {
            eprint!("{}", s);
            3
        }
        cli::Outcome::Run(p) => match &p.cmd {
            cli::Cmd::Compile { input } => run_compile(input, &p.opts),
            cli::Cmd::Theme { name } => run_theme(name),
            cli::Cmd::Highlight { input: _, css: true } => {
                print!("{}", cli::HIGHLIGHT_CSS);
                0
            }
            cli::Cmd::Highlight { input: Some(input), css: false } => match read_input(input) {
                Ok(src) => {
                    print!("{}", highlight::highlight(&src));
                    0
                }
                Err(e) => {
                    eprintln!("{}", e);
                    2
                }
            },
            cli::Cmd::Fmt { input, check, stdout } => run_fmt(input, *check, *stdout),
            cli::Cmd::Desugar { input } => match read_input(input) {
                Ok(src) => {
                    let file = if input == "-" { "<stdin>".to_string() } else { input.clone() };
                    match desugar::desugar(&src) {
                        Ok(out) => {
                            print!("{}", out);
                            0
                        }
                        Err(e) => {
                            eprintln!("{}", diag::render_text(&file, &src, &e));
                            1
                        }
                    }
                }
                Err(e) => {
                    eprintln!("{}", e);
                    2
                }
            },
            _ => 0,
        },
    };
    let _ = std::io::stdout().flush();
    std::process::exit(code);
}

// Tokenizer for Lini source. The whole file is lexed up front; the first
// lexical error aborts the compile.

use crate::diag::{Diag, Span};

#[derive(Debug, Clone, PartialEq)]
pub enum Tok {
    Ident(String),
    Num(f64, String),
    Str(String),
    Hash(String),  // '#' followed by word chars (id or colour)
    Var(String),   // '--name'
    Class(String), // '.name'
    Bar,           // '|'
    BarBar,        // '||'
    LBrace,
    RBrace,
    LBrack,
    RBrack,
    LParen,
    RParen,
    Semi,
    Colon,
    DColon,
    Comma,
    Dot,
    Eq,
    Amp,
    Op(String),     // math operator: + - * / ^ % ? ! < > <= >= == != && ||
    LinkOp(String), // link operator such as '->' '-o<' '~>'
    DimOp(String),  // '(-)' or '(o)'
    Percent(f64, String),
    Newline,
    Eof,
}

#[derive(Debug, Clone)]
pub struct Token {
    pub tok: Tok,
    pub span: Span,
    pub space_before: bool,
}

#[derive(Debug, Clone)]
pub struct Comment {
    pub text: String, // including the leading '//'
    pub span: Span,
    pub own_line: bool,
}

pub struct Lexed {
    pub tokens: Vec<Token>,
    pub comments: Vec<Comment>,
}

fn is_ident_start(c: char) -> bool {
    c.is_ascii_alphabetic() || c == '_'
}
fn is_ident_char(c: char) -> bool {
    c.is_ascii_alphanumeric() || c == '_' || c == '-'
}

pub fn lex(src: &str) -> Result<Lexed, Diag> {
    let chars: Vec<(usize, char)> = src.char_indices().collect();
    let n = chars.len();
    let byte_at = |i: usize| -> usize { if i < n { chars[i].0 } else { src.len() } };
    let ch = |i: usize| -> char { if i < n { chars[i].1 } else { '\0' } };
    let mut toks: Vec<Token> = Vec::new();
    let mut comments = Vec::new();
    let mut i = 0usize;
    let mut paren_depth: i32 = 0;
    let mut space_before = true;
    let mut line_start = true;
    while i < n {
        let c = ch(i);
        let start = i;
        let sp = |a: usize, b: usize| Span::new(byte_at(a), byte_at(b));
        match c {
            ' ' | '\t' | '\r' => {
                i += 1;
                space_before = true;
                continue;
            }
            '\n' => {
                toks.push(Token { tok: Tok::Newline, span: sp(i, i + 1), space_before });
                i += 1;
                space_before = true;
                line_start = true;
                continue;
            }
            '/' if ch(i + 1) == '/' => {
                let mut j = i;
                while j < n && ch(j) != '\n' {
                    j += 1;
                }
                let text: String = chars[i..j].iter().map(|x| x.1).collect();
                comments.push(Comment { text, span: sp(i, j), own_line: line_start });
                i = j;
                space_before = true;
                continue;
            }
            _ => {}
        }
        line_start = false;
        let tok: Tok;
        if c == '"' {
            let mut s = String::new();
            let mut j = i + 1;
            loop {
                if j >= n {
                    return Err(Diag::error("unterminated-string", "unterminated string literal", sp(i, j)));
                }
                let d = ch(j);
                if d == '"' {
                    j += 1;
                    break;
                }
                if d == '\\' {
                    let e = ch(j + 1);
                    match e {
                        'n' => s.push('\n'),
                        't' => s.push('\t'),
                        '"' => s.push('"'),
                        '\\' => s.push('\\'),
                        _ => {
                            let shown: String = if j + 1 < n { format!("\\{}", e) } else { "\\".to_string() };
                            return Err(Diag::error(
                                "bad-escape",
                                &format!("invalid escape sequence '{}'", shown),
                                sp(j, (j + 2).min(n)),
                            ));
                        }
                    }
                    j += 2;
                    continue;
                }
                s.push(d);
                j += 1;
            }
            tok = Tok::Str(s);
            i = j;
        } else if c == '\'' {
            return Err(Diag::error("single-quote", "single quotes are not strings — use \"…\"", sp(i, i + 1)));
        } else if c.is_ascii_digit() || (c == '.' && ch(i + 1).is_ascii_digit()) {
            let (t, j) = lex_number(&chars, i, false);
            tok = t;
            i = j;
        } else if c == '-' && (ch(i + 1).is_ascii_digit() || (ch(i + 1) == '.' && ch(i + 2).is_ascii_digit()))
            && neg_allowed(&toks, space_before)
        {
            let (t, j) = lex_number(&chars, i, true);
            tok = t;
            i = j;
        } else if is_ident_start(c) {
            let mut j = i;
            while j < n && is_ident_char(ch(j)) {
                j += 1;
            }
            tok = Tok::Ident(chars[i..j].iter().map(|x| x.1).collect());
            i = j;
        } else if c == '#' {
            let mut j = i + 1;
            while j < n && is_ident_char(ch(j)) {
                j += 1;
            }
            tok = Tok::Hash(chars[i + 1..j].iter().map(|x| x.1).collect());
            i = j;
        } else if c == '.' {
            if is_ident_start(ch(i + 1)) {
                let mut j = i + 1;
                while j < n && is_ident_char(ch(j)) {
                    j += 1;
                }
                let name: String = chars[i + 1..j].iter().map(|x| x.1).collect();
                if space_before || toks.is_empty() || !prev_is_word(&toks) {
                    tok = Tok::Class(name);
                } else {
                    // path separator: emit Dot and continue lexing the name next round
                    toks.push(Token { tok: Tok::Dot, span: sp(i, i + 1), space_before });
                    space_before = false;
                    tok = Tok::Ident(name);
                    toks.push(Token { tok, span: sp(i + 1, j), space_before: false });
                    i = j;
                    continue;
                }
                i = j;
            } else {
                tok = Tok::Dot;
                i += 1;
            }
        } else if c == '|' {
            if ch(i + 1) == '|' {
                tok = Tok::BarBar;
                i += 2;
            } else {
                tok = Tok::Bar;
                i += 1;
            }
        } else if c == '{' {
            tok = Tok::LBrace;
            i += 1;
        } else if c == '}' {
            tok = Tok::RBrace;
            i += 1;
        } else if c == '[' {
            tok = Tok::LBrack;
            i += 1;
        } else if c == ']' {
            tok = Tok::RBrack;
            i += 1;
        } else if c == '(' {
            if paren_depth == 0 && (ch(i + 1) == '-' || ch(i + 1) == 'o') && ch(i + 2) == ')' {
                tok = Tok::DimOp(format!("({})", ch(i + 1)));
                i += 3;
            } else {
                paren_depth += 1;
                tok = Tok::LParen;
                i += 1;
            }
        } else if c == ')' {
            paren_depth -= 1;
            tok = Tok::RParen;
            i += 1;
        } else if c == ';' {
            tok = Tok::Semi;
            i += 1;
        } else if c == ',' {
            tok = Tok::Comma;
            i += 1;
        } else if c == ':' {
            if ch(i + 1) == ':' {
                tok = Tok::DColon;
                i += 2;
            } else {
                tok = Tok::Colon;
                i += 1;
            }
        } else if c == '&' {
            if paren_depth > 0 && ch(i + 1) == '&' {
                tok = Tok::Op("&&".into());
                i += 2;
            } else {
                tok = Tok::Amp;
                i += 1;
            }
        } else if c == '=' {
            if ch(i + 1) == '=' {
                tok = Tok::Op("==".into());
                i += 2;
            } else if paren_depth == 0 && ch(i + 1) == '>' {
                // '=' then '>' : '>' starts a link op that needs a line
                tok = Tok::Eq;
                i += 1;
            } else {
                tok = Tok::Eq;
                i += 1;
            }
        } else if c == '-' && ch(i + 1) == '-' && is_ident_start(ch(i + 2)) && paren_depth >= 0 && !link_context(&toks) {
            let mut j = i + 2;
            while j < n && is_ident_char(ch(j)) {
                j += 1;
            }
            tok = Tok::Var(chars[i + 2..j].iter().map(|x| x.1).collect());
            i = j;
        } else if paren_depth > 0 && "+-*/^%?!<>".contains(c) {
            let two: String = [c, ch(i + 1)].iter().collect();
            if two == "<=" || two == ">=" || two == "!=" {
                tok = Tok::Op(two);
                i += 2;
            } else {
                tok = Tok::Op(c.to_string());
                i += 1;
            }
        } else if "-<>~+*".contains(c) || (c == 'o' && false) {
            match lex_link_op(&chars, i)? {
                Some((op, j)) => {
                    tok = Tok::LinkOp(op);
                    i = j;
                }
                None => {
                    tok = Tok::Op(c.to_string());
                    i += 1;
                }
            }
        } else if "/^%?!".contains(c) {
            tok = Tok::Op(c.to_string());
            i += 1;
        } else {
            return Err(Diag::error("unexpected-char", &format!("unexpected character '{}'", c), sp(i, i + 1)));
        }
        toks.push(Token { tok, span: Span::new(byte_at(start), byte_at(i)), space_before });
        space_before = false;
    }
    toks.push(Token { tok: Tok::Eof, span: Span::new(src.len(), src.len()), space_before: true });
    Ok(Lexed { tokens: toks, comments })
}

fn prev_is_word(toks: &[Token]) -> bool {
    match toks.last().map(|t| &t.tok) {
        Some(Tok::Ident(_)) | Some(Tok::Bar) | Some(Tok::RParen) | Some(Tok::Hash(_)) => true,
        _ => false,
    }
}

fn link_context(_toks: &[Token]) -> bool {
    false
}

fn neg_allowed(toks: &[Token], space_before: bool) -> bool {
    if space_before {
        return true;
    }
    match toks.last().map(|t| &t.tok) {
        Some(Tok::Ident(_)) | Some(Tok::Num(..)) | Some(Tok::RParen) | Some(Tok::Str(_)) => false,
        _ => true,
    }
}

fn lex_number(chars: &[(usize, char)], i: usize, neg: bool) -> (Tok, usize) {
    let n = chars.len();
    let ch = |k: usize| -> char { if k < n { chars[k].1 } else { '\0' } };
    let mut j = if neg { i + 1 } else { i };
    while j < n && ch(j).is_ascii_digit() {
        j += 1;
    }
    if ch(j) == '.' && ch(j + 1).is_ascii_digit() {
        j += 1;
        while j < n && ch(j).is_ascii_digit() {
            j += 1;
        }
    }
    let text: String = chars[i..j].iter().map(|x| x.1).collect();
    let v: f64 = text.parse().unwrap_or(0.0);
    if ch(j) == '%' {
        let t2: String = chars[i..j + 1].iter().map(|x| x.1).collect();
        return (Tok::Percent(v, t2), j + 1);
    }
    (Tok::Num(v, text), j)
}

// Link operators: [left end] line [right end].
fn lex_link_op(chars: &[(usize, char)], i: usize) -> Result<Option<(String, usize)>, Diag> {
    let n = chars.len();
    let ch = |k: usize| -> char { if k < n { chars[k].1 } else { '\0' } };
    let byte_at = |k: usize| -> usize { if k < n { chars[k].0 } else { chars.last().map(|x| x.0 + x.1.len_utf8()).unwrap_or(0) } };
    let mut j = i;
    // left end
    let c = ch(j);
    let mut left = String::new();
    match c {
        '<' | '*' => {
            left.push(c);
            j += 1;
        }
        '>' => {
            left.push(c);
            j += 1;
            if ch(j) == 'o' || ch(j) == '+' {
                left.push(ch(j));
                j += 1;
            }
        }
        '+' => {
            left.push(c);
            j += 1;
            if ch(j) == 'o' {
                left.push('o');
                j += 1;
            }
        }
        _ => {}
    }
    // line
    let line_start = j;
    if ch(j) == '-' {
        while ch(j) == '-' && j - line_start < 3 {
            j += 1;
        }
    } else if ch(j) == '~' {
        j += 1;
    }
    if j == line_start {
        if !left.is_empty() {
            let last = left.chars().last().unwrap();
            return Err(Diag::error(
                "bad-link-op",
                &format!("expected link-op line after '{}'", last),
                Span::new(byte_at(i), byte_at(j)),
            ));
        }
        return Ok(None);
    }
    // right end
    let mut right = String::new();
    match ch(j) {
        '>' | '*' => {
            right.push(ch(j));
            j += 1;
        }
        '<' => {
            right.push('<');
            j += 1;
        }
        '+' => {
            right.push('+');
            j += 1;
            if ch(j) == '<' {
                right.push('<');
                j += 1;
            }
        }
        'o' if ch(j + 1) == '<' || ch(j + 1) == '+' => {
            right.push('o');
            right.push(ch(j + 1));
            j += 2;
        }
        _ => {}
    }
    let line: String = chars[line_start..j - right.chars().count()].iter().map(|x| x.1).collect();
    Ok(Some((format!("{}{}{}", left, line, right), j)))
}

// Syntax tree for a Lini document.

use crate::diag::Span;

#[derive(Debug, Clone)]
pub struct Doc {
    pub sheet: Option<Sheet>,
    pub stmts: Vec<Stmt>,
}

#[derive(Debug, Clone)]
pub struct Sheet {
    pub items: Vec<SheetItem>,
    pub span: Span,
}

#[derive(Debug, Clone)]
pub enum SheetItem {
    Decl(Decl),
    Var(Decl),
    Binding(Binding),
    Rule(Rule),
    Define(Define),
}

#[derive(Debug, Clone)]
pub struct Decl {
    pub name: String,
    pub name_span: Span,
    pub value: Value,
    pub span: Span,
}

#[derive(Debug, Clone)]
pub struct Binding {
    pub name: String,
    pub params: Option<Vec<String>>,
    pub expr: Term,
    pub span: Span,
}

#[derive(Debug, Clone)]
pub struct Rule {
    pub selector: Vec<Compound>,
    pub decls: Vec<Decl>,
    pub span: Span,
}

#[derive(Debug, Clone, Default)]
pub struct Compound {
    pub bars: bool,
    pub type_name: Option<String>, // '-' for the link selector |-|
    pub id: Option<String>,
    pub classes: Vec<String>,
    pub span: Span,
}

#[derive(Debug, Clone)]
pub struct Define {
    pub name: String,
    pub base: String,
    pub decls: Vec<Decl>,
    pub body: Option<Vec<Stmt>>,
    pub span: Span,
    pub head_span: Span,
}

#[derive(Debug, Clone)]
pub struct Value {
    // comma-separated groups, each a space-separated run of terms
    pub groups: Vec<Vec<Term>>,
    pub span: Span,
}

#[derive(Debug, Clone)]
pub enum Term {
    Num(f64, String, Span),
    Percent(f64, String, Span),
    Ident(String, Span),
    Str(String, Span),
    Hash(String, Span),
    Var(String, Span),
    Call(String, Vec<Expr>, Span),
    Group(Expr, Span),
    Tagged(Box<Term>, String, Span), // term ':' tag (draw segment names)
}

impl Term {
    pub fn span(&self) -> Span {
        match self {
            Term::Num(_, _, s)
            | Term::Percent(_, _, s)
            | Term::Ident(_, s)
            | Term::Str(_, s)
            | Term::Hash(_, s)
            | Term::Var(_, s)
            | Term::Call(_, _, s)
            | Term::Group(_, s)
            | Term::Tagged(_, _, s) => *s,
        }
    }
}

#[derive(Debug, Clone)]
pub enum Expr {
    Num(f64, Span),
    Percent(f64, Span),
    Ident(String, Span),
    Str(String, Span),
    Var(String, Span),
    Hash(String, Span),
    Call(String, Vec<Expr>, Span),
    Unary(String, Box<Expr>, Span),
    Bin(String, Box<Expr>, Box<Expr>, Span),
    Ternary(Box<Expr>, Box<Expr>, Box<Expr>, Span),
    Tuple(Vec<Expr>, Span),
    Block(Vec<(String, Expr)>, Box<Expr>, Span), // (a = 1; b = 2; expr)
}

impl Expr {
    pub fn span(&self) -> Span {
        match self {
            Expr::Num(_, s)
            | Expr::Percent(_, s)
            | Expr::Ident(_, s)
            | Expr::Str(_, s)
            | Expr::Var(_, s)
            | Expr::Hash(_, s)
            | Expr::Call(_, _, s)
            | Expr::Unary(_, _, s)
            | Expr::Bin(_, _, _, s)
            | Expr::Ternary(_, _, _, s)
            | Expr::Tuple(_, s)
            | Expr::Block(_, _, s) => *s,
        }
    }
}

