use std::io::{Read, Write};

#[derive(Default, Clone)]
pub struct Options {
    pub output: Option<String>,
    pub format: String,
    pub static_: bool,
    pub embed_font: bool,
    pub check: bool,
    pub json: bool,
    pub theme: Option<String>,
    pub no_fs: bool,
    pub no_warn: bool,
    pub strict: bool,
    pub watch: bool,
}

fn read_input(path: &str) -> Result<String, String> {
    if path == "-" {
        let mut s = String::new();
        std::io::stdin().read_to_string(&mut s).map_err(|e| format!("error: <stdin>: {}", e))?;
        return Ok(s);
    }
    match std::fs::read(path) {
        Ok(b) => Ok(String::from_utf8_lossy(&b).into_owned()),
        Err(e) => Err(format!("error: {}: {}", path, e)),
    }
}

pub fn compile_src(src: &str, file: &str, opts: &Options) -> Result<(String, Vec<diag::Diag>), (diag::Diag, Vec<diag::Diag>)> {
    let (doc, _comments) = parser::parse(src).map_err(|e| (e, vec![]))?;
    let sheet = scene::build_sheet(&doc).map_err(|e| (e, vec![]))?;
    let root = compile::root_decls_node(&sheet);
    let mut b = scene::Builder::new(&sheet);
    b.add(root, None);
    b.build_stmts(&doc.stmts, 0).map_err(|e| (e, vec![]))?;
    let nodes = std::mem::take(&mut b.nodes);
    drop(b);
    let mut ctx = compile::Ctx {
        src: src.to_string(),
        file: file.to_string(),
        sheet,
        nodes,
        comp: vec![],
        links: vec![],
        warnings: vec![],
        root_font_size: 15.0,
    };
    compile::compute(&mut ctx);
    ctx.root_font_size = ctx.comp[0].font_size;
    layout::measure(&mut ctx, 0, None);
    let svg = render::render(&ctx, opts).map_err(|e| (e, vec![]))?;
    Ok((svg, ctx.warnings))
}

fn write_out(opts: &Options, text: &str) {
    match &opts.output {
        Some(path) if path != "-" => {
            let _ = std::fs::write(path, text.as_bytes());
        }
        _ => {
            let mut so = std::io::stdout();
            let _ = so.write_all(text.as_bytes());
        }
    }
}

fn html_wrap(svg: &str) -> String {
    format!(
        "<!doctype html>\n<html>\n<head>\n  <meta charset=\"utf-8\">\n  <title>lini</title>\n</head>\n<body>\n{}</body>\n</html>\n",
        svg
    )
}

fn run_compile(input: &str, opts: &Options) -> i32 {
    if opts.format != "svg" && opts.format != "html" {
        eprintln!("error: invalid --format '{}' (expected svg|html)", opts.format);
        return 3;
    }
    if let Some(t) = &opts.theme {
        if theme::resolve(t).is_none() {
            eprintln!(
                "error: theme '{}': not a built-in (try: default, light, dark, high-contrast, blueprint), and reading it as a file failed: No such file or directory (os error 2)",
                t
            );
            return 2;
        }
    }
    let src = match read_input(input) {
        Ok(s) => s,
        Err(e) => {
            eprintln!("{}", e);
            return 2;
        }
    };
    let file = if input == "-" { "<stdin>".to_string() } else { input.to_string() };
    let result = compile_src(&src, &file, opts);
    if opts.json {
        let (diags, failed) = match &result {
            Ok((_, w)) => (w.clone(), false),
            Err((e, w)) => {
                let mut d = w.clone();
                d.push(e.clone());
                (d, true)
            }
        };
        print!("{}", diag::render_json(&file, &src, &diags));
        if failed || (opts.strict && !diags.is_empty()) {
            return 1;
        }
        return 0;
    }
    match result {
        Ok((svg, warns)) => {
            if !opts.no_warn {
                for w in &warns {
                    eprintln!("{}", diag::render_text(&file, &src, w));
                }
            }
            if !opts.check {
                let text = if opts.format == "html" { html_wrap(&svg) } else { svg };
                write_out(opts, &text);
            }
            if opts.strict && !warns.is_empty() {
                return 1;
            }
            0
        }
        Err((e, warns)) => {
            if !opts.no_warn {
                for w in &warns {
                    eprintln!("{}", diag::render_text(&file, &src, w));
                }
            }
            eprintln!("{}", diag::render_text(&file, &src, &e));
            1
        }
    }
}

fn run_fmt(input: &str, check: bool, stdout: bool) -> i32 {
    let src = match read_input(input) {
        Ok(s) => s,
        Err(e) => {
            eprintln!("{}", e);
            return 2;
        }
    };
    let file = if input == "-" { "<stdin>".to_string() } else { input.to_string() };
    let out = match format::format(&src) {
        Ok(o) => o,
        Err(e) => {
            eprintln!("{}", diag::render_text(&file, &src, &e));
            return 1;
        }
    };
    if check {
        if out != src {
            eprintln!("{}: would reformat", file);
            return 1;
        }
        return 0;
    }
    if stdout || input == "-" {
        print!("{}", out);
        return 0;
    }
    if out != src {
        let _ = std::fs::write(input, out.as_bytes());
    }
    0
}

fn run_theme(name: &Option<String>) -> i32 {
    match name {
        None => {
            print!("{}", theme::LIST);
            0
        }
        Some(n) => match theme::css_of(n) {
            Some(css) => {
                print!("{}", css);
                0
            }
            None => {
                eprintln!("error: unknown theme '{}' (try one of: default, light, dark, high-contrast, blueprint)", n);
                3
            }
        },
    }
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let code = match cli::parse(&args) {
        cli::Outcome::Print(s) => {
            print!("{}", s);
            0
        }
        cli::Outcome::Fail(s) => {
            eprint!("{}", s);
            3
        }
        cli::Outcome::Run(p) => match &p.cmd {
            cli::Cmd::Compile { input } => run_compile(input, &p.opts),
            cli::Cmd::Theme { name } => run_theme(name),
            cli::Cmd::Highlight { input: _, css: true } => {
                print!("{}", cli::HIGHLIGHT_CSS);
                0
            }
            cli::Cmd::Highlight { input: Some(input), css: false } => match read_input(input) {
                Ok(src) => {
                    print!("{}", highlight::highlight(&src));
                    0
                }
                Err(e) => {
                    eprintln!("{}", e);
                    2
                }
            },
            cli::Cmd::Fmt { input, check, stdout } => run_fmt(input, *check, *stdout),
            cli::Cmd::Desugar { input } => match read_input(input) {
                Ok(src) => {
                    let file = if input == "-" { "<stdin>".to_string() } else { input.clone() };
                    match desugar::desugar(&src) {
                        Ok(out) => {
                            print!("{}", out);
                            0
                        }
                        Err(e) => {
                            eprintln!("{}", diag::render_text(&file, &src, &e));
                            1
                        }
                    }
                }
                Err(e) => {
                    eprintln!("{}", e);
                    2
                }
            },
            _ => 0,
        },
    };
    let _ = std::io::stdout().flush();
    std::process::exit(code);
}

// Tokenizer for Lini source. The whole file is lexed up front; the first
// lexical error aborts the compile.

use crate::diag::{Diag, Span};

#[derive(Debug, Clone, PartialEq)]
pub enum Tok {
    Ident(String),
    Num(f64, String),
    Str(String),
    Hash(String),  // '#' followed by word chars (id or colour)
    Var(String),   // '--name'
    Class(String), // '.name'
    Bar,           // '|'
    BarBar,        // '||'
    LBrace,
    RBrace,
    LBrack,
    RBrack,
    LParen,
    RParen,
    Semi,
    Colon,
    DColon,
    Comma,
    Dot,
    Eq,
    Amp,
    Op(String),     // math operator: + - * / ^ % ? ! < > <= >= == != && ||
    LinkOp(String), // link operator such as '->' '-o<' '~>'
    DimOp(String),  // '(-)' or '(o)'
    Percent(f64, String),
    Newline,
    Eof,
}

#[derive(Debug, Clone)]
pub struct Token {
    pub tok: Tok,
    pub span: Span,
    pub space_before: bool,
}

#[derive(Debug, Clone)]
pub struct Comment {
    pub text: String, // including the leading '//'
    pub span: Span,
    pub own_line: bool,
}

pub struct Lexed {
    pub tokens: Vec<Token>,
    pub comments: Vec<Comment>,
}

fn is_ident_start(c: char) -> bool {
    c.is_ascii_alphabetic() || c == '_'
}
fn is_ident_char(c: char) -> bool {
    c.is_ascii_alphanumeric() || c == '_' || c == '-'
}

pub fn lex(src: &str) -> Result<Lexed, Diag> {
    let chars: Vec<(usize, char)> = src.char_indices().collect();
    let n = chars.len();
    let byte_at = |i: usize| -> usize { if i < n { chars[i].0 } else { src.len() } };
    let ch = |i: usize| -> char { if i < n { chars[i].1 } else { '\0' } };
    let mut toks: Vec<Token> = Vec::new();
    let mut comments = Vec::new();
    let mut i = 0usize;
    let mut paren_depth: i32 = 0;
    let mut space_before = true;
    let mut line_start = true;
    while i < n {
        let c = ch(i);
        let start = i;
        let sp = |a: usize, b: usize| Span::new(byte_at(a), byte_at(b));
        match c {
            ' ' | '\t' | '\r' => {
                i += 1;
                space_before = true;
                continue;
            }
            '\n' => {
                toks.push(Token { tok: Tok::Newline, span: sp(i, i + 1), space_before });
                i += 1;
                space_before = true;
                line_start = true;
                continue;
            }
            '/' if ch(i + 1) == '/' => {
                let mut j = i;
                while j < n && ch(j) != '\n' {
                    j += 1;
                }
                let text: String = chars[i..j].iter().map(|x| x.1).collect();
                comments.push(Comment { text, span: sp(i, j), own_line: line_start });
                i = j;
                space_before = true;
                continue;
            }
            _ => {}
        }
        line_start = false;
        let tok: Tok;
        if c == '"' {
            let mut s = String::new();
            let mut j = i + 1;
            loop {
                if j >= n {
                    return Err(Diag::error("unterminated-string", "unterminated string literal", sp(i, j)));
                }
                let d = ch(j);
                if d == '"' {
                    j += 1;
                    break;
                }
                if d == '\\' {
                    let e = ch(j + 1);
                    match e {
                        'n' => s.push('\n'),
                        't' => s.push('\t'),
                        '"' => s.push('"'),
                        '\\' => s.push('\\'),
                        _ => {
                            let shown: String = if j + 1 < n { format!("\\{}", e) } else { "\\".to_string() };
                            return Err(Diag::error(
                                "bad-escape",
                                &format!("invalid escape sequence '{}'", shown),
                                sp(j, (j + 2).min(n)),
                            ));
                        }
                    }
                    j += 2;
                    continue;
                }
                s.push(d);
                j += 1;
            }
            tok = Tok::Str(s);
            i = j;
        } else if c == '\'' {
            return Err(Diag::error("single-quote", "single quotes are not strings — use \"…\"", sp(i, i + 1)));
        } else if c.is_ascii_digit() || (c == '.' && ch(i + 1).is_ascii_digit()) {
            let (t, j) = lex_number(&chars, i, false);
            tok = t;
            i = j;
        } else if c == '-' && (ch(i + 1).is_ascii_digit() || (ch(i + 1) == '.' && ch(i + 2).is_ascii_digit()))
            && neg_allowed(&toks, space_before)
        {
            let (t, j) = lex_number(&chars, i, true);
            tok = t;
            i = j;
        } else if is_ident_start(c) {
            let mut j = i;
            while j < n && is_ident_char(ch(j)) {
                j += 1;
            }
            tok = Tok::Ident(chars[i..j].iter().map(|x| x.1).collect());
            i = j;
        } else if c == '#' {
            let mut j = i + 1;
            while j < n && is_ident_char(ch(j)) {
                j += 1;
            }
            tok = Tok::Hash(chars[i + 1..j].iter().map(|x| x.1).collect());
            i = j;
        } else if c == '.' {
            if is_ident_start(ch(i + 1)) {
                let mut j = i + 1;
                while j < n && is_ident_char(ch(j)) {
                    j += 1;
                }
                let name: String = chars[i + 1..j].iter().map(|x| x.1).collect();
                if space_before || toks.is_empty() || !prev_is_word(&toks) {
                    tok = Tok::Class(name);
                } else {
                    // path separator: emit Dot and continue lexing the name next round
                    toks.push(Token { tok: Tok::Dot, span: sp(i, i + 1), space_before });
                    space_before = false;
                    tok = Tok::Ident(name);
                    toks.push(Token { tok, span: sp(i + 1, j), space_before: false });
                    i = j;
                    continue;
                }
                i = j;
            } else {
                tok = Tok::Dot;
                i += 1;
            }
        } else if c == '|' {
            if ch(i + 1) == '|' {
                tok = Tok::BarBar;
                i += 2;
            } else {
                tok = Tok::Bar;
                i += 1;
            }
        } else if c == '{' {
            tok = Tok::LBrace;
            i += 1;
        } else if c == '}' {
            tok = Tok::RBrace;
            i += 1;
        } else if c == '[' {
            tok = Tok::LBrack;
            i += 1;
        } else if c == ']' {
            tok = Tok::RBrack;
            i += 1;
        } else if c == '(' {
            if paren_depth == 0 && (ch(i + 1) == '-' || ch(i + 1) == 'o') && ch(i + 2) == ')' {
                tok = Tok::DimOp(format!("({})", ch(i + 1)));
                i += 3;
            } else {
                paren_depth += 1;
                tok = Tok::LParen;
                i += 1;
            }
        } else if c == ')' {
            paren_depth -= 1;
            tok = Tok::RParen;
            i += 1;
        } else if c == ';' {
            tok = Tok::Semi;
            i += 1;
        } else if c == ',' {
            tok = Tok::Comma;
            i += 1;
        } else if c == ':' {
            if ch(i + 1) == ':' {
                tok = Tok::DColon;
                i += 2;
            } else {
                tok = Tok::Colon;
                i += 1;
            }
        } else if c == '&' {
            if paren_depth > 0 && ch(i + 1) == '&' {
                tok = Tok::Op("&&".into());
                i += 2;
            } else {
                tok = Tok::Amp;
                i += 1;
            }
        } else if c == '=' {
            if ch(i + 1) == '=' {
                tok = Tok::Op("==".into());
                i += 2;
            } else if paren_depth == 0 && ch(i + 1) == '>' {
                // '=' then '>' : '>' starts a link op that needs a line
                tok = Tok::Eq;
                i += 1;
            } else {
                tok = Tok::Eq;
                i += 1;
            }
        } else if c == '-' && ch(i + 1) == '-' && is_ident_start(ch(i + 2)) && paren_depth >= 0 && !link_context(&toks) {
            let mut j = i + 2;
            while j < n && is_ident_char(ch(j)) {
                j += 1;
            }
            tok = Tok::Var(chars[i + 2..j].iter().map(|x| x.1).collect());
            i = j;
        } else if paren_depth > 0 && "+-*/^%?!<>".contains(c) {
            let two: String = [c, ch(i + 1)].iter().collect();
            if two == "<=" || two == ">=" || two == "!=" {
                tok = Tok::Op(two);
                i += 2;
            } else {
                tok = Tok::Op(c.to_string());
                i += 1;
            }
        } else if "-<>~+*".contains(c) || (c == 'o' && false) {
            match lex_link_op(&chars, i)? {
                Some((op, j)) => {
                    tok = Tok::LinkOp(op);
                    i = j;
                }
                None => {
                    tok = Tok::Op(c.to_string());
                    i += 1;
                }
            }
        } else if "/^%?!".contains(c) {
            tok = Tok::Op(c.to_string());
            i += 1;
        } else {
            return Err(Diag::error("unexpected-char", &format!("unexpected character '{}'", c), sp(i, i + 1)));
        }
        toks.push(Token { tok, span: Span::new(byte_at(start), byte_at(i)), space_before });
        space_before = false;
    }
    toks.push(Token { tok: Tok::Eof, span: Span::new(src.len(), src.len()), space_before: true });
    Ok(Lexed { tokens: toks, comments })
}

fn prev_is_word(toks: &[Token]) -> bool {
    match toks.last().map(|t| &t.tok) {
        Some(Tok::Ident(_)) | Some(Tok::Bar) | Some(Tok::RParen) | Some(Tok::Hash(_)) => true,
        _ => false,
    }
}

fn link_context(_toks: &[Token]) -> bool {
    false
}

fn neg_allowed(toks: &[Token], space_before: bool) -> bool {
    if space_before {
        return true;
    }
    match toks.last().map(|t| &t.tok) {
        Some(Tok::Ident(_)) | Some(Tok::Num(..)) | Some(Tok::RParen) | Some(Tok::Str(_)) => false,
        _ => true,
    }
}

fn lex_number(chars: &[(usize, char)], i: usize, neg: bool) -> (Tok, usize) {
    let n = chars.len();
    let ch = |k: usize| -> char { if k < n { chars[k].1 } else { '\0' } };
    let mut j = if neg { i + 1 } else { i };
    while j < n && ch(j).is_ascii_digit() {
        j += 1;
    }
    if ch(j) == '.' && ch(j + 1).is_ascii_digit() {
        j += 1;
        while j < n && ch(j).is_ascii_digit() {
            j += 1;
        }
    }
    let text: String = chars[i..j].iter().map(|x| x.1).collect();
    let v: f64 = text.parse().unwrap_or(0.0);
    if ch(j) == '%' {
        let t2: String = chars[i..j + 1].iter().map(|x| x.1).collect();
        return (Tok::Percent(v, t2), j + 1);
    }
    (Tok::Num(v, text), j)
}

// Link operators: [left end] line [right end].
fn lex_link_op(chars: &[(usize, char)], i: usize) -> Result<Option<(String, usize)>, Diag> {
    let n = chars.len();
    let ch = |k: usize| -> char { if k < n { chars[k].1 } else { '\0' } };
    let byte_at = |k: usize| -> usize { if k < n { chars[k].0 } else { chars.last().map(|x| x.0 + x.1.len_utf8()).unwrap_or(0) } };
    let mut j = i;
    // left end
    let c = ch(j);
    let mut left = String::new();
    match c {
        '<' | '*' => {
            left.push(c);
            j += 1;
        }
        '>' => {
            left.push(c);
            j += 1;
            if ch(j) == 'o' || ch(j) == '+' {
                left.push(ch(j));
                j += 1;
            }
        }
        '+' => {
            left.push(c);
            j += 1;
            if ch(j) == 'o' {
                left.push('o');
                j += 1;
            }
        }
        _ => {}
    }
    // line
    let line_start = j;
    if ch(j) == '-' {
        while ch(j) == '-' && j - line_start < 3 {
            j += 1;
        }
    } else if ch(j) == '~' {
        j += 1;
    }
    if j == line_start {
        if !left.is_empty() {
            let last = left.chars().last().unwrap();
            return Err(Diag::error(
                "bad-link-op",
                &format!("expected link-op line after '{}'", last),
                Span::new(byte_at(i), byte_at(j)),
            ));
        }
        return Ok(None);
    }
    // right end
    let mut right = String::new();
    match ch(j) {
        '>' | '*' => {
            right.push(ch(j));
            j += 1;
        }
        '<' => {
            right.push('<');
            j += 1;
        }
        '+' => {
            right.push('+');
            j += 1;
            if ch(j) == '<' {
                right.push('<');
                j += 1;
            }
        }
        'o' if ch(j + 1) == '<' || ch(j + 1) == '+' => {
            right.push('o');
            right.push(ch(j + 1));
            j += 2;
        }
        _ => {}
    }
    let line: String = chars[line_start..j - right.chars().count()].iter().map(|x| x.1).collect();
    Ok(Some((format!("{}{}{}", left, line, right), j)))
}

// Syntax tree for a Lini document.

use crate::diag::Span;

#[derive(Debug, Clone)]
pub struct Doc {
    pub sheet: Option<Sheet>,
    pub stmts: Vec<Stmt>,
}

#[derive(Debug, Clone)]
pub struct Sheet {
    pub items: Vec<SheetItem>,
    pub span: Span,
}

#[derive(Debug, Clone)]
pub enum SheetItem {
    Decl(Decl),
    Var(Decl),
    Binding(Binding),
    Rule(Rule),
    Define(Define),
}

#[derive(Debug, Clone)]
pub struct Decl {
    pub name: String,
    pub name_span: Span,
    pub value: Value,
    pub span: Span,
}

#[derive(Debug, Clone)]
pub struct Binding {
    pub name: String,
    pub params: Option<Vec<String>>,
    pub expr: Term,
    pub span: Span,
}

#[derive(Debug, Clone)]
pub struct Rule {
    pub selector: Vec<Compound>,
    pub decls: Vec<Decl>,
    pub span: Span,
}

#[derive(Debug, Clone, Default)]
pub struct Compound {
    pub bars: bool,
    pub type_name: Option<String>, // '-' for the link selector |-|
    pub id: Option<String>,
    pub classes: Vec<String>,
    pub span: Span,
}

#[derive(Debug, Clone)]
pub struct Define {
    pub name: String,
    pub base: String,
    pub decls: Vec<Decl>,
    pub body: Option<Vec<Stmt>>,
    pub span: Span,
    pub head_span: Span,
}

#[derive(Debug, Clone)]
pub struct Value {
    // comma-separated groups, each a space-separated run of terms
    pub groups: Vec<Vec<Term>>,
    pub span: Span,
}

#[derive(Debug, Clone)]
pub enum Term {
    Num(f64, String, Span),
    Percent(f64, String, Span),
    Ident(String, Span),
    Str(String, Span),
    Hash(String, Span),
    Var(String, Span),
    Call(String, Vec<Expr>, Span),
    Group(Expr, Span),
    Tagged(Box<Term>, String, Span), // term ':' tag (draw segment names)
}

impl Term {
    pub fn span(&self) -> Span {
        match self {
            Term::Num(_, _, s)
            | Term::Percent(_, _, s)
            | Term::Ident(_, s)
            | Term::Str(_, s)
            | Term::Hash(_, s)
            | Term::Var(_, s)
            | Term::Call(_, _, s)
            | Term::Group(_, s)
            | Term::Tagged(_, _, s) => *s,
        }
    }
}

#[derive(Debug, Clone)]
pub enum Expr {
    Num(f64, Span),
    Percent(f64, Span),
    Ident(String, Span),
    Str(String, Span),
    Var(String, Span),
    Hash(String, Span),
    Call(String, Vec<Expr>, Span),
    Unary(String, Box<Expr>, Span),
    Bin(String, Box<Expr>, Box<Expr>, Span),
    Ternary(Box<Expr>, Box<Expr>, Box<Expr>, Span),
    Tuple(Vec<Expr>, Span),
    Block(Vec<(String, Expr)>, Box<Expr>, Span), // (a = 1; b = 2; expr)
}

impl Expr {
    pub fn span(&self) -> Span {
        match self {
            Expr::Num(_, s)
            | Expr::Percent(_, s)
            | Expr::Ident(_, s)
            | Expr::Str(_, s)
            | Expr::Var(_, s)
            | Expr::Hash(_, s)
            | Expr::Call(_, _, s)
            | Expr::Unary(_, _, s)
            | Expr::Bin(_, _, _, s)
            | Expr::Ternary(_, _, _, s)
            | Expr::Tuple(_, s)
            | Expr::Block(_, _, s) => *s,
        }
    }
}

#[derive(Debug, Clone)]
pub enum Stmt {
    Node(NodeStmt),
    Text(TextStmt),
    Link(LinkStmt),
}

#[derive(Debug, Clone)]
pub struct NodeStmt {
    pub type_name: Option<String>,
    pub id: Option<String>,
    pub label: Option<(String, Span)>,
    pub classes: Vec<String>,
    pub classes_span: Option<Span>,
    pub style: Option<Vec<Decl>>,
    pub style_span: Option<Span>,
    pub children: Option<Vec<Stmt>>,
    pub span: Span,
    pub head_span: Span,
}

#[derive(Debug, Clone)]
pub struct TextStmt {
    pub text: String,
    pub classes: Vec<String>,
    pub style: Option<Vec<Decl>>,
    pub span: Span,
}

#[derive(Debug, Clone)]
pub enum Endpoint {
    Path(PathRef),
    Node(Box<NodeStmt>),
    Text(String, Span),
}

#[derive(Debug, Clone)]
pub struct PathRef {
    pub parts: Vec<String>,
    pub index: Option<u32>,
    pub anchor: Option<String>,
    pub span: Span,
}

#[derive(Debug, Clone)]
pub struct LinkStmt {
    // groups[i] are fanned endpoints; ops[i] joins groups[i] and groups[i+1]
    pub groups: Vec<Vec<Endpoint>>,
    pub ops: Vec<(String, Span)>,
    pub label: Option<(String, Span)>,
    pub classes: Vec<String>,
    pub style: Option<Vec<Decl>>,
    pub labels: Option<Vec<Stmt>>,
    pub span: Span,
}
// Diagnostics: errors and warnings with stable codes and source spans.

#[derive(Debug, Clone, Copy, PartialEq, Default)]
pub struct Span {
    pub start: usize,
    pub end: usize,
}

impl Span {
    pub fn new(start: usize, end: usize) -> Span {
        Span { start, end }
    }
    pub fn to(self, other: Span) -> Span {
        Span { start: self.start.min(other.start), end: self.end.max(other.end) }
    }
}

#[derive(Debug, Clone, PartialEq)]
pub enum Severity {
    Error,
    Warning,
}

#[derive(Debug, Clone)]
pub struct Diag {
    pub family: String,
    pub severity: Severity,
    pub message: String,
    pub span: Span,
    pub fixes: Vec<Fix>,
}

#[derive(Debug, Clone)]
pub struct Fix {
    pub message: String,
    pub span: Span,
    pub replacement: String,
}

impl Diag {
    pub fn error(family: &str, message: &str, span: Span) -> Diag {
        Diag { family: family.to_string(), severity: Severity::Error, message: message.to_string(), span, fixes: vec![] }
    }
    pub fn warning(family: &str, message: &str, span: Span) -> Diag {
        Diag { family: family.to_string(), severity: Severity::Warning, message: message.to_string(), span, fixes: vec![] }
    }
    pub fn code(&self) -> &'static str {
        family_code(&self.family)
    }
}

pub fn family_code(family: &str) -> &'static str {
    match family {
        "lex" => "L000",
        "unterminated-string" => "L001",
        "bad-escape" => "L002",
        "unexpected-char" => "L004",
        "parse" => "P000",
        "declaration-outside-block" => "P004",
        "stylesheet-after-canvas" => "P005",
        "unknown-property" => "V001",
        "class-never-worn" => "V004",
        "malformed-value" => "V005",
        "invalid-color" => "V010",
        "resolve" => "R000",
        "unknown-type" => "R001",
        "unknown-class" => "R002",
        "duplicate-id" => "R003",
        "unknown-endpoint" => "R008",
        "chain-too-short" => "R009",
        "asset-not-found" => "R010",
        "layout" => "Y000",
        "missing-required-property" => "Y001",
        "chart-type" => "Y009",
        _ => "X000",
    }
}

// Line/column (1-based, columns counted in chars) of a byte offset.
pub fn line_col(src: &str, off: usize) -> (usize, usize) {
    let mut line = 1;
    let mut col = 1;
    for (i, c) in src.char_indices() {
        if i >= off {
            break;
        }
        if c == '\n' {
            line += 1;
            col = 1;
        } else {
            col += 1;
        }
    }
    (line, col)
}

pub fn render_text(file: &str, src: &str, d: &Diag) -> String {
    let (l, c) = line_col(src, d.span.start);
    let sev = match d.severity {
        Severity::Error => "error",
        Severity::Warning => "warning",
    };
    format!("{}:{}:{}: {}: {}", file, l, c, sev, d.message)
}

pub fn json_escape(s: &str) -> String {
    let mut o = String::new();
    for c in s.chars() {
        match c {
            '"' => o.push_str("\\\""),
            '\\' => o.push_str("\\\\"),
            '\n' => o.push_str("\\n"),
            '\r' => o.push_str("\\r"),
            '\t' => o.push_str("\\t"),
            c if (c as u32) < 0x20 => o.push_str(&format!("\\u{:04x}", c as u32)),
            c => o.push(c),
        }
    }
    o
}

pub fn render_json(file: &str, src: &str, diags: &[Diag]) -> String {
    let mut o = String::new();
    o.push_str("{\n");
    o.push_str(&format!("  \"file\": \"{}\",\n", json_escape(file)));
    if diags.is_empty() {
        o.push_str("  \"diagnostics\": []\n}\n");
        return o;
    }
    o.push_str("  \"diagnostics\": [\n");
    for (i, d) in diags.iter().enumerate() {
        let (l, c) = line_col(src, d.span.start);
        let (el, ec) = line_col(src, d.span.end);
        let sev = match d.severity {
            Severity::Error => "error",
            Severity::Warning => "warning",
        };
        o.push_str("    {\n");
        o.push_str(&format!("      \"code\": \"{}\",\n", d.code()));
        o.push_str(&format!("      \"family\": \"{}\",\n", json_escape(&d.family)));
        o.push_str(&format!("      \"severity\": \"{}\",\n", sev));
        o.push_str(&format!("      \"message\": \"{}\",\n", json_escape(&d.message)));
        o.push_str("      \"span\": {\n");
        o.push_str(&format!("        \"start\": {},\n", d.span.start));
        o.push_str(&format!("        \"end\": {},\n", d.span.end));
        o.push_str(&format!("        \"line\": {},\n", l));
        o.push_str(&format!("        \"col\": {},\n", c));
        o.push_str(&format!("        \"endLine\": {},\n", el));
        o.push_str(&format!("        \"endCol\": {}\n", ec));
        if d.fixes.is_empty() {
            o.push_str("      }\n");
        } else {
            o.push_str("      },\n");
            o.push_str("      \"fixes\": [\n");
            for (k, f) in d.fixes.iter().enumerate() {
                o.push_str("        {\n");
                o.push_str(&format!("          \"message\": \"{}\",\n", json_escape(&f.message)));
                o.push_str(&format!("          \"start\": {},\n", f.span.start));
                o.push_str(&format!("          \"end\": {},\n", f.span.end));
                o.push_str(&format!("          \"replacement\": \"{}\"\n", json_escape(&f.replacement)));
                o.push_str(if k + 1 < d.fixes.len() { "        },\n" } else { "        }\n" });
            }
            o.push_str("      ]\n");
        }
        o.push_str(if i + 1 < diags.len() { "    },\n" } else { "    }\n" });
    }
    o.push_str("  ]\n}\n");
    o
}

1	// Recursive-descent parser over the token stream.
2	
3	use crate::ast::*;
4	use crate::diag::{Diag, Span};
5	use crate::lexer::{Tok, Token};
6	
7	pub struct Parser<'a> {
8	    toks: &'a [Token],
9	    pos: usize,
10	    pub src: &'a str,
11	}
12	
13	type PResult<T> = Result<T, Diag>;
14	
15	fn perr(msg: &str, span: Span) -> Diag {
16	    Diag::error("parse", msg, span)
17	}
18	
19	pub const SEP_ERR: &str = "expected a newline, ';', or a closing bracket";
20	
21	impl<'a> Parser<'a> {
22	    pub fn new(toks: &'a [Token], src: &'a str) -> Self {
23	        Parser { toks, pos: 0, src }
24	    }
25	    fn peek(&self) -> &Tok {
26	        &self.toks[self.pos].tok
27	    }
28	    fn peek_at(&self, k: usize) -> &Tok {
29	        let i = (self.pos + k).min(self.toks.len() - 1);
30	        &self.toks[i].tok
31	    }
32	    fn tok(&self) -> &Token {
33	        &self.toks[self.pos]
34	    }
35	    fn tok_at(&self, k: usize) -> &Token {
36	        let i = (self.pos + k).min(self.toks.len() - 1);
37	        &self.toks[i]
38	    }
39	    fn span(&self) -> Span {
40	        self.toks[self.pos].span
41	    }
42	    fn prev_span(&self) -> Span {
43	        if self.pos == 0 {
44	            Span::new(0, 0)
45	        } else {
46	            self.toks[self.pos - 1].span
47	        }
48	    }
49	    fn bump(&mut self) -> Token {
50	        let t = self.toks[self.pos].clone();
51	        if self.pos < self.toks.len() - 1 {
52	            self.pos += 1;
53	        }
54	        t
55	    }
56	    fn skip_newlines(&mut self) {
57	        while matches!(self.peek(), Tok::Newline) {
58	            self.bump();
59	        }
60	    }
61	    fn skip_seps(&mut self) {
62	        while matches!(self.peek(), Tok::Newline | Tok::Semi) {
63	            self.bump();
64	        }
65	    }
66	
67	    pub fn parse_doc(&mut self) -> PResult<Doc> {
68	        self.skip_seps();
69	        let mut sheet = None;
70	        if matches!(self.peek(), Tok::LBrace) {
71	            sheet = Some(self.parse_sheet()?);
72	        }
73	        let mut stmts = Vec::new();
74	        loop {
75	            self.skip_seps();
76	            if matches!(self.peek(), Tok::Eof) {
77	                break;
78	            }
79	            if matches!(self.peek(), Tok::LBrace) {
80	                return Err(Diag::error(
81	                    "stylesheet-after-canvas",
82	                    "the stylesheet '{ }' must come first, before any instance",
83	                    self.span(),
84	                ));
85	            }
86	            let s = self.parse_stmt(false)?;
87	            stmts.push(s);
88	            self.expect_sep_or(&[Tok::Eof])?;
89	        }
90	        Ok(Doc { sheet, stmts })
91	    }
92	
93	    fn expect_sep_or(&mut self, closers: &[Tok]) -> PResult<()> {
94	        match self.peek() {
95	            Tok::Newline | Tok::Semi => Ok(()),
96	            t if closers.iter().any(|c| c == t) => Ok(()),
97	            Tok::Eof => Ok(()),
98	            Tok::RBrack | Tok::RBrace => Ok(()),
99	            _ => Err(perr(SEP_ERR, self.span())),
100	        }
101	    }
102	
103	    // ---------------------------------------------------------------- sheet
104	    fn parse_sheet(&mut self) -> PResult<Sheet> {
105	        let open = self.bump(); // {
106	        let mut items = Vec::new();
107	        loop {
108	            self.skip_seps();
109	            match self.peek() {
110	                Tok::RBrace => {
111	                    let close = self.bump();
112	                    return Ok(Sheet { items, span: open.span.to(close.span) });
113	                }
114	                Tok::Eof => return Err(perr("expected '}'", self.span())),
115	                _ => {}
116	            }
117	            let item = self.parse_sheet_item()?;
118	            let needs_semi = matches!(item, SheetItem::Decl(_) | SheetItem::Var(_));
119	            items.push(item);
120	            match self.peek() {
121	                Tok::Semi | Tok::Newline | Tok::RBrace => {}
122	                _ => {
123	                    if needs_semi {
124	                        return Err(perr("a declaration ends with ';'", self.span()));
125	                    }
126	                    return Err(perr(SEP_ERR, self.span()));
127	                }
128	            }
129	        }
130	    }
131	
132	    fn parse_sheet_item(&mut self) -> PResult<SheetItem> {
133	        let start = self.span();
134	        match self.peek().clone() {
135	            Tok::Var(name) => {
136	                let t = self.bump();
137	                if !matches!(self.peek(), Tok::Colon) {
138	                    return Err(perr("expected ':'", self.span()));
139	                }
140	                self.bump();
141	                let value = self.parse_value()?;
142	                let span = t.span.to(value.span);
143	                Ok(SheetItem::Var(Decl { name, name_span: t.span, value, span }))
144	            }
145	            Tok::Ident(name) => {
146	                // declaration, binding, or function binding
147	                match self.peek_at(1) {
148	                    Tok::Colon => {
149	                        let d = self.parse_decl()?;
150	                        Ok(SheetItem::Decl(d))
151	                    }
152	                    Tok::Eq => {
153	                        self.bump();
154	                        self.bump();
155	                        let expr = self.parse_term_for_binding()?;
156	                        let span = start.to(expr.span());
157	                        Ok(SheetItem::Binding(Binding { name, params: None, expr, span }))
158	                    }
159	                    Tok::LParen => {
160	                        self.bump();
161	                        self.bump();
162	                        let mut params = Vec::new();
163	                        loop {
164	                            match self.peek().clone() {
165	                                Tok::Ident(p) => {
166	                                    self.bump();
167	                                    params.push(p);
168	                                }
169	                                Tok::RParen => {}
170	                                _ => return Err(perr("expected identifier", self.span())),
171	                            }
172	                            match self.peek() {
173	                                Tok::Comma => {
174	                                    self.bump();
175	                                }
176	                                Tok::RParen => {
177	                                    self.bump();
178	                                    break;
179	                                }
180	                                _ => return Err(perr("expected ')'", self.span())),
181	                            }
182	                        }
183	                        if !matches!(self.peek(), Tok::Eq) {
184	                            return Err(perr("expected '='", self.span()));
185	                        }
186	                        self.bump();
187	                        let expr = self.parse_term_for_binding()?;
188	                        let span = start.to(expr.span());
189	                        Ok(SheetItem::Binding(Binding { name, params: Some(params), expr, span }))
190	                    }
191	                    _ => {
192	                        self.bump();
193	                        Err(perr("expected ':'", self.span()))
194	                    }
195	                }
196	            }
197	            Tok::Bar | Tok::Class(_) | Tok::Hash(_) => self.parse_rule_or_define(),
198	            _ => Err(perr("expected a declaration, rule, or binding", self.span())),
199	        }
200	    }
201	
202	    fn parse_term_for_binding(&mut self) -> PResult<Term> {
203	        let t = self.parse_term()?;
204	        Ok(t)
205	    }
206	
207	    fn parse_rule_or_define(&mut self) -> PResult<SheetItem> {
208	        let start = self.span();
209	        // define: |name::base|
210	        if matches!(self.peek(), Tok::Bar) {
211	            if let (Tok::Ident(name), Tok::DColon) = (self.peek_at(1).clone(), self.peek_at(2).clone()) {
212	                self.bump();
213	                self.bump();
214	                self.bump();
215	                let base = match self.peek().clone() {
216	                    Tok::Ident(b) => {
217	                        self.bump();
218	                        b
219	                    }
220	                    _ => return Err(perr("expected identifier", self.span())),
221	                };
222	                if !matches!(self.peek(), Tok::Bar) {
223	                    return Err(perr("expected '|'", self.span()));
224	                }
225	                let bar = self.bump();
226	                let head_span = start.to(bar.span);
227	                let mut decls = Vec::new();
228	                if matches!(self.peek(), Tok::LBrace) {
229	                    decls = self.parse_style_block()?.0;
230	                }
231	                let mut body = None;
232	                if matches!(self.peek(), Tok::LBrack) {
233	                    body = Some(self.parse_children()?);
234	                }
235	                let span = start.to(self.prev_span());
236	                return Ok(SheetItem::Define(Define { name, base, decls, body, span, head_span }));
237	            }
238	        }
239	        let mut selector = Vec::new();
240	        loop {
241	            match self.peek() {
242	                Tok::Bar | Tok::Class(_) | Tok::Hash(_) => {
243	                    let c = self.parse_compound()?;
244	                    selector.push(c);
245	                }
246	                Tok::LBrace => break,
247	                _ => return Err(perr("expected '{'", self.span())),
248	            }
249	        }
250	        let (decls, _) = self.parse_style_block()?;
251	        let span = start.to(self.prev_span());
252	        Ok(SheetItem::Rule(Rule { selector, decls, span }))
253	    }
254	
255	    fn parse_compound(&mut self) -> PResult<Compound> {
256	        let start = self.span();
257	        let mut c = Compound::default();
258	        if matches!(self.peek(), Tok::Bar) {
259	            self.bump();
260	            c.bars = true;
261	            match self.peek().clone() {
262	                Tok::Ident(t) => {
263	                    self.bump();
264	                    c.type_name = Some(t);
265	                }
266	                Tok::LinkOp(op) if op == "-" => {
267	                    self.bump();
268	                    c.type_name = Some("-".to_string());
269	                }
270	                _ => {}
271	            }
272	            if let Tok::Hash(h) = self.peek().clone() {
273	                self.bump();
274	                c.id = Some(h);
275	            }
276	            if !matches!(self.peek(), Tok::Bar) {
277	                if c.type_name.is_none() && c.id.is_none() {
278	                    return Err(perr("'| |' needs a type or an '#id'", start));
279	                }
280	                return Err(perr("expected '|'", self.span()));
281	            }
282	            self.bump();
283	            if c.type_name.is_none() && c.id.is_none() {
284	                return Err(perr("'| |' needs a type or an '#id'", start));
285	            }
286	        } else if let Tok::Hash(h) = self.peek().clone() {
287	            self.bump();
288	            c.id = Some(h);
289	        }
290	        while let Tok::Class(cl) = self.peek().clone() {
291	            if self.tok().space_before && (c.bars || c.id.is_some() || !c.classes.is_empty()) {
292	                break;
293	            }
294	            self.bump();
295	            c.classes.push(cl);
296	        }
297	        c.span = start.to(self.prev_span());
298	        Ok(c)
299	    }
300	
301	    // { decl; decl; } -> (decls, span)
302	    pub fn parse_style_block(&mut self) -> PResult<(Vec<Decl>, Span)> {
303	        let open = self.bump(); // {
304	        let mut decls = Vec::new();
305	        loop {
306	            self.skip_seps();
307	            match self.peek() {
308	                Tok::RBrace => {
309	                    let close = self.bump();
310	                    return Ok((decls, open.span.to(close.span)));
311	                }
312	                Tok::Eof => return Err(perr("expected '}'", self.span())),
313	                Tok::Ident(_) => {
314	                    let d = self.parse_decl()?;
315	                    decls.push(d);
316	                    match self.peek() {
317	                        Tok::Semi | Tok::RBrace | Tok::Newline => {}
318	                        _ => return Err(perr("a declaration ends with ';'", self.span())),
319	                    }
320	                }
321	                Tok::Var(_) => {
322	                    return Err(perr("variables are declared in the stylesheet '{ }'", self.span()));
323	                }
324	                _ => return Err(perr("expected a property name", self.span())),
325	            }
326	        }
327	    }
328	
329	    fn parse_decl(&mut self) -> PResult<Decl> {
330	        let t = self.bump();
331	        let name = match &t.tok {
332	            Tok::Ident(n) => n.clone(),
333	            _ => unreachable!(),
334	        };
335	        if !matches!(self.peek(), Tok::Colon) {
336	            return Err(perr("expected ':'", self.span()));
337	        }
338	        self.bump();
339	        let value = self.parse_value()?;
340	        let span = t.span.to(value.span);
341	        Ok(Decl { name, name_span: t.span, value, span })
342	    }
343	
344	    // value := group (',' group)* ; group := term+ ; newlines are ignored
345	    pub fn parse_value(&mut self) -> PResult<Value> {
346	        let start = self.span();
347	        let mut groups = Vec::new();
348	        let mut cur: Vec<Term> = Vec::new();
349	        loop {
350	            self.skip_newlines();
351	            match self.peek() {
352	                Tok::Semi | Tok::RBrace | Tok::Eof => break,
353	                Tok::Comma => {
354	                    if cur.is_empty() {
355	                        return Err(perr("expected a value", self.span()));
356	                    }
357	                    self.bump();
358	                    groups.push(std::mem::take(&mut cur));
359	                    continue;
360	                }
361	                Tok::Colon if !cur.is_empty() => {
362	                    // a term tag (draw segment name)
363	                    self.bump();
364	                    match self.peek().clone() {
365	                        Tok::Ident(tag) => {
366	                            let ts = self.bump().span;
367	                            let last = cur.pop().unwrap();
368	                            let sp = last.span().to(ts);
369	                            cur.push(Term::Tagged(Box::new(last), tag, sp));
370	                        }
371	                        _ => return Err(perr("expected identifier", self.span())),
372	                    }
373	                    continue;
374	                }
375	                _ => {}
376	            }
377	            let t = self.parse_term()?;
378	            cur.push(t);
379	        }
380	        if cur.is_empty() {
381	            if groups.is_empty() {
382	                return Err(perr("expected a value", self.span()));
383	            }
384	            return Err(perr("expected a value", self.span()));
385	        }
386	        groups.push(cur);
387	        let end = self.prev_span();
388	        Ok(Value { groups, span: start.to(end) })
389	    }
390	
391	    fn parse_term(&mut self) -> PResult<Term> {
392	        let t = self.tok().clone();
393	        match &t.tok {
394	            Tok::Num(v, s) => {
395	                self.bump();
396	                Ok(Term::Num(*v, s.clone(), t.span))
397	            }
398	            Tok::Percent(v, s) => {
399	                self.bump();
400	                Ok(Term::Percent(*v, s.clone(), t.span))
401	            }
402	            Tok::Str(s) => {
403	                self.bump();
404	                Ok(Term::Str(s.clone(), t.span))
405	            }
406	            Tok::Hash(h) => {
407	                self.bump();
408	                Ok(Term::Hash(h.clone(), t.span))
409	            }
410	            Tok::Var(v) => {
411	                self.bump();
412	                Ok(Term::Var(v.clone(), t.span))
413	            }
414	            Tok::Ident(name) => {
415	                self.bump();
416	                if matches!(self.peek(), Tok::LParen) && !self.tok().space_before {
417	                    self.bump();
418	                    let args = self.parse_call_args()?;
419	                    let sp = t.span.to(self.prev_span());
420	                    return Ok(Term::Call(name.clone(), args, sp));
421	                }
422	                Ok(Term::Ident(name.clone(), t.span))
423	            }
424	            Tok::LParen => {
425	                self.bump();
426	                let e = self.parse_group_body()?;
427	                let sp = t.span.to(self.prev_span());
428	                Ok(Term::Group(e, sp))
429	            }
430	            Tok::LinkOp(_) | Tok::Op(_) => Err(perr("to compute here, wrap the math in a group — e.g. (a - b)", t.span)),
431	            _ => Err(perr("expected a value", t.span)),
432	        }
433	    }
434	
435	    // after '(' of a call: args separated by commas until ')'
436	    fn parse_call_args(&mut self) -> PResult<Vec<Expr>> {
437	        let mut args = Vec::new();
438	        self.skip_newlines();
439	        if matches!(self.peek(), Tok::RParen) {
440	            self.bump();
441	            return Ok(args);
442	        }
443	        loop {
444	            self.skip_newlines();
445	            let e = self.parse_expr()?;
446	            args.push(e);
447	            self.skip_newlines();
448	            match self.peek() {
449	                Tok::Comma => {
450	                    self.bump();
451	                }
452	                Tok::RParen => {
453	                    self.bump();
454	                    return Ok(args);
455	                }
456	                _ => return Err(perr("expected ')'", self.span())),
457	            }
458	        }
459	    }
460	
461	    // after '(' of a group: expr, tuple, or a block of local bindings
462	    fn parse_group_body(&mut self) -> PResult<Expr> {
463	        let start = self.prev_span();
464	        let mut locals = Vec::new();
465	        loop {
466	            self.skip_newlines();
467	            if let (Tok::Ident(name), Tok::Eq) = (self.peek().clone(), self.peek_at(1).clone()) {
468	                self.bump();
469	                self.bump();
470	                let e = self.parse_expr()?;
471	                locals.push((name, e));
472	                self.skip_newlines();
473	                if matches!(self.peek(), Tok::Semi) {
474	                    self.bump();
475	                }
476	                continue;
477	            }
478	            break;
479	        }
480	        let first = self.parse_expr()?;
481	        self.skip_newlines();
482	        let mut items = vec![first];
483	        while matches!(self.peek(), Tok::Comma) {
484	            self.bump();
485	            self.skip_newlines();
486	            items.push(self.parse_expr()?);
487	            self.skip_newlines();
488	        }
489	        if !matches!(self.peek(), Tok::RParen) {
490	            return Err(perr("expected ')'", self.span()));
491	        }
492	        let close = self.bump();
493	        let sp = start.to(close.span);
494	        let body = if items.len() == 1 { items.pop().unwrap() } else { Expr::Tuple(items, sp) };
495	        if locals.is_empty() {
496	            Ok(body)
497	        } else {
498	            Ok(Expr::Block(locals, Box::new(body), sp))
499	        }
500	    }
501	
502	    // ------------------------------------------------------------- expressions
503	    pub fn parse_expr(&mut self) -> PResult<Expr> {
504	        self.parse_ternary()
505	    }
506	    fn parse_ternary(&mut self) -> PResult<Expr> {
507	        let c = self.parse_binary(0)?;
508	        self.skip_newlines();
509	        if matches!(self.peek(), Tok::Op(o) if o == "?") {
510	            self.bump();
511	            self.skip_newlines();
512	            let a = self.parse_ternary()?;
513	            self.skip_newlines();
514	            if !matches!(self.peek(), Tok::Colon) {
515	                return Err(perr("expected ':'", self.span()));
516	            }
517	            self.bump();
518	            self.skip_newlines();
519	            let b = self.parse_ternary()?;
520	            let sp = c.span().to(b.span());
521	            return Ok(Expr::Ternary(Box::new(c), Box::new(a), Box::new(b), sp));
522	        }
523	        Ok(c)
524	    }
525	    fn binop_prec(t: &Tok) -> Option<(&'static str, u8)> {
526	        match t {
527	            Tok::Op(o) => match o.as_str() {
528	                "||" => Some(("||", 1)),
529	                "&&" => Some(("&&", 2)),
530	                "==" => Some(("==", 3)),
531	                "!=" => Some(("!=", 3)),
532	                "<" => Some(("<", 4)),
533	                ">" => Some((">", 4)),
534	                "<=" => Some(("<=", 4)),
535	                ">=" => Some((">=", 4)),
536	                "+" => Some(("+", 5)),
537	                "-" => Some(("-", 5)),
538	                "*" => Some(("*", 6)),
539	                "/" => Some(("/", 6)),
540	                "%" => Some(("%", 6)),
541	                "^" => Some(("^", 8)),
542	                _ => None,
543	            },
544	            Tok::BarBar => Some(("||", 1)),
545	            _ => None,
546	        }
547	    }
548	    fn parse_binary(&mut self, min: u8) -> PResult<Expr> {
549	        let mut lhs = self.parse_unary()?;
550	        loop {
551	            self.skip_newlines();
552	            // a negative literal directly after an operand reads as subtraction
553	            if let Tok::Num(v, _) = self.peek().clone() {
554	                if v < 0.0 || self.tok().span.start < self.src.len() && self.src[self.tok().span.start..].starts_with('-') {
555	                    if 5 >= min && v <= 0.0 {
556	                        let t = self.bump();
557	                        let rhs_v = -v;
558	                        let mut rhs = Expr::Num(rhs_v, t.span);
559	                        // continue with higher-precedence ops binding to rhs
560	                        rhs = self.continue_binary(rhs, 6)?;
561	                        let sp = lhs.span().to(rhs.span());
562	                        lhs = Expr::Bin("-".into(), Box::new(lhs), Box::new(rhs), sp);
563	                        continue;
564	                    }
565	                }
566	            }
567	            let (op, prec) = match Self::binop_prec(self.peek()) {
568	                Some(x) => x,
569	                None => break,
570	            };
571	            if prec < min {
572	                break;
573	            }
574	            self.bump();
575	            self.skip_newlines();
576	            // ^ is right-associative
577	            let next_min = if op == "^" { prec } else { prec + 1 };
578	            let rhs = self.parse_binary(next_min)?;
579	            let sp = lhs.span().to(rhs.span());
580	            lhs = Expr::Bin(op.to_string(), Box::new(lhs), Box::new(rhs), sp);
581	        }
582	        Ok(lhs)
583	    }
584	    fn continue_binary(&mut self, mut lhs: Expr, min: u8) -> PResult<Expr> {
585	        loop {
586	            self.skip_newlines();
587	            let (op, prec) = match Self::binop_prec(self.peek()) {
588	                Some(x) => x,
589	                None => break,
590	            };
591	            if prec < min {
592	                break;
593	            }
594	            self.bump();
595	            self.skip_newlines();
596	            let next_min = if op == "^" { prec } else { prec + 1 };
597	            let rhs = self.parse_binary(next_min)?;
598	            let sp = lhs.span().to(rhs.span());
599	            lhs = Expr::Bin(op.to_string(), Box::new(lhs), Box::new(rhs), sp);
600	        }
601	        Ok(lhs)
602	    }
603	    fn parse_unary(&mut self) -> PResult<Expr> {
604	        let t = self.tok().clone();
605	        match &t.tok {
606	            Tok::Op(o) if o == "-" || o == "!" || o == "+" => {
607	                self.bump();
608	                let e = self.parse_unary_pow()?;
609	                let sp = t.span.to(e.span());
610	                Ok(Expr::Unary(o.clone(), Box::new(e), sp))
611	            }
612	            _ => self.parse_postfix(),
613	        }
614	    }
615	    // unary minus binds looser than ^ : -x^2 = -(x^2)
616	    fn parse_unary_pow(&mut self) -> PResult<Expr> {
617	        let base = self.parse_unary()?;
618	        self.skip_newlines();
619	        if matches!(self.peek(), Tok::Op(o) if o == "^") {
620	            self.bump();
621	            let rhs = self.parse_binary(8)?;
622	            let sp = base.span().to(rhs.span());
623	            return Ok(Expr::Bin("^".into(), Box::new(base), Box::new(rhs), sp));
624	        }
625	        Ok(base)
626	    }
627	    fn parse_postfix(&mut self) -> PResult<Expr> {
628	        let t = self.tok().clone();
629	        match &t.tok {
630	            Tok::Num(v, _) => {
631	                self.bump();
632	                Ok(Expr::Num(*v, t.span))
633	            }
634	            Tok::Percent(v, _) => {
635	                self.bump();
636	                Ok(Expr::Percent(*v, t.span))
637	            }
638	            Tok::Str(s) => {
639	                self.bump();
640	                Ok(Expr::Str(s.clone(), t.span))
641	            }
642	            Tok::Var(v) => {
643	                self.bump();
644	                Ok(Expr::Var(v.clone(), t.span))
645	            }
646	            Tok::Hash(h) => {
647	                self.bump();
648	                Ok(Expr::Hash(h.clone(), t.span))
649	            }
650	            Tok::Ident(name) => {
651	                self.bump();
652	                if matches!(self.peek(), Tok::LParen) {
653	                    self.bump();
654	                    let args = self.parse_call_args()?;
655	                    let sp = t.span.to(self.prev_span());
656	                    return Ok(Expr::Call(name.clone(), args, sp));
657	                }
658	                Ok(Expr::Ident(name.clone(), t.span))
659	            }
660	            Tok::LParen => {
661	                self.bump();
662	                let e = self.parse_group_body()?;
663	                Ok(e)
664	            }
665	            _ => Err(perr("expected a value", t.span)),
666	        }
667	    }
668	
669	    // ------------------------------------------------------------- statements
670	    fn parse_children(&mut self) -> PResult<Vec<Stmt>> {
671	        self.bump(); // [
672	        let mut out = Vec::new();
673	        loop {
674	            self.skip_seps();
675	            match self.peek() {
676	                Tok::RBrack => {
677	                    self.bump();
678	                    return Ok(out);
679	                }
680	                Tok::Eof => return Err(perr("expected ']'", self.span())),
681	                _ => {}
682	            }
683	            let s = self.parse_stmt(true)?;
684	            out.push(s);
685	            match self.peek() {
686	                Tok::Newline | Tok::Semi | Tok::RBrack => {}
687	                // several bare strings may share a line inside [ ]
688	                Tok::Str(_) if matches!(out.last(), Some(Stmt::Text(_))) => {}
689	                _ => return Err(perr(SEP_ERR, self.span())),
690	            }
691	        }
692	    }
693	
694	    fn parse_stmt(&mut self, _in_children: bool) -> PResult<Stmt> {
695	        let start = self.span();
696	        match self.peek().clone() {
697	            Tok::Bar => {
698	                let node = self.parse_node()?;
699	                if matches!(self.peek(), Tok::LinkOp(_) | Tok::Amp | Tok::DimOp(_) | Tok::BarBar) {
700	                    return Err(perr(SEP_ERR, self.span()));
701	                }
702	                Ok(Stmt::Node(node))
703	            }
704	            Tok::Str(s) => {
705	                self.bump();
706	                let mut classes = Vec::new();
707	                while let Tok::Class(c) = self.peek().clone() {
708	                    self.bump();
709	                    classes.push(c);
710	                }
711	                let mut style = None;
712	                if matches!(self.peek(), Tok::LBrace) {
713	                    style = Some(self.parse_style_block()?.0);
714	                }
715	                Ok(Stmt::Text(TextStmt { text: s, classes, style, span: start.to(self.prev_span()) }))
716	            }
717	            Tok::Ident(_) => self.parse_link(),
718	            Tok::Var(_) => Err(perr("variables are declared in the stylesheet '{ }'", start)),
719	            _ => Err(perr("a node leads with bars — write '|box#X|' (a bare name is a link endpoint)", start)),
720	        }
721	    }
722	
723	    fn parse_node(&mut self) -> PResult<NodeStmt> {
724	        let start = self.span();
725	        self.bump(); // |
726	        let mut type_name = None;
727	        let mut id = None;
728	        if let Tok::Ident(t) = self.peek().clone() {
729	            self.bump();
730	            type_name = Some(t);
731	        }
732	        if let Tok::Hash(h) = self.peek().clone() {
733	            self.bump();
734	            id = Some(h);
735	        }
