764	    fn parse_node_tail(&mut self, node: &mut NodeStmt) -> PResult<()> {
765	        if let Tok::Str(s) = self.peek().clone() {
766	            let t = self.bump();
767	            node.label = Some((s, t.span));
768	            if matches!(self.peek(), Tok::Str(_)) {
769	                return Err(perr("one inline label — put two or more in a '[ ]'", self.span()));
770	            }
771	        }
772	        if let Tok::Class(_) = self.peek() {
773	            let cs = self.span();
774	            while let Tok::Class(c) = self.peek().clone() {
775	                if self.tok().space_before && !node.classes.is_empty() {
776	                    return Err(perr("classes glue into a chain — write '.hot.loud', no space", self.span()));
777	                }
778	                self.bump();
779	                node.classes.push(c);
780	            }
781	            node.classes_span = Some(cs.to(self.prev_span()));
782	            if matches!(self.peek(), Tok::Str(_)) {
783	                return Err(perr("a label comes before classes — write '|box| \"X\" .hot'", self.span()));
784	            }
785	        }
786	        if matches!(self.peek(), Tok::LBrace) {
787	            let (d, sp) = self.parse_style_block()?;
788	            node.style = Some(d);
789	            node.style_span = Some(sp);
790	            if matches!(self.peek(), Tok::Str(_)) {
791	                return Err(perr("a label comes before classes — write '|box| \"X\" .hot'", self.span()));
792	            }
793	        }
794	        if matches!(self.peek(), Tok::LBrack) {
795	            node.children = Some(self.parse_children()?);
796	        }
797	        Ok(())
798	    }
