800	    fn parse_path(&mut self) -> PResult<PathRef> {
801	        let start = self.span();
802	        let mut parts = Vec::new();
803	        match self.peek().clone() {
804	            Tok::Ident(n) => {
805	                self.bump();
806	                parts.push(n);
807	            }
808	            _ => return Err(perr("expected identifier", self.span())),
809	        }
810	        let mut index = None;
811	        loop {
812	            match self.peek().clone() {
813	                Tok::Dot => {
814	                    self.bump();
815	                    match self.peek().clone() {
816	                        Tok::Ident(n) => {
817	                            self.bump();
818	                            parts.push(n);
819	                        }
820	                        Tok::Num(v, _) => {
821	                            self.bump();
822	                            index = Some(v as u32);
823	                            break;
824	                        }
825	                        _ => return Err(perr("expected identifier", self.span())),
826	                    }
827	                }
828	                Tok::Num(v, s) if s.starts_with('.') && !self.tok().space_before => {
829	                    self.bump();
830	                    let digits = &s[1..];
831	                    index = Some(digits.parse::<u32>().unwrap_or(v as u32));
832	                    break;
833	                }
834	                _ => break,
835	            }
836	        }
837	        let mut anchor = None;
838	        if matches!(self.peek(), Tok::Colon) {
839	            self.bump();
840	            match self.peek().clone() {
841	                Tok::Ident(a) => {
842	                    self.bump();
843	                    anchor = Some(a);
844	                }
845	                _ => return Err(perr("expected identifier", self.span())),
846	            }
847	        }
848	        Ok(PathRef { parts, index, anchor, span: start.to(self.prev_span()) })
849	    }
