851	    fn parse_endpoint(&mut self) -> PResult<Endpoint> {
852	        match self.peek().clone() {
853	            Tok::Ident(_) => Ok(Endpoint::Path(self.parse_path()?)),
854	            Tok::Bar => {
855	                let start = self.span();
856	                self.bump();
857	                let mut type_name = None;
858	                let mut id = None;
859	                if let Tok::Ident(t) = self.peek().clone() {
860	                    self.bump();
861	                    type_name = Some(t);
862	                }
863	                if let Tok::Hash(h) = self.peek().clone() {
864	                    self.bump();
865	                    id = Some(h);
866	                }
867	                if !matches!(self.peek(), Tok::Bar) {
868	                    if type_name.is_none() && id.is_none() {
869	                        return Err(perr("'| |' needs a type or an '#id'", start));
870	                    }
871	                    return Err(perr("expected '|'", self.span()));
872	                }
873	                let bar = self.bump();
874	                if type_name.is_none() && id.is_none() {
875	                    return Err(perr("'| |' needs a type or an '#id'", start));
876	                }
877	                let head_span = start.to(bar.span);
878	                Ok(Endpoint::Node(Box::new(NodeStmt {
879	                    type_name,
880	                    id,
881	                    label: None,
882	                    classes: vec![],
883	                    classes_span: None,
884	                    style: None,
885	                    style_span: None,
886	                    children: None,
887	                    span: head_span,
888	                    head_span,
889	                })))
