899	    fn parse_fan(&mut self) -> PResult<Vec<Endpoint>> {
900	        let mut eps = vec![self.parse_endpoint()?];
901	        while matches!(self.peek(), Tok::Amp) {
902	            self.bump();
903	            eps.push(self.parse_endpoint()?);
904	        }
905	        Ok(eps)
906	    }
