908	    fn parse_link(&mut self) -> PResult<Stmt> {
909	        let start = self.span();
910	        let first = self.parse_fan()?;
911	        let mut groups = vec![first];
912	        let mut ops = Vec::new();
913	        loop {
914	            match self.peek().clone() {
915	                Tok::LinkOp(op) | Tok::DimOp(op) => {
916	                    let t = self.bump();
917	                    ops.push((op, t.span));
918	                }
919	                Tok::BarBar => {
920	                    let t = self.bump();
921	                    ops.push(("||".to_string(), t.span));
922	                }
923	                _ => break,
924	            }
925	            // one-ended forms: 'a (o)' or 'a <- "text"'
926	            match self.peek() {
927	                Tok::Ident(_) | Tok::Bar => {
928	                    groups.push(self.parse_fan()?);
929	                }
930	                _ => break,
931	            }
932	        }
933	        if ops.is_empty() {
934	            // a bare endpoint, or something that looks like a declaration
935	            let had_colon = groups[0].iter().any(|e| matches!(e, Endpoint::Path(p) if p.anchor.is_some()));
936	            if had_colon || matches!(self.peek(), Tok::Colon) {
937	                return Err(Diag::error("declaration-outside-block", "a declaration belongs in a '{ }' block", start));
938	            }
939	            return Err(perr("a node leads with bars — write '|box#X|' (a bare name is a link endpoint)", start));
940	        }
941	        let mut link = LinkStmt {
942	            groups,
943	            ops,
944	            label: None,
945	            classes: vec![],
946	            style: None,
947	            labels: None,
948	            span: start,
949	        };
950	        if let Tok::Str(s) = self.peek().clone() {
951	            let t = self.bump();
952	            link.label = Some((s, t.span));
953	            if matches!(self.peek(), Tok::Str(_)) {
954	                return Err(perr("one inline label — put two or more in a '[ ]'", self.span()));
955	            }
956	        }
957	        while let Tok::Class(c) = self.peek().clone() {
958	            if self.tok().space_before && !link.classes.is_empty() {
959	                return Err(perr("classes glue into a chain — write '.hot.loud', no space", self.span()));
960	            }
961	            self.bump();
962	            link.classes.push(c);
963	        }
964	        if matches!(self.peek(), Tok::Str(_)) {
965	            return Err(perr("a label comes before classes — write '|box| \"X\" .hot'", self.span()));
966	        }
967	        if matches!(self.peek(), Tok::LBrace) {
968	            link.style = Some(self.parse_style_block()?.0);
969	            if matches!(self.peek(), Tok::Str(_)) {
970	                return Err(perr("a label comes before classes — write '|box| \"X\" .hot'", self.span()));
971	            }
972	        }
973	        if matches!(self.peek(), Tok::LBrack) {
974	            link.labels = Some(self.parse_children()?);
975	        }
976	        link.span = start.to(self.prev_span());
977	        Ok(Stmt::Link(link))
978	    }
979	}
