// Tokenizer for `lini fmt`. It mirrors the compiler's lexical rules but keeps
// what the pretty-printer needs: exact source offsets, whether whitespace came
// before a token, and every `//` comment with its position.

use crate::diag::{Diag, Span};

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum K {
    Ident,
    Num,
    Percent,
    Str,
    Hash,
    Var,
    Dot,
    Bar,
    BarBar,
    LBrace,
    RBrace,
    LBrack,
    RBrack,
    LParen,
    RParen,
    Semi,
    Colon,
    DColon,
    Comma,
    Eq,
    Amp,
    Math, // + - * / ^ ? < > <= >= == != && inside ( ); * / ^ outside
    Link, // link operator: -> <-> -o< ~> ...
    Dim,  // (-) (o) (<)
    Newline,
    Eof,
}

#[derive(Clone, Debug)]
pub struct Tok {
    pub k: K,
    pub s: usize,
    pub e: usize,
    pub sp: bool, // whitespace (or a line start) right before the token
    pub v: f64,
    // Ident / Hash (without '#') / Var (without '--') name, decoded string,
    // operator text, or the number's source text.
    pub text: String,
}

#[derive(Clone, Debug)]
pub struct Comment {
    pub s: usize,
    pub e: usize,
    pub text: String, // trailing whitespace trimmed
    pub own_line: bool,
}

pub struct Lexed {
    pub toks: Vec<Tok>,
    pub comments: Vec<Comment>,
}

fn is_ident_start(c: char) -> bool {
    c.is_ascii_alphabetic() || c == '_'
}

fn is_ident_char(c: char) -> bool {
    c.is_ascii_alphanumeric() || c == '_' || c == '-'
}

fn err(msg: &str, s: usize, e: usize) -> Diag {
    Diag::error("lex", msg, Span::new(s, e))
}

pub fn lex(src: &str) -> Result<Lexed, Diag> {
    let cs: Vec<(usize, char)> = src.char_indices().collect();
    let n = cs.len();
    let at = |i: usize| -> char { if i < n { cs[i].1 } else { '\0' } };
    let off = |i: usize| -> usize { if i < n { cs[i].0 } else { src.len() } };
    let mut toks: Vec<Tok> = Vec::new();
    let mut comments: Vec<Comment> = Vec::new();
    let mut i = 0usize;
    let mut depth: usize = 0;
    let mut sp = true;
    let mut line_start = true;
    // a run of newlines yields one Newline token; a comment ends the run
    let mut in_nl_run = false;
    while i < n {
        let c = at(i);
        match c {
            ' ' | '\t' | '\r' => {
                i += 1;
                sp = true;
                continue;
            }
            '\n' => {
                if !in_nl_run {
                    toks.push(Tok { k: K::Newline, s: off(i), e: off(i + 1), sp, v: 0.0, text: String::new() });
                    in_nl_run = true;
                }
                i += 1;
                sp = true;
                line_start = true;
                continue;
            }
            '/' if at(i + 1) == '/' => {
                let mut j = i;
                while j < n && at(j) != '\n' {
                    j += 1;
                }
                let text: String = src[off(i)..off(j)].trim_end().to_string();
                comments.push(Comment { s: off(i), e: off(j), text, own_line: line_start });
                in_nl_run = false;
                i = j;
                sp = true;
                continue;
            }
            _ => {}
        }
        line_start = false;
        in_nl_run = false;
        let start = i;
        let mut text = String::new();
        let mut v = 0.0;
        let k: K;
        if c == '"' {
            let mut s = String::new();
            let mut j = i + 1;
            loop {
                if j >= n {
                    return Err(err("unterminated string literal", off(i), off(i + 1)));
                }
                let d = at(j);
                if d == '"' {
                    j += 1;
                    break;
                }
                if d == '\\' {
                    if j + 1 >= n {
                        return Err(err("unterminated escape sequence", off(j), off(j + 1)));
                    }
                    match at(j + 1) {
                        'n' => s.push('\n'),
                        't' => s.push('\t'),
                        '"' => s.push('"'),
                        '\\' => s.push('\\'),
                        e => {
                            return Err(err(
                                &format!("invalid escape sequence '\\{}'", e.escape_debug()),
                                off(j),
                                off(j + 2),
                            ));
                        }
                    }
                    j += 2;
                    continue;
                }
                s.push(d);
                j += 1;
            }
            k = K::Str;
            text = s;
            i = j;
        } else if c == '\'' {
            return Err(err("single quotes are not strings — use \"…\"", off(i), off(i + 1)));
        } else if c.is_ascii_digit() || (c == '.' && at(i + 1).is_ascii_digit() && !glued_to_word(&toks, sp)) {
            let (kk, j, val) = lex_number(&cs, i, i);
            k = kk;
            v = val;
            text = src[off(i)..off(j)].to_string();
            i = j;
        } else if (c == '-' || c == '+')
            && (at(i + 1).is_ascii_digit() || (at(i + 1) == '.' && at(i + 2).is_ascii_digit()))
        {
            let (kk, j, val) = lex_number(&cs, i, i + 1);
            k = kk;
            v = if c == '-' { -val } else { val };
            text = src[off(i)..off(j)].to_string();
            i = j;
        } else if is_ident_start(c) {
            let mut j = i;
            while j < n && is_ident_char(at(j)) {
                j += 1;
            }
            k = K::Ident;
            text = src[off(i)..off(j)].to_string();
            i = j;
        } else if c == '#' {
            let mut j = i + 1;
            while j < n && is_ident_char(at(j)) {
                j += 1;
            }
            k = K::Hash;
            text = src[off(i + 1)..off(j)].to_string();
            i = j;
        } else if c == '-' && at(i + 1) == '-' && is_ident_start(at(i + 2)) {
            let mut j = i + 2;
            while j < n && is_ident_char(at(j)) {
                j += 1;
            }
            k = K::Var;
            text = src[off(i + 2)..off(j)].to_string();
            i = j;
        } else if c == '.' {
            k = K::Dot;
            i += 1;
        } else if c == '|' {
            if at(i + 1) == '|' {
                k = K::BarBar;
                i += 2;
            } else {
                k = K::Bar;
                i += 1;
            }
        } else if c == '{' {
            k = K::LBrace;
            i += 1;
        } else if c == '}' {
            k = K::RBrace;
            i += 1;
        } else if c == '[' {
            k = K::LBrack;
            i += 1;
        } else if c == ']' {
            k = K::RBrack;
            i += 1;
        } else if c == '(' {
            let c1 = at(i + 1);
            if depth == 0 && at(i + 2) == ')' && (c1 == '-' || c1 == 'o' || c1 == '<') {
                k = K::Dim;
                text = format!("({})", c1);
                i += 3;
            } else if depth == 0 && at(i + 2) == ')' && c1 == '>' {
                return Err(err("'(>)' is reserved — the angle op is '(<)'", off(i), off(i + 3)));
            } else {
                depth += 1;
                k = K::LParen;
                i += 1;
            }
        } else if c == ')' {
            depth = depth.saturating_sub(1);
            k = K::RParen;
            i += 1;
        } else if c == ';' {
            k = K::Semi;
            i += 1;
        } else if c == ',' {
            k = K::Comma;
            i += 1;
        } else if c == ':' {
            if at(i + 1) == ':' {
                k = K::DColon;
                i += 2;
            } else {
                k = K::Colon;
                i += 1;
            }
        } else if c == '&' {
            if depth > 0 && at(i + 1) == '&' {
                k = K::Math;
                text = "&&".into();
                i += 2;
            } else {
                k = K::Amp;
                i += 1;
            }
        } else if c == '=' {
            if at(i + 1) == '=' && depth > 0 {
                k = K::Math;
                text = "==".into();
                i += 2;
            } else {
                k = K::Eq;
                i += 1;
            }
        } else if depth > 0 && "+-*/^?<>!".contains(c) {
            let two: String = [c, at(i + 1)].iter().collect();
            if two == "<=" || two == ">=" || two == "!=" {
                k = K::Math;
                text = two;
                i += 2;
            } else if c == '!' {
                return Err(err(&format!("unexpected character '{}'", c.escape_debug()), off(i), off(i + 1)));
            } else {
                k = K::Math;
                text = c.to_string();
                i += 1;
            }
        } else if "-<>~+*".contains(c) {
            match lex_link_op(&cs, i, src)? {
                Some(j) => {
                    k = K::Link;
                    text = src[off(i)..off(j)].to_string();
                    i = j;
                }
                None => {
                    // only '*' falls through: a bare math operator
                    k = K::Math;
                    text = c.to_string();
                    i += 1;
                }
            }
        } else if c == '/' || c == '^' {
            k = K::Math;
            text = c.to_string();
            i += 1;
        } else {
            return Err(err(&format!("unexpected character '{}'", c.escape_debug()), off(i), off(i + 1)));
        }
        toks.push(Tok { k, s: off(start), e: off(i), sp, v, text });
        sp = false;
    }
    // the end-of-input token reports at the last real token
    let (s, e) = match toks.last() {
        Some(t) => (t.s, t.e),
        None => (0, 0),
    };
    toks.push(Tok { k: K::Eof, s, e, sp: true, v: 0.0, text: String::new() });
    Ok(Lexed { toks, comments })
}

// '.5' right after a word ('a.5') is a path index, not a number
fn glued_to_word(toks: &[Tok], sp: bool) -> bool {
    if sp {
        return false;
    }
    matches!(toks.last().map(|t| t.k), Some(K::Ident) | Some(K::Hash) | Some(K::Var) | Some(K::RParen))
}

// digits ['.' digits] | '.' digits, then an optional '%'
fn lex_number(cs: &[(usize, char)], start: usize, digits_at: usize) -> (K, usize, f64) {
    let n = cs.len();
    let at = |k: usize| -> char { if k < n { cs[k].1 } else { '\0' } };
    let mut j = digits_at;
    let mut body = String::new();
    while at(j).is_ascii_digit() {
        body.push(at(j));
        j += 1;
    }
    if at(j) == '.' && at(j + 1).is_ascii_digit() {
        body.push('.');
        j += 1;
        while at(j).is_ascii_digit() {
            body.push(at(j));
            j += 1;
        }
    }
    let _ = start;
    let v: f64 = body.parse().unwrap_or(0.0);
    if at(j) == '%' {
        return (K::Percent, j + 1, v);
    }
    (K::Num, j, v)
}

// Link operators: [left end] line [right end]. Returns the end index, or None
// when a lone '*' is not followed by a line.
fn lex_link_op(cs: &[(usize, char)], i: usize, src: &str) -> Result<Option<usize>, Diag> {
    let n = cs.len();
    let at = |k: usize| -> char { if k < n { cs[k].1 } else { '\0' } };
    let off = |k: usize| -> usize { if k < n { cs[k].0 } else { src.len() } };
    let mut j = i;
    let mut left = String::new();
    match at(j) {
        '<' | '*' => {
            left.push(at(j));
            j += 1;
            if left == "<" && at(j) == '>' {
                left.push('>');
                j += 1;
            }
        }
        '>' => {
            left.push('>');
            j += 1;
            if at(j) == 'o' || at(j) == '+' {
                left.push(at(j));
                j += 1;
            }
        }
        '+' => {
            left.push('+');
            j += 1;
            if at(j) == 'o' {
                left.push('o');
                j += 1;
            }
        }
        _ => {}
    }
    let line_start = j;
    if at(j) == '-' {
        while at(j) == '-' && j - line_start < 3 {
            j += 1;
        }
    } else if at(j) == '~' {
        j += 1;
    }
    if j == line_start {
        if left == "*" {
            return Ok(None);
        }
        return Err(err(&format!("expected link-op line after '{}'", left), off(i), off(j)));
    }
    let line_end = j;
    match at(j) {
        '>' | '*' | '<' => {
            j += 1;
        }
        '+' => {
            j += 1;
            if at(j) == '<' {
                j += 1;
            }
        }
        'o' => {
            if at(j + 1) == '<' || at(j + 1) == '+' {
                j += 2;
            } else if !is_ident_char(at(j + 1)) || at(line_end - 1) == '-' {
                return Err(err(
                    "'-o' needs a max glyph — write '-o<' or '-o+'; the hollow ring is an ER component only",
                    off(line_end - 1),
                    off(line_end + 1),
                ));
            }
        }
        _ => {}
    }
    Ok(Some(j))
}

// Concrete syntax tree for `lini fmt`: just enough structure to reprint a
// document, with comments and blank lines attached to the items they sit
// between. Leaf values are kept pre-rendered in canonical form.

#[derive(Clone, Debug)]
pub enum Triv {
    Blank,
    // own: the comment starts its source line; otherwise it trails code
    // (an opening bracket, or something the printer drops).
    Comment { text: String, own: bool },
}

#[derive(Clone, Debug)]
pub struct Entry<T> {
    pub lead: Vec<Triv>,
    pub item: T,
    pub trail: Option<String>,
}

#[derive(Clone, Debug)]
pub struct Block<T> {
    pub entries: Vec<Entry<T>>,
    pub close: Vec<Triv>,
}

impl<T> Block<T> {
    pub fn has_comments(&self) -> bool {
        self.entries.iter().any(|e| e.trail.is_some() || e.lead.iter().any(|t| matches!(t, Triv::Comment { .. })))
            || self.close.iter().any(|t| matches!(t, Triv::Comment { .. }))
    }
    pub fn has_blanks(&self) -> bool {
        self.entries.iter().any(|e| e.lead.iter().any(|t| matches!(t, Triv::Blank)))
            || self.close.iter().any(|t| matches!(t, Triv::Blank))
    }
    pub fn has_trivia(&self) -> bool {
        self.has_comments() || self.has_blanks()
    }
}

#[derive(Clone, Debug)]
pub struct Decl {
    pub name: String, // includes the leading '--' for variables
    pub groups: Vec<Vec<String>>,
    pub draw: bool,
    // a comment inside the declaration's own text (dropped, but it still
    // forces the enclosing block onto several lines)
    pub inner_comment: bool,
}

impl Decl {
    pub fn value_text(&self) -> String {
        self.groups.iter().map(|g| g.join(" ")).collect::<Vec<_>>().join(", ")
    }
    pub fn text(&self) -> String {
        format!("{}: {};", self.name, self.value_text())
    }
}

#[derive(Clone, Debug)]
pub enum SheetItem {
    Decl(Decl),
    Var(Decl),
    Binding(String), // "k = v;"
    Rule { selector: String, block: Block<Decl> },
    Define { head: String, style: Option<Block<Decl>>, body: Option<Block<Stmt>> },
}

#[derive(Clone, Debug)]
pub struct Node {
    pub head: String, // "|box#id|"
    pub label: Option<String>,
    pub classes: String, // ".a.b" or ""
    pub style: Option<Block<Decl>>,
    pub children: Option<Block<Stmt>>,
    pub columns: Option<i64>,
}

#[derive(Clone, Debug)]
pub struct Text {
    pub text: String, // rendered with quotes
    pub classes: String,
    pub style: Option<Block<Decl>>,
}

#[derive(Clone, Debug)]
pub struct Link {
    pub head: String, // endpoints and operators
    // the inline label and the '[ ]' entries, merged
    pub labels: Block<Stmt>,
    pub classes: String,
    pub style: Option<Block<Decl>>,
}

#[derive(Clone, Debug)]
pub enum Stmt {
    Node(Node),
    Text(Text),
    Link(Link),
}

#[derive(Clone, Debug)]
pub struct Doc {
    // the stylesheet (None when absent); `sheet_lead` holds what came before it
    pub sheet: Option<Block<SheetItem>>,
    pub sheet_lead: Vec<Triv>,
    pub sheet_trail: Option<String>,
    pub stmts: Block<Stmt>,
}

// Recursive-descent parser for `lini fmt`. It follows the compiler's grammar
// (and its error messages) and builds the concrete tree the printer walks.

use super::cst::*;
use super::expr;
use super::lex::{Comment, Tok, K};
use crate::diag::{Diag, Span};
use std::collections::HashMap;

type R<T> = Result<T, Diag>;

pub const SEP_ERR: &str = "expected a newline, ';', or a closing bracket";
const NODE_ERR: &str = "a node leads with bars — write '|box#X|' (a bare name is a link endpoint)";
const MATH_ERR: &str = "math operators appear inside ( ) — e.g. padding: (8 * 2)";
const GROUP_ERR: &str = "to compute here, wrap the math in a group — e.g. (a - b)";
const LABEL_FIRST: &str = "a label comes before classes — write '|box| \"X\" .hot'";
const CLASS_GLUE: &str = "classes glue into a chain — write '.hot.loud', no space";
const ONE_LABEL: &str = "one inline label — put two or more in a '[ ]'";

fn perr(msg: &str, t: &Tok) -> Diag {
    Diag::error("parse", msg, Span::new(t.s, t.e))
}

#[derive(Clone, Copy, PartialEq)]
enum Ctx {
    Top,
    Children,
    Define,
    Labels,
}

pub struct Parser<'a> {
    src: &'a str,
    toks: &'a [Tok],
    comments: &'a [Comment],
    pos: usize,
    defines: HashMap<String, String>,
}

pub fn render_number(v: f64) -> String {
    if v == 0.0 {
        return "0".to_string();
    }
    format!("{}", v)
}

pub fn render_string(s: &str) -> String {
    let t = s.trim();
    let mut o = String::with_capacity(t.len() + 2);
    o.push('"');
    for c in t.chars() {
        match c {
            '"' => o.push_str("\\\""),
            '\\' => o.push_str("\\\\"),
            '\n' => o.push_str("\\n"),
            '\t' => o.push_str("\\t"),
            c => o.push(c),
        }
    }
    o.push('"');
    o
}

impl<'a> Parser<'a> {
    pub fn new(src: &'a str, toks: &'a [Tok], comments: &'a [Comment]) -> Self {
        Parser { src, toks, comments, pos: 0, defines: HashMap::new() }
    }

    fn peek(&self) -> K {
        self.toks[self.pos].k
    }
    fn peek_at(&self, k: usize) -> K {
        let i = (self.pos + k).min(self.toks.len() - 1);
        self.toks[i].k
    }
    fn tok(&self) -> &Tok {
        &self.toks[self.pos]
    }
    fn tok_at(&self, k: usize) -> &Tok {
        let i = (self.pos + k).min(self.toks.len() - 1);
        &self.toks[i]
    }
    fn bump(&mut self) -> Tok {
        let t = self.toks[self.pos].clone();
        if self.pos < self.toks.len() - 1 {
            self.pos += 1;
        }
        t
    }
    // end offset of the last consumed token
    fn last_end(&self) -> usize {
        if self.pos == 0 {
            0
        } else {
            self.toks[self.pos - 1].e
        }
    }
    fn skip_newlines(&mut self) {
        while self.peek() == K::Newline {
            self.bump();
        }
    }
    fn err_here(&self, msg: &str) -> Diag {
        perr(msg, self.tok())
    }

    // ------------------------------------------------------------- trivia
    fn gap(&self, a: usize, b: usize) -> (Option<String>, Vec<Triv>) {
        let mut first = None;
        let mut out = Vec::new();
        let mut pos = a;
        for c in self.comments.iter().filter(|c| c.s >= a && c.s < b) {
            let nl = self.src[pos..c.s].matches('\n').count();
            if nl == 0 && pos == a && first.is_none() {
                first = Some(c.text.clone());
            } else {
                if nl >= 2 {
                    out.push(Triv::Blank);
                }
                out.push(Triv::Comment { text: c.text.clone(), own: c.own_line });
            }
            pos = c.e;
        }
        if self.src[pos..b].matches('\n').count() >= 2 {
            out.push(Triv::Blank);
        }
        (first, out)
    }

    fn build_block<T>(&self, open_end: usize, items: Vec<(usize, usize, T)>, close_start: usize) -> Block<T> {
        let mut entries: Vec<Entry<T>> = Vec::new();
        let mut prev_end = open_end;
        for (s, e, item) in items {
            let (first, rest) = self.gap(prev_end, s);
            let mut lead = Vec::new();
            if let Some(c) = first {
                match entries.last_mut() {
                    Some(last) => last.trail = Some(c),
                    None => lead.push(Triv::Comment { text: c, own: false }),
                }
            }
            lead.extend(rest);
            entries.push(Entry { lead, item, trail: None });
            prev_end = e;
        }
        let (first, rest) = self.gap(prev_end, close_start);
        let mut close = Vec::new();
        if let Some(c) = first {
            match entries.last_mut() {
                Some(last) => last.trail = Some(c),
                None => close.push(Triv::Comment { text: c, own: false }),
            }
        }
        close.extend(rest);
        Block { entries, close }
    }

    fn has_comment_in(&self, a: usize, b: usize) -> bool {
        self.comments.iter().any(|c| c.s >= a && c.s < b)
    }

    // ------------------------------------------------------------ document
    pub fn parse_doc(&mut self) -> R<Doc> {
        self.skip_newlines();
        let mut items: Vec<(usize, usize, Option<Stmt>)> = Vec::new();
        let mut sheet = None;
        if self.peek() == K::LBrace {
            let s = self.tok().s;
            let b = self.parse_sheet()?;
            sheet = Some(b);
            items.push((s, self.last_end(), None));
        }
        loop {
            self.skip_newlines();
            if self.peek() == K::Eof {
                break;
            }
            if self.peek() == K::LBrace {
                return Err(Diag::error(
                    "stylesheet-after-canvas",
                    "the stylesheet '{ }' must come first, before any instance",
                    Span::new(self.tok().s, self.tok().e),
                ));
            }
            let s = self.tok().s;
            let st = self.parse_stmt(Ctx::Top)?;
            items.push((s, self.last_end(), Some(st)));
            self.after_stmt(K::Eof)?;
        }
        let end = self.src.len();
        let blk = self.build_block(0, items, end);
        let mut entries = blk.entries.into_iter();
        let mut sheet_lead = Vec::new();
        let mut sheet_trail = None;
        let mut stmts = Vec::new();
        if sheet.is_some() {
            let e = entries.next().unwrap();
            sheet_lead = e.lead;
            sheet_trail = e.trail;
        }
        for e in entries {
            stmts.push(Entry { lead: e.lead, item: e.item.unwrap(), trail: e.trail });
        }
        Ok(Doc { sheet, sheet_lead, sheet_trail, stmts: Block { entries: stmts, close: blk.close } })
    }

    // separator after a statement: ';' (then more may follow on the line),
    // a newline, a closing bracket, or the end
    fn after_stmt(&mut self, _closer: K) -> R<()> {
        match self.peek() {
            K::Semi => {
                self.bump();
                Ok(())
            }
            K::Newline | K::Eof | K::RBrack | K::RBrace => Ok(()),
            _ => Err(self.err_here(SEP_ERR)),
        }
    }

    // ------------------------------------------------------------- sheet
    fn parse_sheet(&mut self) -> R<Block<SheetItem>> {
        let open = self.bump();
        let mut items = Vec::new();
        loop {
            self.skip_newlines();
            match self.peek() {
                K::RBrace => break,
                K::Eof => return Err(self.err_here("expected '}'")),
                _ => {}
            }
            let s = self.tok().s;
            let item = self.parse_sheet_item()?;
            items.push((s, self.last_end(), item));
            match self.peek() {
                K::Semi => {
                    self.bump();
                }
                K::Newline | K::RBrace | K::Str => {}
                K::Eof => {}
                _ => return Err(self.err_here(SEP_ERR)),
            }
        }
        let close = self.bump();
        Ok(self.build_block(open.e, items, close.s))
    }

    fn parse_sheet_item(&mut self) -> R<SheetItem> {
        match self.peek() {
            K::Var => {
                let t = self.bump();
                if self.peek() != K::Colon {
                    return Err(self.err_here(&format!("expected ':' after '--{}'", t.text)));
                }
                self.bump();
                let d = self.parse_decl_rest(format!("--{}", t.text), t.s)?;
                Ok(SheetItem::Var(d))
            }
            K::Ident => match self.peek_at(1) {
                K::Colon => {
                    let d = self.parse_decl()?;
                    Ok(SheetItem::Decl(d))
                }
                K::Eq => self.parse_binding(),
                K::LParen => self.parse_binding(),
                _ => Err(self.err_here("a type only appears in bars — write '|box| { }' to style every box")),
            },
            K::Bar | K::BarBar | K::Dot | K::Hash | K::Dim => self.parse_rule_or_define(),
            K::Link => Err(self.err_here(
                "'->' draws a link on the canvas — style every link with '|-| { stroke: … }' in a '{ }' block",
            )),
            _ => Err(self.err_here("the stylesheet holds declarations, rules, and defines")),
        }
    }

    fn parse_binding(&mut self) -> R<SheetItem> {
        let name = self.bump().text;
        let mut params: Option<Vec<String>> = None;
        if self.peek() == K::LParen {
            self.bump();
            let mut ps = Vec::new();
            loop {
                match self.peek() {
                    K::Ident => {
                        ps.push(self.bump().text);
                    }
                    K::RParen if ps.is_empty() => {}
                    _ => return Err(self.err_here("expected identifier")),
                }
                match self.peek() {
                    K::Comma => {
                        self.bump();
                    }
                    K::RParen => {
                        self.bump();
                        break;
                    }
                    _ => return Err(self.err_here("expected ')'")),
                }
            }
            params = Some(ps);
        }
        if self.peek() != K::Eq {
            return Err(self.err_here("expected '='"));
        }
        self.bump();
        let rhs = self.parse_binding_rhs()?;
        if self.peek() == K::Semi {
            self.bump();
        }
        let head = match params {
            Some(ps) if !ps.is_empty() => format!("{}({})", name, ps.join(", ")),
            _ => name,
        };
        Ok(SheetItem::Binding(format!("{} = {};", head, rhs)))
    }

    fn parse_binding_rhs(&mut self) -> R<String> {
        match self.peek() {
            K::Semi | K::Newline | K::RBrace | K::Eof => {
                return Err(self.err_here("a binding needs a value — 'name = value'"));
            }
            _ => {}
        }
        if self.peek() == K::LParen {
            let open = self.bump();
            let close_end = self.skip_group(&open)?;
            match self.peek() {
                K::Semi | K::Newline | K::RBrace | K::Eof => {}
                _ => return Err(self.err_here(SEP_ERR)),
            }
            let inner = self.src[open.e..close_end - 1].trim();
            return Ok(expr::binding_group(inner));
        }
        let start = self.tok().s;
        let mut end = start;
        let mut depth = 0usize;
        loop {
            match self.peek() {
                K::Semi | K::Eof => break,
                K::Newline | K::RBrace if depth == 0 => break,
                K::Math if depth == 0 => return Err(self.err_here(MATH_ERR)),
                K::LBrace => return Err(self.err_here(NODE_ERR)),
                K::LParen => depth += 1,
                K::RParen => depth = depth.saturating_sub(1),
                _ => {}
            }
            end = self.bump().e;
        }
        let text = &self.src[start..end];
        Ok(expr::binding_bare(text))
    }

    fn parse_rule_or_define(&mut self) -> R<SheetItem> {
        // define: |name::base|
        if self.peek() == K::Bar
            && ((self.peek_at(1) == K::Ident && self.peek_at(2) == K::DColon) || self.peek_at(1) == K::DColon)
        {
            self.bump();
            if self.peek() == K::DColon {
                return Err(self.err_here("'| |' needs a type or an '#id'"));
            }
            let name = self.bump().text;
            self.bump(); // ::
            if self.peek() != K::Ident {
                return Err(self.err_here("expected identifier"));
            }
            let base = self.bump().text;
            if self.peek() != K::Bar {
                return Err(self.err_here("expected '|'"));
            }
            self.bump();
            self.defines.insert(name.clone(), base.clone());
            let mut style = None;
            if self.peek() == K::LBrace {
                style = Some(self.parse_style_block()?);
            }
            let mut body = None;
            if self.peek() == K::LBrack {
                body = Some(self.parse_children(Ctx::Define)?);
            }
            let style = style.filter(|b| !b.entries.is_empty());
            let body = body.filter(|b| !b.entries.is_empty());
            return Ok(SheetItem::Define { head: format!("|{}::{}|", name, base), style, body });
        }
        let mut parts: Vec<String> = Vec::new();
        loop {
            match self.peek() {
                K::LBrace => break,
                K::Bar | K::BarBar => {
                    parts.push(self.parse_selector_bars()?);
                }
                K::Dot => {
                    let d = self.bump();
                    if self.peek() != K::Ident || self.tok().sp {
                        return Err(self.err_here("expected identifier"));
                    }
                    let _ = d;
                    parts.push(format!(".{}", self.bump().text));
                }
                K::Hash => {
                    let h = self.bump();
                    if !valid_id(&h.text) {
                        return Err(perr(&format!("'#{}' is not a valid id — an id starts with a letter or '_'", h.text), &h));
                    }
                    parts.push(format!("#{}", h.text));
                }
                K::Dim => {
                    let t = self.bump();
                    if t.text != "(-)" {
                        return Err(perr(
                            "'(-)' selects every dimension — per-kind '(o)' / '(<)' selectors are deferred (SPEC 24)",
                            &t,
                        ));
                    }
                    parts.push(t.text);
                }
                _ => return Err(self.err_here("expected '{'")),
            }
        }
        let block = self.parse_style_block()?;
        Ok(SheetItem::Rule { selector: parts.join(" "), block })
    }

    fn parse_selector_bars(&mut self) -> R<String> {
        if self.peek() == K::BarBar {
            let t = self.tok().clone();
            return Err(Diag::error("parse", "'| |' needs a type or an '#id'", Span::new(t.s + 1, t.e)));
        }
        self.bump();
        let mut ty = None;
        match self.peek() {
            K::Ident => ty = Some(self.bump().text),
            K::Link if self.tok().text == "-" => {
                self.bump();
                ty = Some("-".to_string());
            }
            _ => {}
        }
        let mut id = None;
        if self.peek() == K::Hash && !(ty.is_some() && self.tok().sp) {
            let h = self.bump();
            if !valid_id(&h.text) {
                return Err(perr(&format!("'#{}' is not a valid id — an id starts with a letter or '_'", h.text), &h));
            }
            id = Some(h.text);
        }
        if ty.is_none() && id.is_none() {
            return Err(self.err_here("'| |' needs a type or an '#id'"));
        }
        if self.peek() != K::Bar {
            return Err(self.err_here("expected '|'"));
        }
        self.bump();
        let mut s = String::from("|");
        if let Some(t) = ty {
            s.push_str(&t);
        }
        if let Some(i) = id {
            s.push('#');
            s.push_str(&i);
        }
        s.push('|');
        Ok(s)
    }

    // ------------------------------------------------------- style blocks
    fn parse_style_block(&mut self) -> R<Block<Decl>> {
        let open = self.bump(); // {
        let mut items = Vec::new();
        loop {
            self.skip_newlines();
            match self.peek() {
                K::RBrace => break,
                K::Eof => return Err(self.err_here("expected '}'")),
                K::Ident if self.peek_at(1) == K::Colon => {
                    let s = self.tok().s;
                    let d = self.parse_decl()?;
                    items.push((s, self.last_end(), d));
                }
                _ => return Err(self.err_here("a '{ }' style block holds only declarations")),
            }
        }
        let close = self.bump();
        Ok(self.build_block(open.e, items, close.s))
    }

    fn parse_decl(&mut self) -> R<Decl> {
        let t = self.bump();
        self.bump(); // ':'
        self.parse_decl_rest(t.text.clone(), t.s)
    }

    // after 'name:' — the value, then ';' or a closing '}'
    fn parse_decl_rest(&mut self, name: String, start: usize) -> R<Decl> {
        let draw = name == "draw";
        let groups = self.parse_value(draw)?;
        match self.peek() {
            K::Semi => {
                self.bump();
            }
            K::RBrace => {}
            _ => return Err(self.err_here("a declaration ends with ';'")),
        }
        let inner_comment = self.has_comment_in(start, self.last_end());
        Ok(Decl { name, groups, draw, inner_comment })
    }

    fn parse_value(&mut self, draw: bool) -> R<Vec<Vec<String>>> {
        let mut groups: Vec<Vec<String>> = vec![Vec::new()];
        let mut any = false;
        let mut prev_call = false;
        loop {
            self.skip_newlines();
            match self.peek() {
                K::Semi | K::RBrace | K::Eof => break,
                K::Comma => {
                    self.bump();
                    groups.push(Vec::new());
                    prev_call = false;
                    continue;
                }
                K::Colon => {
                    if draw && self.peek_at(1) == K::Ident && !self.tok_at(1).sp {
                        let glued = prev_call && !self.tok().sp;
                        if !glued {
                            return Err(self.err_here("a ':segment' glues to its call — name a station with point():v"));
                        }
                        self.bump();
                        let tag = self.bump().text;
                        let g = groups.last_mut().unwrap();
                        let last = g.pop().unwrap();
                        g.push(format!("{}:{}", last, tag));
                        prev_call = false;
                        continue;
                    }
                    break;
                }
                _ => {}
            }
            let (term, is_call) = self.parse_term()?;
            groups.last_mut().unwrap().push(term);
            any = true;
            prev_call = is_call;
        }
        if !any && groups.len() == 1 {
            return Err(self.err_here("declaration needs a value"));
        }
        Ok(groups)
    }

    // one value term, rendered canonically; also reports whether it is a call
    fn parse_term(&mut self) -> R<(String, bool)> {
        let t = self.tok().clone();
        match t.k {
            K::Num => {
                self.bump();
                Ok((render_number(t.v), false))
            }
            K::Percent => {
                self.bump();
                Ok((format!("{}%", render_number(t.v)), false))
            }
            K::Str => {
                self.bump();
                Ok((render_string(&t.text), false))
            }
            K::Hash => {
                self.bump();
                if t.text.is_empty() {
                    return Err(perr("invalid hex color '#'", &t));
                }
                Ok((format!("#{}", t.text), false))
            }
            K::Var => {
                self.bump();
                Ok((format!("--{}", t.text), false))
            }
            K::Ident => {
                self.bump();
                if self.peek() == K::LParen && !self.tok().sp {
                    let open = self.bump();
                    let args = self.parse_call_args(&open)?;
                    return Ok((format!("{}({})", t.text, args.join(", ")), true));
                }
                Ok((t.text.clone(), false))
            }
            K::LParen => {
                let open = self.bump();
                let close_end = self.skip_group(&open)?;
                let inner = self.src[open.e..close_end - 1].trim();
                Ok((format!("({})", inner), false))
            }
            K::Link => Err(perr(GROUP_ERR, &t)),
            K::Math => {
                if t.text == "-" || t.text == "+" {
                    Err(perr(GROUP_ERR, &t))
                } else {
                    Err(perr(MATH_ERR, &t))
                }
            }
            _ => Err(perr("expected a value", &t)),
        }
    }

    // skip a '( … )' group (the '(' already consumed); returns the end
    // offset of the matching ')'
    fn skip_group(&mut self, open: &Tok) -> R<usize> {
        let mut depth = 1usize;
        loop {
            match self.peek() {
                K::Eof => {
                    return Err(perr("unterminated '(' group", open));
                }
                K::LParen => depth += 1,
                K::RParen => {
                    depth -= 1;
                    if depth == 0 {
                        return Ok(self.bump().e);
                    }
                }
                _ => {}
            }
            self.bump();
        }
    }

    // call arguments after '(' : comma-separated groups of terms. A group
    // with any operator is kept verbatim; otherwise each term is rendered.
    fn parse_call_args(&mut self, open: &Tok) -> R<Vec<String>> {
        let mut args: Vec<String> = Vec::new();
        let mut cur: Vec<(String, usize, usize, bool)> = Vec::new(); // (rendered, start, end, is_group)
        let mut verbatim = false;
        let mut ternary = 0usize;
        let mut after_bind = false;
        let finish = |cur: &mut Vec<(String, usize, usize, bool)>, verbatim: bool, src: &str| -> String {
            let out = if cur.is_empty() {
                String::new()
            } else if verbatim {
                src[cur[0].1..cur[cur.len() - 1].2].to_string()
            } else if cur.len() == 1 && cur[0].3 {
                let (s, e) = (cur[0].1, cur[0].2);
                src[s + 1..e - 1].trim().to_string()
            } else {
                cur.iter().map(|x| x.0.clone()).collect::<Vec<_>>().join(" ")
            };
            cur.clear();
            out
        };
        loop {
            self.skip_newlines();
            let t = self.tok().clone();
            match t.k {
                K::RParen => {
                    self.bump();
                    if !(args.is_empty() && cur.is_empty()) {
                        args.push(finish(&mut cur, verbatim, self.src));
                    }
                    return Ok(args);
                }
                K::Eof => return Err(perr("unterminated '(' group", open)),
                K::Comma => {
                    self.bump();
                    args.push(finish(&mut cur, verbatim, self.src));
                    verbatim = false;
                    ternary = 0;
                    after_bind = false;
                    continue;
                }
                K::Math => {
                    self.bump();
                    if t.text == "?" {
                        ternary += 1;
                    }
                    cur.push((t.text.clone(), t.s, t.e, false));
                    verbatim = true;
                    continue;
                }
                K::Colon if ternary > 0 => {
                    self.bump();
                    ternary -= 1;
                    cur.push((":".into(), t.s, t.e, false));
                    verbatim = true;
                    continue;
                }
                K::Eq => {
                    self.bump();
                    cur.push(("=".into(), t.s, t.e, false));
                    verbatim = true;
                    after_bind = true;
                    continue;
                }
                K::Semi if after_bind => {
                    self.bump();
                    cur.push((";".into(), t.s, t.e, false));
                    after_bind = false;
                    continue;
                }
                K::Colon => return Err(perr("a declaration ends with ';'", &t)),
                _ => {}
            }
            let s = t.s;
            let is_group = t.k == K::LParen;
            let (term, _) = self.parse_term()?;
            let e = self.last_end();
            cur.push((term, s, e, is_group));
        }
    }

    // ----------------------------------------------------------- statements
    fn parse_children(&mut self, ctx: Ctx) -> R<Block<Stmt>> {
        let open = self.bump(); // [
        let mut items = Vec::new();
        loop {
            self.skip_newlines();
            match self.peek() {
                K::RBrack => break,
                K::Eof => return Err(self.err_here("expected ']'")),
                _ => {}
            }
            let s = self.tok().s;
            let st = self.parse_stmt(ctx)?;
            let is_text = matches!(st, Stmt::Text(_));
            items.push((s, self.last_end(), st));
            match self.peek() {
                K::Semi => {
                    self.bump();
                }
                K::Newline | K::RBrack => {}
                K::Str if is_text => {}
                _ => return Err(self.err_here(SEP_ERR)),
            }
        }
        let close = self.bump();
        Ok(self.build_block(open.e, items, close.s))
    }

    fn parse_stmt(&mut self, ctx: Ctx) -> R<Stmt> {
        match self.peek() {
            K::Bar | K::BarBar => {
                let start = self.pos;
                let head = self.parse_node_head()?;
                if matches!(self.peek(), K::Link | K::Dim | K::BarBar | K::Amp) {
                    if ctx == Ctx::Labels {
                        return Err(perr("a link's '[ ]' holds labels (text) and annotation nodes", &self.toks[start]));
                    }
                    self.pos = start;
                    return self.parse_link();
                }
                let node = self.parse_node_tail(head)?;
                Ok(Stmt::Node(node))
            }
            K::Str => {
                let t = self.bump();
                let text = render_string(&t.text);
                let classes = self.parse_classes()?;
                if self.peek() == K::Str && !classes.is_empty() {
                    return Err(self.err_here(LABEL_FIRST));
                }
                let mut style = None;
                if self.peek() == K::LBrace {
                    style = Some(self.parse_style_block()?);
                }
                Ok(Stmt::Text(Text { text, classes, style: style.filter(|b| !b.entries.is_empty()) }))
            }
            K::Ident => {
                if ctx == Ctx::Labels {
                    return Err(self.err_here("a link's '[ ]' holds labels (text) and annotation nodes"));
                }
                self.parse_link()
            }
            K::Var => Err(self.err_here("variables are declared in the stylesheet '{ }'")),
            _ => Err(self.err_here(NODE_ERR)),
        }
    }

    // '|type#id|' -> (rendered head, type name)
    fn parse_node_head(&mut self) -> R<(String, Option<String>)> {
        if self.peek() == K::BarBar {
            let t = self.tok().clone();
            return Err(Diag::error("parse", "'| |' needs a type or an '#id'", Span::new(t.s + 1, t.e)));
        }
        self.bump(); // |
        let mut ty = None;
        if self.peek() == K::Ident {
            ty = Some(self.bump().text);
        }
        let mut id = None;
        if self.peek() == K::Hash && !(ty.is_some() && self.tok().sp) {
            let h = self.bump();
            if !valid_id(&h.text) {
                return Err(perr(&format!("'#{}' is not a valid id — an id starts with a letter or '_'", h.text), &h));
            }
            id = Some(h.text);
        }
        if ty.is_none() && id.is_none() {
            return Err(self.err_here("'| |' needs a type or an '#id'"));
        }
        if self.peek() != K::Bar {
            return Err(self.err_here("expected '|'"));
        }
        self.bump();
        let mut s = String::from("|");
        if let Some(t) = &ty {
            s.push_str(t);
        }
        if let Some(i) = &id {
            s.push('#');
            s.push_str(i);
        }
        s.push('|');
        Ok((s, ty))
    }

    fn parse_classes(&mut self) -> R<String> {
        let mut out = String::new();
        while self.peek() == K::Dot {
            if self.tok().sp && !out.is_empty() {
                return Err(self.err_here(CLASS_GLUE));
            }
            self.bump();
            if self.peek() != K::Ident || self.tok().sp {
                return Err(self.err_here("expected identifier"));
            }
            out.push('.');
            out.push_str(&self.bump().text);
        }
        Ok(out)
    }

    fn parse_node_tail(&mut self, head: (String, Option<String>)) -> R<Node> {
        let mut label = None;
        if self.peek() == K::Str {
            let t = self.bump();
            label = Some(render_string(&t.text));
            if self.peek() == K::Str {
                return Err(self.err_here(ONE_LABEL));
            }
        }
        let classes = self.parse_classes()?;
        if self.peek() == K::Str {
            return Err(self.err_here(LABEL_FIRST));
        }
        let mut style = None;
        if self.peek() == K::LBrace {
            style = Some(self.parse_style_block()?);
            if self.peek() == K::Str {
                return Err(self.err_here(LABEL_FIRST));
            }
        }
        let mut children = None;
        if self.peek() == K::LBrack {
            children = Some(self.parse_children(Ctx::Children)?);
        }
        let columns = self.node_columns(head.1.as_deref(), style.as_ref());
        Ok(Node {
            head: head.0,
            label,
            classes,
            style: style.filter(|b| !b.entries.is_empty()),
            children: children.filter(|b| !b.entries.is_empty()),
            columns,
        })
    }

    fn node_columns(&self, ty: Option<&str>, style: Option<&Block<Decl>>) -> Option<i64> {
        if let Some(b) = style {
            if let Some(d) = b.entries.iter().rev().find(|e| e.item.name == "columns") {
                return Some(count_tracks(&d.item.groups));
            }
        }
        // built-in defaults, through user defines
        let mut t = ty?.to_string();
        let mut guard = 0;
        loop {
            if t == "entity" {
                return Some(2);
            }
            match self.defines.get(&t) {
                Some(b) if guard < 64 => {
                    t = b.clone();
                    guard += 1;
                }
                _ => return None,
            }
        }
    }

    // ---------------------------------------------------------------- links
    fn parse_endpoint(&mut self, in_fan: bool) -> R<(String, bool)> {
        match self.peek() {
            K::Ident => self.parse_path(),
            K::Bar | K::BarBar => {
                let (h, _) = self.parse_node_head()?;
                Ok((h, false))
            }
            K::Str if !in_fan => {
                let t = self.bump();
                Ok((render_string(&t.text), false))
            }
            _ => Err(self.err_here("expected identifier")),
        }
    }

    // a.b.c[.2][:anchor] -> (rendered, has_dots)
    fn parse_path(&mut self) -> R<(String, bool)> {
        let mut s = self.bump().text;
        let mut dotted = false;
        loop {
            if self.peek() == K::Dot && !self.tok().sp {
                let d = self.tok().clone();
                if self.peek_at(1) == K::Ident && !self.tok_at(1).sp {
                    self.bump();
                    s.push('.');
                    s.push_str(&self.bump().text);
                    dotted = true;
                    continue;
                }
                if self.peek_at(1) == K::Num && !self.tok_at(1).sp {
                    self.bump();
                    let n = self.bump();
                    s.push('.');
                    s.push_str(&render_index(&n.text));
                    dotted = true;
                    if self.peek() == K::Dot && !self.tok().sp {
                        return Err(self.err_here("the copy index ends an endpoint path"));
                    }
                    break;
                }
                if self.tok_at(1).sp {
                    return Err(perr("endpoint '.' must have no whitespace after it", self.tok_at(1)));
                }
                let _ = d;
                break;
            }
            break;
        }
        if self.peek() == K::Colon {
            self.bump();
            if self.peek() != K::Ident {
                return Err(self.err_here("expected identifier"));
            }
            s.push(':');
            s.push_str(&self.bump().text);
        }
        Ok((s, dotted))
    }

    fn parse_fan(&mut self) -> R<(Vec<String>, bool)> {
        let (first, dotted) = self.parse_endpoint(false)?;
        let mut eps = vec![first];
        let mut complex = dotted;
        while self.peek() == K::Amp {
            self.bump();
            let (e, _) = self.parse_endpoint(true)?;
            eps.push(e);
            complex = true;
        }
        Ok((eps, complex))
    }

    fn parse_link(&mut self) -> R<Stmt> {
        let start_tok = self.tok().clone();
        let first_is_text = self.peek() == K::Str;
        let (first, complex) = self.parse_fan()?;
        let mut head = first.join(" & ");
        let mut nops = 0;
        let mut ended = first_is_text;
        loop {
            let op = match self.peek() {
                K::Link | K::Dim => self.tok().text.clone(),
                K::BarBar => "||".to_string(),
                _ => break,
            };
            if ended {
                return Err(self.err_here("a text callout ends its statement — chain before it"));
            }
            let op_tok = self.bump();
            nops += 1;
            head.push(' ');
            head.push_str(&op);
            match self.peek() {
                K::Ident | K::Bar | K::BarBar => {
                    let (eps, _) = self.parse_fan()?;
                    head.push(' ');
                    head.push_str(&eps.join(" & "));
                }
                K::Str => {
                    // a text callout target ends the chain
                    let t = self.bump();
                    head.push(' ');
                    head.push_str(&render_string(&t.text));
                    ended = true;
                    if self.peek() == K::Str {
                        return Err(self.err_here(ONE_LABEL));
                    }
                }
                _ => {
                    if matches!(self.peek(), K::Link | K::Dim | K::BarBar) {
                        return Err(perr("a text callout ends its statement — chain before it", &op_tok));
                    }
                    ended = true;
                }
            }
        }
        if nops == 0 {
            if complex {
                return Err(self.err_here("expected a link operator"));
            }
            if self.peek() == K::Colon || head.contains(':') {
                return Err(Diag::error(
                    "declaration-outside-block",
                    "a declaration belongs in a '{ }' block",
                    Span::new(start_tok.s, start_tok.e),
                ));
            }
            return Err(perr(NODE_ERR, &start_tok));
        }
        let mut label: Option<(usize, usize, Stmt)> = None;
        if self.peek() == K::Str {
            let t = self.bump();
            label = Some((t.s, t.e, Stmt::Text(Text { text: render_string(&t.text), classes: String::new(), style: None })));
            if self.peek() == K::Str {
                return Err(self.err_here(ONE_LABEL));
            }
        }
        let classes = self.parse_classes()?;
        if self.peek() == K::Str {
            return Err(self.err_here(LABEL_FIRST));
        }
        let mut style = None;
        if self.peek() == K::LBrace {
            style = Some(self.parse_style_block()?);
            if self.peek() == K::Str {
                return Err(self.err_here(LABEL_FIRST));
            }
        }
        let mut labels = match self.peek() {
            K::LBrack => self.parse_children(Ctx::Labels)?,
            _ => Block { entries: Vec::new(), close: Vec::new() },
        };
        if let Some((_, _, st)) = label {
            labels.entries.insert(0, Entry { lead: Vec::new(), item: st, trail: None });
        }
        Ok(Stmt::Link(Link { head, labels, classes, style: style.filter(|b| !b.entries.is_empty()) }))
    }
}

fn valid_id(s: &str) -> bool {
    match s.chars().next() {
        Some(c) => c.is_ascii_alphabetic() || c == '_',
        None => false,
    }
}

fn render_index(text: &str) -> String {
    let digits: String = text.chars().filter(|c| c.is_ascii_digit()).collect();
    match digits.parse::<u64>() {
        Ok(v) => v.to_string(),
        Err(_) => digits,
    }
}

// number of grid tracks a `columns:` value declares
fn count_tracks(groups: &[Vec<String>]) -> i64 {
    let mut n: i64 = 0;
    for g in groups {
        for t in g {
            if let Some(rest) = t.strip_prefix("repeat(") {
                let first = rest.trim_end_matches(')').split(',').next().unwrap_or("").trim();
                match first.parse::<f64>() {
                    Ok(v) if v.is_finite() && v >= 1.0 => n += v.trunc().min(1e15) as i64,
                    Ok(v) if v.is_infinite() && v > 0.0 => n += 1_000_000_000,
                    _ => n += 1,
                }
            } else {
                n += 1;
            }
        }
    }
    n
}

// Binding right-hand sides: `w = 120;` stays bare, `k = a b;` gains a group,
// and `k = (a);` sheds one. The decision reads the text as a math expression.

#[derive(Clone, Debug, PartialEq)]
enum Kind {
    Num,
    Ident,
    Var,
    Call,
    Unary,
    Paren(Box<Kind>),
    Compound, // binary, ternary, tuple, block
}

#[derive(Clone, Debug, PartialEq)]
enum T {
    Num,
    Ident,
    Var,
    Op(String),
    LParen,
    RParen,
    Comma,
    Eq,
    Semi,
    Colon,
    Bad,
}

fn tokenize(s: &str) -> Vec<(T, bool)> {
    // (token, whitespace before)
    let cs: Vec<char> = s.chars().collect();
    let n = cs.len();
    let at = |i: usize| -> char { if i < n { cs[i] } else { '\0' } };
    let mut out = Vec::new();
    let mut i = 0;
    let mut sp = true;
    while i < n {
        let c = cs[i];
        if c.is_whitespace() {
            sp = true;
            i += 1;
            continue;
        }
        let t;
        if c.is_ascii_digit() || (c == '.' && at(i + 1).is_ascii_digit()) {
            while at(i).is_ascii_digit() {
                i += 1;
            }
            if at(i) == '.' && at(i + 1).is_ascii_digit() {
                i += 1;
                while at(i).is_ascii_digit() {
                    i += 1;
                }
            }
            if at(i) == 'e' || at(i) == 'E' {
                let mut j = i + 1;
                if at(j) == '+' || at(j) == '-' {
                    j += 1;
                }
                if at(j).is_ascii_digit() {
                    while at(j).is_ascii_digit() {
                        j += 1;
                    }
                    i = j;
                }
            }
            if at(i) == '%' {
                t = T::Bad;
                i += 1;
            } else {
                t = T::Num;
            }
        } else if c.is_ascii_alphabetic() || c == '_' {
            while at(i).is_ascii_alphanumeric() || at(i) == '_' || at(i) == '-' {
                i += 1;
            }
            t = T::Ident;
        } else if c == '-' && at(i + 1) == '-' && (at(i + 2).is_ascii_alphabetic() || at(i + 2) == '_') {
            i += 2;
            while at(i).is_ascii_alphanumeric() || at(i) == '_' || at(i) == '-' {
                i += 1;
            }
            t = T::Var;
        } else {
            let two: String = [c, at(i + 1)].iter().collect();
            if ["<=", ">=", "==", "!=", "&&", "||"].contains(&two.as_str()) {
                t = T::Op(two);
                i += 2;
            } else {
                i += 1;
                t = match c {
                    '+' | '-' | '*' | '/' | '^' | '<' | '>' | '?' => T::Op(c.to_string()),
                    '(' => T::LParen,
                    ')' => T::RParen,
                    ',' => T::Comma,
                    '=' => T::Eq,
                    ';' => T::Semi,
                    ':' => T::Colon,
                    _ => T::Bad,
                };
            }
        }
        out.push((t, sp));
        sp = false;
    }
    out
}

struct P {
    toks: Vec<(T, bool)>,
    pos: usize,
}

fn prec(op: &str) -> Option<u8> {
    Some(match op {
        "||" => 1,
        "&&" => 2,
        "==" | "!=" => 3,
        "<" | ">" | "<=" | ">=" => 4,
        "+" | "-" => 5,
        "*" | "/" => 6,
        "^" => 8,
        _ => return None,
    })
}

impl P {
    fn peek(&self) -> Option<&T> {
        self.toks.get(self.pos).map(|t| &t.0)
    }
    fn peek2(&self) -> Option<&T> {
        self.toks.get(self.pos + 1).map(|t| &t.0)
    }
    fn bump(&mut self) {
        self.pos += 1;
    }
    fn expr(&mut self) -> Option<Kind> {
        // local bindings: name = expr; ... expr
        let mut block = false;
        while matches!(self.peek(), Some(T::Ident)) && matches!(self.peek2(), Some(T::Eq)) {
            self.bump();
            self.bump();
            self.ternary()?;
            if matches!(self.peek(), Some(T::Semi)) {
                self.bump();
            }
            block = true;
        }
        let k = self.ternary()?;
        Some(if block { Kind::Compound } else { k })
    }
    fn ternary(&mut self) -> Option<Kind> {
        let c = self.binary(0)?;
        if matches!(self.peek(), Some(T::Op(o)) if o == "?") {
            self.bump();
            self.ternary()?;
            if !matches!(self.peek(), Some(T::Colon)) {
                return None;
            }
            self.bump();
            self.ternary()?;
            return Some(Kind::Compound);
        }
        Some(c)
    }
    fn binary(&mut self, min: u8) -> Option<Kind> {
        let mut lhs = self.unary()?;
        loop {
            let op = match self.peek() {
                Some(T::Op(o)) => o.clone(),
                _ => break,
            };
            let p = match prec(&op) {
                Some(p) => p,
                None => break,
            };
            if p < min {
                break;
            }
            self.bump();
            let next = if op == "^" { p } else { p + 1 };
            self.binary(next)?;
            lhs = Kind::Compound;
        }
        Some(lhs)
    }
    fn unary(&mut self) -> Option<Kind> {
        if matches!(self.peek(), Some(T::Op(o)) if o == "-") {
            self.bump();
            self.unary()?;
            return Some(Kind::Unary);
        }
        self.primary()
    }
    fn primary(&mut self) -> Option<Kind> {
        match self.peek()?.clone() {
            T::Num => {
                self.bump();
                Some(Kind::Num)
            }
            T::Var => {
                self.bump();
                Some(Kind::Var)
            }
            T::Ident => {
                self.bump();
                if matches!(self.peek(), Some(T::LParen)) {
                    self.bump();
                    if matches!(self.peek(), Some(T::RParen)) {
                        self.bump();
                        return Some(Kind::Call);
                    }
                    loop {
                        self.expr()?;
                        match self.peek() {
                            Some(T::Comma) => self.bump(),
                            Some(T::RParen) => {
                                self.bump();
                                return Some(Kind::Call);
                            }
                            _ => return None,
                        }
                    }
                }
                Some(Kind::Ident)
            }
            T::LParen => {
                self.bump();
                let k = self.expr()?;
                let mut tuple = false;
                while matches!(self.peek(), Some(T::Comma)) {
                    self.bump();
                    self.expr()?;
                    tuple = true;
                }
                if !matches!(self.peek(), Some(T::RParen)) {
                    return None;
                }
                self.bump();
                Some(if tuple { Kind::Compound } else { Kind::Paren(Box::new(k)) })
            }
            _ => None,
        }
    }
}

fn classify(s: &str) -> Option<Kind> {
    let toks = tokenize(s);
    if toks.iter().any(|t| t.0 == T::Bad) {
        return None;
    }
    let mut p = P { toks, pos: 0 };
    let k = p.expr()?;
    if p.pos != p.toks.len() {
        return None;
    }
    Some(k)
}

fn simple(k: &Kind) -> bool {
    matches!(k, Kind::Num | Kind::Ident | Kind::Var | Kind::Call | Kind::Unary)
}

fn core(k: &Kind) -> &Kind {
    match k {
        Kind::Paren(inner) => core(inner),
        k => k,
    }
}

// RHS written as '( inner )'
pub fn binding_group(inner: &str) -> String {
    match classify(inner) {
        Some(k) if simple(core(&k)) => inner.to_string(),
        _ => format!("({})", inner),
    }
}

// RHS written bare
pub fn binding_bare(text: &str) -> String {
    match classify(text) {
        Some(k) if simple(&k) => text.to_string(),
        _ => format!("({})", text),
    }
}

// Concrete syntax tree for `lini fmt`: just enough structure to reprint a
// document, with comments and blank lines attached to the items they sit
// between. Leaf values are kept pre-rendered in canonical form.

#[derive(Clone, Debug)]
pub enum Triv {
    Blank,
    // own: the comment starts its source line; otherwise it trails code
    // (an opening bracket, or something the printer drops).
    Comment { text: String, own: bool },
}

#[derive(Clone, Debug)]
pub struct Entry<T> {
    pub lead: Vec<Triv>,
    pub item: T,
    pub trail: Option<String>,
}

#[derive(Clone, Debug)]
pub struct Block<T> {
    pub entries: Vec<Entry<T>>,
    pub close: Vec<Triv>,
    // any comment between the brackets, even one the printer drops
    pub any_comment: bool,
    // any comment from the first entry's start to the last entry's end
    pub comment_among: bool,
}

impl<T> Block<T> {
    pub fn empty() -> Self {
        Block { entries: Vec::new(), close: Vec::new(), any_comment: false, comment_among: false }
    }
    pub fn has_blanks(&self) -> bool {
        self.entries.iter().any(|e| e.lead.iter().any(|t| matches!(t, Triv::Blank)))
            || self.close.iter().any(|t| matches!(t, Triv::Blank))
    }
    pub fn has_trivia(&self) -> bool {
        self.any_comment || self.has_blanks()
    }
}

#[derive(Clone, Debug)]
pub struct Decl {
    pub name: String, // includes the leading '--' for variables
    pub groups: Vec<Vec<String>>,
    pub draw: bool,
    pub tracks: i64, // grid tracks, when read as a `columns:` value
}

impl Decl {
    pub fn value_text(&self) -> String {
        self.groups.iter().map(|g| g.join(" ")).collect::<Vec<_>>().join(", ")
    }
    pub fn text(&self) -> String {
        format!("{}: {};", self.name, self.value_text())
    }
}

#[derive(Clone, Debug)]
pub enum SheetItem {
    Decl(Decl),
    Var(Decl),
    Binding(String), // "k = v;"
    Rule { selector: String, block: Block<Decl> },
    Define { head: String, style: Option<Block<Decl>>, body: Option<Block<Stmt>> },
}

#[derive(Clone, Debug)]
pub struct Node {
    pub head: String, // "|box#id|"
    pub label: Option<String>,
    pub classes: String, // ".a.b" or ""
    pub style: Option<Block<Decl>>,
    pub children: Option<Block<Stmt>>,
    pub columns: Option<i64>,
}

#[derive(Clone, Debug)]
pub struct Text {
    pub text: String, // rendered with quotes
    pub classes: String,
    pub style: Option<Block<Decl>>,
}

#[derive(Clone, Debug)]
pub struct Link {
    pub head: String, // endpoints and operators
    // the inline label and the '[ ]' entries, merged
    pub labels: Block<Stmt>,
    pub classes: String,
    pub style: Option<Block<Decl>>,
}

#[derive(Clone, Debug)]
pub enum Stmt {
    Node(Node),
    Text(Text),
    Link(Link),
}

#[derive(Clone, Debug)]
pub struct Doc {
    // the stylesheet (None when absent); `sheet_lead` holds what came before it
    pub sheet: Option<Block<SheetItem>>,
    pub sheet_lead: Vec<Triv>,
    pub sheet_trail: Option<String>,
    pub stmts: Block<Stmt>,
}

