fn draw(&mut self, indent: usize, d: &Decl) {
    let prefix = format!("{}: ", d.name);
    let col = indent + prefix.len();
    let mut pieces: Vec<String> = Vec::new();
    let ng = d.groups.len();
    for (gi, g) in d.groups.iter().enumerate() {
        for (ti, t) in g.iter().enumerate() {
