fn after_stmt(&mut self, _closer: K) -> R<()> {
    match self.peek() {
        K::Semi => {
            self.bump();
            Ok(())
        }
        K::Newline | K::Eof | K::RBrack | K::RBrace => Ok(()),
        _ => Err(self.err_here(SEP_ERR)),
    }
}

