fn after_stmt(&mut self, was_text: bool) -> R<()> {
    match self.peek() {
        K::Semi => {
            self.bump();
            Ok(())
        }
        K::Newline | K::Eof | K::RBrack | K::RBrace => Ok(()),
        K::Str if was_text => Ok(()),
        K::Math => Err(self.err_here(MATH_ERR)),
