// the whitespace right before `pos` spans an empty line
fn blank_before(&self, pos: usize) -> bool {
    let bytes = self.src.as_bytes();
    let mut i = pos;
    let mut nl = 0;
    while i > 0 {
        match bytes[i - 1] {
            b'\n' => nl += 1,
            b' ' | b'\t' | b'\r' => {}
            _ => break,
        }
        i -= 1;
    }
    nl >= 2
}

