                    let mut end = t.e;
                    let mut depth = 0usize;
                    loop {
                        match self.peek() {
                            K::Eof => return Err(self.err_here("expected ')'")),
                            K::LParen => depth += 1,
                            K::RParen if depth == 0 => break,
                            K::RParen => depth -= 1,
                            K::Comma if depth == 0 => break,
                            K::Newline => {
                                self.bump();
                                continue;
                            }
                            _ => {}
                        }
                        end = self.bump().e;
                    }
                    if args.is_empty() {
                        first_num = None;
                    }
                    cur.clear();
                    cur.push((self.src[start..end].to_string(), start, end, false));
                    let text = cur.pop().unwrap().0;
                    args.push(text);
                    if self.peek() == K::Comma {
                        self.bump();
                        // a comma must be followed by another argument
                        self.skip_newlines();
                        if matches!(self.peek(), K::RParen | K::Comma) {
                            return Err(self.err_here("expected a value"));
                        }
                    } else {
                        self.bump(); // ')'
                        return Ok((args, first_num));
                    }
                    continue;
