#!/usr/bin/env python3
# Random Lini document generator for differential testing of `fmt`.
import random

PROPS = ['fill', 'stroke', 'gap', 'padding', 'width', 'height', 'radius', 'font-size', 'color',
         'direction', 'layout', 'columns', 'rows', 'align', 'justify', 'translate', 'rotate',
         'data', 'labels', 'categories', 'points', 'draw', 'stroke-width', 'opacity', 'marker-end',
         'side', 'at', 'on', 'range', 'value', 'fn', 'samples', 'cell', 'span', 'symbol', 'shadow']
TYPES = ['box', 'group', 'row', 'column', 'grid', 'table', 'entity', 'cyl', 'oval', 'sketch', 'line',
         'chart', 'bars', 'pie', 'slice', 'caption', 'badge', 'text', 'icon', 'note', 'page']
IDENTS = ['a', 'b', 'c', 'api', 'db', 'web', 'user', 'node1', 'x_y', 'k-2']
WORDS = ['red', 'blue', 'auto', 'none', 'start', 'end', 'center', 'row', 'column', 'dashed', 'bold']
OPS = ['->', '<-', '<->', '-', '--', '-->', '---', '~>', '~', '-o<', '>-', '*-', '-*', '+-o<', '<--', '||', '(-)', '(o)', '(<)']
COMMENTS = ['// c', '// a note', '//x', '// — dash', '// ends here']
STRS = ['"A"', '"Hello"', '"two words"', '"x\\ny"', '"q\\"q"', '""', '" pad "', '"é²"', '"a longer label text"']


class G:
    def __init__(self, seed):
        self.r = random.Random(seed)

    def ch(self, xs):
        return self.r.choice(xs)

    def p(self, x):
        return self.r.random() < x

    def num(self):
        return self.ch(['0', '1', '2', '12', '1.5', '0.25', '-3', '.5', '100', '1.50', '007', '3.0', '-0', '1e3'])

    def arg(self, depth):
        k = self.r.randint(0, 9)
        if k < 4:
            return self.num()
        if k < 6:
            return self.ch(IDENTS + WORDS)
        if k == 6:
            return self.ch(['a + 1', 'x * 2', '1-2', 'w / 2', '(1 + 2)', '- a', '2*-1', 'x ? 1 : 2', '( a )'])
        if k == 7 and depth < 2:
            return self.call(depth + 1)
        if k == 8:
            return self.ch(STRS[:3])
        return self.ch(['--v', '#fff', '10%'])

    def call(self, depth=0):
        name = self.ch(['f', 'move', 'right', 'up', 'arc', 'repeat', 'gradient', 'hatch', 'min', 'rgba'])
        n = self.r.randint(0, 3)
        args = []
        for _ in range(n):
            g = ' '.join(self.arg(depth) for _ in range(self.r.randint(1, 2)))
            args.append(g)
        sep = self.ch([', ', ',', ' , ', ',  '])
        o = self.ch(['(', '( '])
        c = self.ch([')', ' )'])
        return name + o + sep.join(args) + c

    def term(self):
        k = self.r.randint(0, 11)
        if k < 3:
            return self.num()
        if k < 5:
            return self.ch(WORDS)
        if k == 5:
            return self.ch(STRS)
        if k == 6:
            return self.ch(['#fff', '#0a84ff', '#888', '#eef'])
        if k == 7:
            return self.ch(['--teal', '--red-ink', '--bg'])
        if k == 8:
            return self.ch(['50%', '12.5%'])
        if k == 9:
            return self.ch(['(1 + 2)', '( a*b )', '(x)', '(u * 300, 20 * sin(u))', '(8 * 2)'])
        return self.call()

    def value(self, prop):
        if prop == 'draw':
            parts = ['move(0, 0)']
            for _ in range(self.r.randint(1, 12)):
                c = self.ch(['right(10)', 'down(5)', 'up(2.5)', 'left(7.25)', 'arc(3, 90)', 'close()',
                             'move(1, 1)', 'fillet(2)', 'right(40):top', 'point():v', 'line(3, -4)'])
                parts.append(c)
            sep = self.ch([' ', '  ', '\n        '])
            return sep.join(parts)
        groups = []
        for _ in range(self.r.randint(1, 3) if self.p(0.4) else 1):
            groups.append(' '.join(self.term() for _ in range(self.r.randint(1, 3))))
        return self.ch([', ', ',', ' , ']).join(groups)

    def decl(self):
        prop = self.ch(PROPS)
        return '%s:%s%s' % (prop, self.ch([' ', '', '  ']), self.value(prop))

    def style(self, indent, multiline=None):
        n = self.r.randint(0, 5)
        decls = [self.decl() for _ in range(n)]
        if multiline is None:
            multiline = self.p(0.3)
        if not multiline:
            body = '; '.join(decls)
            if decls and self.p(0.7):
                body += ';'
            return '{ ' + body + (' ' if body else '') + '}'
        out = ['{' + (' ' + self.ch(COMMENTS) if self.p(0.1) else '')]
        for d in decls:
            line = ' ' * (indent + 2) + d + ';'
            if self.p(0.15):
                line += '  ' + self.ch(COMMENTS)
            out.append(line)
            if self.p(0.1):
                out.append('')
            if self.p(0.08):
                out.append(' ' * (indent + 2) + self.ch(COMMENTS))
        out.append(' ' * indent + '}')
        return '\n'.join(out)

    def classes(self):
        return ''.join('.' + self.ch(['hot', 'loud', 'k', 'x-y']) for _ in range(self.r.randint(1, 2)))

    def head(self):
        t = self.ch(TYPES)
        if self.p(0.5):
            return '|%s#%s|' % (t, self.ch(IDENTS[:8]))
        return '|%s|' % t

    def text(self, indent):
        s = self.ch(STRS)
        if self.p(0.15):
            s += ' ' + self.classes()
        if self.p(0.15):
            s += ' ' + self.style(indent, False)
        return s

    def node(self, indent, depth):
        s = self.head()
        if self.p(0.6):
            s += ' ' + self.ch(STRS)
        if self.p(0.2):
            s += ' ' + self.classes()
        if self.p(0.5):
            st = self.style(indent)
            if st != '{ }' or self.p(0.2):
                s += ' ' + st
        if self.p(0.4) and depth < 3:
            s += ' ' + self.children(indent, depth + 1)
        return s

    def endpoint(self):
        k = self.r.randint(0, 9)
        if k < 6:
            e = self.ch(IDENTS[:8])
            if self.p(0.2):
                e += '.' + self.ch(IDENTS[:4])
            if self.p(0.1):
                e += '.2'
            if self.p(0.2):
                e += ':' + self.ch(['top', 'left', 'right', 'bottom'])
            return e
        return self.head()

    def link(self, indent):
        def fan():
            n = 1 if self.p(0.8) else self.r.randint(2, 3)
            return ' & '.join(self.endpoint() for _ in range(n))
        op = self.ch(OPS)
        s = fan() + ' ' + op + ' ' + fan()
        if self.p(0.2):
            s += ' ' + op + ' ' + fan()
        if self.p(0.4):
            s += ' ' + self.ch(STRS)
        if self.p(0.15):
            s += ' ' + self.classes()
        if self.p(0.3):
            s += ' ' + self.style(indent)
        if self.p(0.15):
            s += ' [ ' + ' '.join(self.text(indent) for _ in range(self.r.randint(1, 3))) + ' ]'
        return s

    def stmt(self, indent, depth):
        k = self.r.randint(0, 9)
        if k < 5:
            return self.node(indent, depth)
        if k < 7:
            return self.text(indent)
        return self.link(indent)

    def children(self, indent, depth):
        if self.p(0.3):
            # a row of strings
            items = [self.ch(STRS) for _ in range(self.r.randint(1, 6))]
            if self.p(0.2):
                items.append(self.text(indent))
            return '[ ' + ' '.join(items) + ' ]'
        out = ['[' + ('  ' + self.ch(COMMENTS) if self.p(0.1) else '')]
        for _ in range(self.r.randint(0, 4)):
            if self.p(0.1):
                out.append('')
            if self.p(0.1):
                out.append(' ' * (indent + 2) + self.ch(COMMENTS))
            line = ' ' * (indent + 2) + self.stmt(indent + 2, depth)
            if self.p(0.1):
                line += '  ' + self.ch(COMMENTS)
            out.append(line)
        out.append(' ' * indent + ']')
        return '\n'.join(out)

    def selector(self):
        parts = []
        for _ in range(self.r.randint(1, 2)):
            parts.append(self.ch(['|box|', '|-|', '.hot', '#g', '|box#a|', '(-)', '|cyl|', '.a.b']))
        return ' '.join(parts)

    def sheet_item(self):
        k = self.r.randint(0, 9)
        if k < 3:
            return self.decl() + ';'
        if k == 3:
            return '--%s: %s;' % (self.ch(['brand', 'v', 'accent']), self.term())
        if k == 4:
            return self.ch(['w = 120;', 'k = (1 + 2);', 'scale(n) = (100 * 1.2^n);', 'f(a, b) = (a+b);',
                            'cap = 0.9;', 'g = (a);', 'h = "s";', 'z = a b;', 'm = min(1, 2);'])
        if k < 8:
            return self.selector() + ' ' + self.style(2)
        s = '|%s::%s|' % (self.ch(['room', 'card', 'svc', 'tile']), self.ch(TYPES))
        if self.p(0.6):
            s += ' ' + self.style(2)
        if self.p(0.4):
            s += ' ' + self.children(2, 1)
        return s

    def doc(self):
        out = []
        if self.p(0.2):
            out.append(self.ch(COMMENTS))
        if self.p(0.6):
            if self.p(0.2):
                out.append('{ ' + '; '.join(self.decl() for _ in range(self.r.randint(1, 3))) + ' }')
            else:
                out.append('{')
                for _ in range(self.r.randint(0, 6)):
                    if self.p(0.1):
                        out.append('')
                    if self.p(0.1):
                        out.append('  ' + self.ch(COMMENTS))
                    line = '  ' + self.sheet_item()
                    if self.p(0.15):
                        line += '  ' + self.ch(COMMENTS)
                    out.append(line)
                out.append('}')
            if self.p(0.5):
                out.append('')
        for _ in range(self.r.randint(1, 8)):
            if self.p(0.1):
                out.append('')
            if self.p(0.1):
                out.append(self.ch(COMMENTS))
            line = self.stmt(0, 0)
            if self.p(0.15):
                line += '  ' + self.ch(COMMENTS)
            out.append(line)
        return '\n'.join(out) + '\n'


if __name__ == '__main__':
    import sys
    seed = int(sys.argv[1]) if len(sys.argv) > 1 else 1
    print(G(seed).doc())

