56	pub struct Lexed {
57	    pub toks: Vec<Tok>,
58	    pub comments: Vec<Comment>,
59	}
60	
61	fn is_ident_start(c: char) -> bool {
62	    c.is_ascii_alphabetic() || c == '_'
63	}
