75	pub fn lex(src: &str) -> Result<Lexed, Diag> {
76	    let cs: Vec<(usize, char)> = src.char_indices().collect();
77	    let n = cs.len();
78	    let at = |i: usize| -> char { if i < n { cs[i].1 } else { '\0' } };
79	    let off = |i: usize| -> usize { if i < n { cs[i].0 } else { src.len() } };
80	    let mut toks: Vec<Tok> = Vec::new();
81	    let mut comments: Vec<Comment> = Vec::new();
82	    let mut i = 0usize;
83	    let mut depth: usize = 0;
84	    let mut sp = true;
85	    let mut line_start = true;
86	    // a run of newlines yields one Newline token; a comment ends the run
87	    let mut in_nl_run = false;
88	    while i < n {
89	        let c = at(i);
90	        match c {
91	            ' ' | '\t' | '\r' => {
92	                i += 1;
93	                sp = true;
94	                continue;
95	            }
96	            '\n' => {
97	                if !in_nl_run {
98	                    toks.push(Tok { k: K::Newline, s: off(i), e: off(i + 1), sp, v: 0.0, text: String::new() });
99	                    in_nl_run = true;
100	                }
101	                i += 1;
102	                sp = true;
103	                line_start = true;
104	                continue;
105	            }
106	            '/' if at(i + 1) == '/' => {
107	                let mut j = i;
108	                while j < n && at(j) != '\n' {
109	                    j += 1;
110	                }
111	                let text: String = src[off(i)..off(j)].trim_end().to_string();
112	                comments.push(Comment { s: off(i), e: off(j), text, own_line: line_start });
113	                in_nl_run = false;
114	                i = j;
115	                sp = true;
116	                continue;
117	            }
118	            _ => {}
119	        }
120	        line_start = false;
121	        in_nl_run = false;
122	        let start = i;
123	        let mut text = String::new();
124	        let mut v = 0.0;
125	        let k: K;
126	        if c == '"' {
127	            let mut s = String::new();
128	            let mut j = i + 1;
129	            loop {
130	                if j >= n {
131	                    return Err(err("unterminated string literal", off(i), off(i + 1)));
132	                }
133	                let d = at(j);
134	                if d == '"' {
135	                    j += 1;
136	                    break;
137	                }
138	                if d == '\\' {
139	                    if j + 1 >= n {
140	                        return Err(err("unterminated escape sequence", off(j), off(j + 1)));
141	                    }
142	                    match at(j + 1) {
143	                        'n' => s.push('\n'),
144	                        't' => s.push('\t'),
145	                        '"' => s.push('"'),
146	                        '\\' => s.push('\\'),
147	                        e => {
148	                            return Err(err(
149	                                &format!("invalid escape sequence '\\{}'", e.escape_debug()),
150	                                off(j),
151	                                off(j + 2),
152	                            ));
153	                        }
154	                    }
155	                    j += 2;
156	                    continue;
157	                }
158	                s.push(d);
159	                j += 1;
160	            }
161	            k = K::Str;
162	            text = s;
163	            i = j;
164	        } else if c == '\'' {
165	            return Err(err("single quotes are not strings — use \"…\"", off(i), off(i + 1)));
166	        } else if c.is_ascii_digit() || (c == '.' && at(i + 1).is_ascii_digit() && !glued_to_word(&toks, sp)) {
167	            let (kk, j, val) = lex_number(&cs, i, depth > 0);
168	            k = kk;
169	            v = val;
170	            text = src[off(i)..off(j)].to_string();
171	            i = j;
172	        } else if (c == '-' || c == '+')
173	            && (at(i + 1).is_ascii_digit() || (at(i + 1) == '.' && at(i + 2).is_ascii_digit()))
174	        {
175	            let (kk, j, val) = lex_number(&cs, i + 1, depth > 0);
176	            k = kk;
177	            v = if c == '-' { -val } else { val };
178	            text = src[off(i)..off(j)].to_string();
179	            i = j;

