1	// Recursive-descent parser for `lini fmt`. It follows the compiler's grammar
2	// (and its error messages) and builds the concrete tree the printer walks.
3	
4	use super::cst::*;
5	use super::expr;
6	use super::lex::{Comment, Tok, K};
7	use crate::diag::{Diag, Span};
8	use std::collections::HashMap;
9	
10	type R<T> = Result<T, Diag>;
11	
12	pub const SEP_ERR: &str = "expected a newline, ';', or a closing bracket";
13	const NODE_ERR: &str = "a node leads with bars — write '|box#X|' (a bare name is a link endpoint)";
14	use super::lex::MATH_ERR;
15	const GROUP_ERR: &str = "to compute here, wrap the math in a group — e.g. (a - b)";
16	const LABEL_FIRST: &str = "a label comes before classes — write '|box| \"X\" .hot'";
17	const CLASS_GLUE: &str = "classes glue into a chain — write '.hot.loud', no space";
18	const ONE_LABEL: &str = "one inline label — put two or more in a '[ ]'";
19	const CLASS_FIRST: &str = "a class comes before the style block — write '|box| .hot { … }'";
20	
21	fn perr(msg: &str, t: &Tok) -> Diag {
22	    Diag::error("parse", msg, Span::new(t.s, t.e))
23	}
24	
25	struct Term {
26	    text: String,
27	    call: bool,
28	    tracks: i64,      // grid tracks this term stands for in `columns:`
29	    num: Option<f64>, // a plain number literal
30	}
31	
32	#[derive(Clone, Copy, PartialEq)]
33	enum Ctx {
34	    Top,
35	    Children,
36	    Define,
37	    Labels,
38	}
39	
40	pub struct Parser<'a> {
41	    src: &'a str,
42	    toks: &'a [Tok],
43	    comments: &'a [Comment],
44	    pos: usize,
45	    defines: HashMap<String, String>,
46	    // how deep inside '[ ]' blocks the parser is
47	    brackets: usize,
48	}
49	
50	pub fn render_number(v: f64) -> String {
51	    if v == 0.0 {
52	        return "0".to_string();
53	    }
54	    format!("{}", v)
55	}
56	
57	pub fn render_string(s: &str) -> String {
58	    let t = s.trim();
59	    let mut o = String::with_capacity(t.len() + 2);
60	    o.push('"');
61	    for c in t.chars() {
62	        match c {
63	            '"' => o.push_str("\\\""),
64	            '\\' => o.push_str("\\\\"),
65	            '\n' => o.push_str("\\n"),
66	            '\t' => o.push_str("\\t"),
67	            c => o.push(c),
68	        }
69	    }
70	    o.push('"');
71	    o
72	}
73	
74	impl<'a> Parser<'a> {
75	    pub fn new(src: &'a str, toks: &'a [Tok], comments: &'a [Comment]) -> Self {
76	        Parser { src, toks, comments, pos: 0, defines: HashMap::new(), brackets: 0 }
77	    }
78	
79	    fn peek(&self) -> K {
80	        self.toks[self.pos].k
81	    }
82	    fn peek_at(&self, k: usize) -> K {
83	        let i = (self.pos + k).min(self.toks.len() - 1);
84	        self.toks[i].k
85	    }
86	    fn tok(&self) -> &Tok {
87	        &self.toks[self.pos]
88	    }
89	    fn tok_at(&self, k: usize) -> &Tok {
90	        let i = (self.pos + k).min(self.toks.len() - 1);
91	        &self.toks[i]
92	    }
93	    fn bump(&mut self) -> Tok {
94	        let t = self.toks[self.pos].clone();
95	        if self.pos < self.toks.len() - 1 {
96	            self.pos += 1;
97	        }
98	        t
99	    }
100	    // end offset of the last consumed token
101	    fn last_end(&self) -> usize {
102	        if self.pos == 0 {
103	            0
104	        } else {
105	            self.toks[self.pos - 1].e
106	        }
107	    }
108	    fn skip_newlines(&mut self) {
109	        while self.peek() == K::Newline {
110	            self.bump();
111	        }
112	    }
113	    fn err_here(&self, msg: &str) -> Diag {
114	        perr(msg, self.tok())
115	    }
116	    fn decl_msg(&self) -> &'static str {
117	        if self.brackets > 0 {
118	            "declarations go in '{ }', not '[ ]'"
119	        } else {
120	            "a declaration belongs in a '{ }' block"
121	        }
122	    }
123	    // two glued bars: the '||' (flush) operator
124	    fn at_barbar(&self) -> bool {
125	        self.peek() == K::Bar && self.peek_at(1) == K::Bar && !self.tok_at(1).sp
126	    }
127	
128	    // ------------------------------------------------------------- trivia
129	    fn gap(&self, a: usize, b: usize) -> (Option<String>, Vec<Triv>) {
130	        let mut first = None;
131	        let mut out = Vec::new();
132	        let mut pos = a;
133	        for c in self.comments.iter().filter(|c| c.s >= a && c.s < b) {
134	            let nl = self.src[pos..c.s].matches('\n').count();
135	            if nl == 0 && pos == a && first.is_none() {
136	                first = Some(c.text.clone());
137	            } else {
138	                if self.blank_before(c.s) {
139	                    out.push(Triv::Blank);
140	                }
141	                out.push(Triv::Comment { text: c.text.clone(), own: c.own_line });
142	            }
143	            pos = c.e;
144	        }
145	        if b > a && self.blank_before(b) {
146	            out.push(Triv::Blank);
147	        }
148	        (first, out)
149	    }
150	
151	    // the whitespace right before `pos` spans an empty line
152	    fn blank_before(&self, pos: usize) -> bool {
153	        let bytes = self.src.as_bytes();
154	        let mut i = pos;
155	        let mut nl = 0;
156	        while i > 0 {
157	            match bytes[i - 1] {
158	                b'\n' => nl += 1,
159	                b' ' | b'\t' | b'\r' => {}
160	                _ => break,
161	            }
162	            i -= 1;
163	        }
164	        nl >= 2
165	    }
166	
167	    fn build_block<T>(&self, open_end: usize, items: Vec<(usize, usize, T)>, close_start: usize) -> Block<T> {
168	        let any_comment = self.has_comment_in(open_end, close_start);
169	        let comment_among = match (items.first(), items.last()) {
170	            (Some(f), Some(l)) => self.has_comment_in(f.0, l.1),
171	            _ => false,
172	        };
173	        let mut entries: Vec<Entry<T>> = Vec::new();
174	        let mut prev_end = open_end;
175	        for (s, e, item) in items {
176	            let (first, rest) = self.gap(prev_end, s);
177	            let mut lead = Vec::new();
178	            if let Some(c) = first {
179	                match entries.last_mut() {
180	                    Some(last) => last.trail = Some(c),
181	                    None => lead.push(Triv::Comment { text: c, own: false }),
182	                }
183	            }
184	            lead.extend(rest);
185	            entries.push(Entry { lead, item, trail: None });
186	            prev_end = e;
187	        }
188	        let (first, rest) = self.gap(prev_end, close_start);
189	        let mut close = Vec::new();
190	        if let Some(c) = first {
191	            match entries.last_mut() {
192	                Some(last) => last.trail = Some(c),
193	                None => close.push(Triv::Comment { text: c, own: false }),
194	            }
195	        }
196	        close.extend(rest);
197	        Block { entries, close, any_comment, comment_among }
198	    }
199	
200	    fn has_comment_in(&self, a: usize, b: usize) -> bool {
201	        self.comments.iter().any(|c| c.s >= a && c.s < b)
202	    }
203	
204	    // ------------------------------------------------------------ document
205	    pub fn parse_doc(&mut self) -> R<Doc> {
206	        self.skip_newlines();
207	        let mut items: Vec<(usize, usize, Option<Stmt>)> = Vec::new();
208	        let mut sheet = None;
209	        if self.peek() == K::LBrace {
210	            let s = self.tok().s;
211	            let b = self.parse_sheet()?;
212	            sheet = Some(b);
213	            items.push((s, self.last_end(), None));
