197	        self.push(cur);
198	    }
199	
200	    fn decls(&mut self, b: &Block<Decl>, indent: usize) {
201	        let es = &b.entries;
202	        let mut i = 0;
203	        while i < es.len() {
204	            let e = &es[i];
205	            self.trivia(indent, &e.lead);
206	            if e.item.draw {
207	                self.draw(indent, &e.item);
208	                self.trail_opt(indent, &e.trail);
209	                i += 1;
210	                continue;
211	            }
212	            let mut j = i;
213	            while j + 1 < es.len() && es[j].trail.is_none() && es[j + 1].lead.is_empty() && !es[j + 1].item.draw {
214	                j += 1;
215	            }
216	            let text: Vec<String> = es[i..=j].iter().map(|x| x.item.text()).collect();
217	            self.line(indent, &text.join(" "));
218	            self.trail_opt(indent, &es[j].trail);
219	            i = j + 1;
220	        }
221	        self.trivia(indent, &b.close);
222	    }
223	
224	    fn style_inline(b: &Block<Decl>) -> Option<String> {
225	        if b.has_trivia() {
226	            return None;
227	        }
228	        // a drawing with several subpaths never fits one line
229	        if b.entries.iter().any(|e| e.item.draw && e.item.groups.iter().flatten().skip(1).any(|t| is_move(t))) {
230	            return None;
231	        }
232	        let parts: Vec<String> = b.entries.iter().map(|e| e.item.text()).collect();
233	        Some(format!("{{ {} }}", parts.join(" ")))
234	    }
235	
236	    // `prefix { style } [ kids ]`
237	    fn composite(&mut self, indent: usize, prefix: String, style: Option<&Block<Decl>>, kids: Kids) {
238	        let mut cur = prefix;
239	        if let Some(b) = style {
240	            let inline = Self::style_inline(b).map(|s| format!("{} {}", cur, s));
241	            match inline {
242	                Some(l) if indent + l.len() <= WIDTH => cur = l,
243	                _ => {
244	                    self.line(indent, &format!("{} {{", cur));
245	                    self.decls(b, indent + 2);
246	                    cur = "}".to_string();
247	                }
248	            }
249	        }
250	        match kids {
251	            Kids::None => self.line(indent, &cur),
252	            Kids::Define(b) => {
253	                self.line(indent, &format!("{} [", cur));
254	                self.stmt_entries(b, indent + 2);
255	                self.line(indent, "]");
256	            }
257	            Kids::Node(b, cols) => self.children(indent, cur, b, cols),
258	            Kids::Labels(b) => self.children(indent, cur, b, None),
259	        }
260	    }
261	
262	    fn plain_texts<'b>(b: &'b Block<Stmt>) -> Option<Vec<&'b Text>> {
263	        let mut v = Vec::new();
264	        for e in &b.entries {
265	            match &e.item {
266	                Stmt::Text(t) => v.push(t),
267	                _ => return None,
268	            }
269	        }
270	        Some(v)
271	    }
272	
273	    fn children(&mut self, indent: usize, cur: String, b: &Block<Stmt>, cols: Option<i64>) {
274	        if let Some(texts) = Self::plain_texts(b) {
275	            if let Some(n) = cols {
276	                let between_blank = b.entries.iter().skip(1).any(|e| !e.lead.is_empty());
277	                if !b.comment_among && !between_blank {
278	                    self.line(indent, &format!("{} [", cur));
279	                    self.rows(&texts, n, indent + 2);
280	                    if let Some(last) = b.entries.last() {
281	                        self.trail_opt(indent + 2, &last.trail);
282	                    }
283	                    self.trivia(indent + 2, &b.close);
284	                    self.line(indent, "]");
285	                    return;
286	                }
287	            } else if !b.has_trivia() && texts.iter().all(|t| t.classes.is_empty() && t.style.is_none()) {
288	                let items: Vec<&str> = texts.iter().map(|t| t.text.as_str()).collect();
289	                let l = format!("{} [ {} ]", cur, items.join(" "));
290	                if indent + l.len() <= WIDTH {
291	                    self.line(indent, &l);
292	                    return;
293	                }
294	            }
295	        }
296	        self.line(indent, &format!("{} [", cur));
297	        self.stmt_entries(b, indent + 2);
298	        self.line(indent, "]");
299	    }
300	
301	    fn rows(&mut self, texts: &[&Text], n: i64, indent: usize) {
302	        let n = if n < 1 { 1 } else { n.min(1_000_000) as usize };
303	        let rows: Vec<&[&Text]> = texts.chunks(n).collect();
304	        let lifted = |r: &[&Text]| r.iter().any(|t| !t.classes.is_empty() || t.style.is_some());
305	        let mut widths = vec![0usize; n.min(texts.len().max(1))];
306	        for r in &rows {
307	            if lifted(r) {
308	                continue;
309	            }
310	            for (c, t) in r.iter().enumerate() {
311	                widths[c] = widths[c].max(t.text.len());
312	            }
313	        }
314	        for r in &rows {
315	            if lifted(r) {
316	                let mut prefix = String::new();
317	                let last = r.len() - 1;
318	                let mut done = false;
319	                for (c, t) in r.iter().enumerate() {
320	                    if c > 0 {
321	                        prefix.push(' ');
322	                    }
323	                    prefix.push_str(&t.text);
324	                    if !t.classes.is_empty() {
325	                        prefix.push(' ');
326	                        prefix.push_str(&t.classes);
327	                    }
328	                    if let Some(st) = &t.style {
329	                        if c == last {
330	                            self.composite(indent, prefix.clone(), Some(st), Kids::None);
331	                            done = true;
332	                        } else if let Some(s) = Self::style_inline(st) {
333	                            prefix.push(' ');
334	                            prefix.push_str(&s);
335	                        }
336	                    }
337	                }
338	                if !done {
339	                    self.line(indent, &prefix);
340	                }
341	                continue;
342	            }
343	            let mut s = String::new();
344	            let last = r.len() - 1;
345	            for (c, t) in r.iter().enumerate() {
346	                s.push_str(&t.text);
347	                if c < last {
348	                    s.push_str(&pad(widths[c] - t.text.len() + 1));
349	                }
350	            }
351	            self.line(indent, &s);
352	        }
353	    }
354	
355	    fn stmt_entries(&mut self, b: &Block<Stmt>, indent: usize) {
356	        for e in &b.entries {
357	            self.trivia(indent, &e.lead);
358	            self.stmt(&e.item, indent);
359	            self.trail_opt(indent, &e.trail);
360	        }
361	        self.trivia(indent, &b.close);
362	    }
363	
364	    fn stmt(&mut self, s: &Stmt, indent: usize) {
365	        match s {
366	            Stmt::Node(n) => {
367	                let mut prefix = n.head.clone();
368	                if let Some(l) = &n.label {
369	                    prefix.push(' ');
370	                    prefix.push_str(l);
371	                }
372	                if !n.classes.is_empty() {
373	                    prefix.push(' ');
374	                    prefix.push_str(&n.classes);
375	                }
376	                let kids = match &n.children {
377	                    Some(b) => Kids::Node(b, n.columns),
378	                    None => Kids::None,
379	                };
380	                self.composite(indent, prefix, n.style.as_ref(), kids);
381	            }
382	            Stmt::Text(t) => {
383	                let mut prefix = t.text.clone();
384	                if !t.classes.is_empty() {
385	                    prefix.push(' ');
386	                    prefix.push_str(&t.classes);
387	                }
388	                self.composite(indent, prefix, t.style.as_ref(), Kids::None);
389	            }
390	            Stmt::Link(l) => {
391	                let mut prefix = l.head.clone();
392	                let single = l.labels.entries.len() == 1 && !l.has_comment;
393	                let mut kids = Kids::None;
394	                match l.labels.entries.first().map(|e| &e.item) {
395	                    Some(Stmt::Text(t)) if single && t.style.is_none() => {
396	                        prefix.push(' ');
397	                        prefix.push_str(&t.text);
398	                        if !t.classes.is_empty() {
399	                            prefix.push(' ');
400	                            prefix.push_str(&t.classes);
401	                        }
402	                    }
403	                    Some(_) => kids = Kids::Labels(&l.labels),
404	                    None => {}
405	                }
406	                if !l.classes.is_empty() {
407	                    prefix.push(' ');
408	                    prefix.push_str(&l.classes);
409	                }
410	                self.composite(indent, prefix, l.style.as_ref(), kids);
411	            }
412	        }
413	    }
414	}
415	
416	enum Kids<'a> {
417	    None,
418	    Define(&'a Block<Stmt>),
419	    Node(&'a Block<Stmt>, Option<i64>),

