    os.remove(os.path.join(outdir, f))
d = tempfile.mkdtemp(dir='/tmp/fmt')
ORIG = '/workspace/executable'
CH = list('{}[]();:,.|#"-><&=*/+~^%!?@$\'\\ \n\t') + ['//', '->', '::', '..', '(-)', '(o)', '"x"', '|box|', '#id', '.c', '--v', '1.5', 'é']

def damage(s, r):
    k = r.randint(0, 5)
    if not s:
        return s
    if k == 0:
        i = r.randrange(len(s)); return s[:i] + s[i+1:]
    if k == 1:
        i = r.randrange(len(s) + 1); return s[:i] + r.choice(CH) + s[i:]
    if k == 2:
        return s[:r.randrange(len(s))]
    if k == 3:
        ls = s.split('\n'); i = r.randrange(len(ls)); del ls[i]; return '\n'.join(ls)
    if k == 4:
        i = r.randrange(len(s)); j = min(len(s), i + r.randint(1, 6)); return s[:i] + s[j:]
    ls = s.split('\n'); i = r.randrange(len(ls)); j = r.randrange(len(ls)); ls[i], ls[j] = ls[j], ls[i]; return '\n'.join(ls)

def run(b, src):
    p = os.path.join(d, 'in.lini')
    with open(p, 'w') as f: f.write(src)
    r = subprocess.run([b, 'fmt', '--stdout', 'in.lini'], capture_output=True, cwd=d, timeout=20)
    return r.stdout + b'\n--stderr--\n' + r.stderr + b'\n--exit %d--' % r.returncode

bad = []
