#!/usr/bin/env python3
# Collect (message -> code, family) from the original's --json output over many error inputs.
import subprocess, os, tempfile, json, random, sys, re
sys.path.insert(0, '/tmp/fmt')
from gen import G
d = tempfile.mkdtemp(dir='/tmp/fmt')
CH = list('{}[]();:,.|#"-><&=*/+~^%!?@$\'\\ \n\t') + ['//', '->', '::', '..', '(-)', '(o)', '"x"', '|box|', '#id', '.c', '--v', '1.5', 'é']
def damage(s, r):
    k = r.randint(0, 5)
    if not s: return s
    if k == 0:
        i = r.randrange(len(s)); return s[:i] + s[i+1:]
    if k == 1:
        i = r.randrange(len(s) + 1); return s[:i] + r.choice(CH) + s[i:]
    if k == 2:
        return s[:r.randrange(len(s))]
    if k == 3:
        ls = s.split('\n'); i = r.randrange(len(ls)); del ls[i]; return '\n'.join(ls)
    if k == 4:
        i = r.randrange(len(s)); j = min(len(s), i + r.randint(1, 6)); return s[:i] + s[j:]
    ls = s.split('\n'); i = r.randrange(len(ls)); j = r.randrange(len(ls)); ls[i], ls[j] = ls[j], ls[i]; return '\n'.join(ls)
codes = {}
same = 0; diff = 0; diffs = []
n = int(sys.argv[1]) if len(sys.argv) > 1 else 500
for i in range(n):
    r = random.Random(i)
    src = G(i).doc()
    for _ in range(r.randint(1, 2)):
        src = damage(src, r)
    p = os.path.join(d, 'in.lini'); open(p, 'w').write(src)
    rj = subprocess.run(['/workspace/executable', '--json', 'in.lini'], capture_output=True, cwd=d, text=True)
    rf = subprocess.run(['/workspace/executable', 'fmt', '--stdout', 'in.lini'], capture_output=True, cwd=d, text=True)
    rc = subprocess.run(['/workspace/executable', 'in.lini'], capture_output=True, cwd=d, text=True)
    try:
        j = json.loads(rj.stdout)
    except Exception:
        continue
    errs = [x for x in j['diagnostics'] if x['severity'] == 'error']
    if rf.returncode != 0:
        # fmt failed: compare with compile's error line
        cl = [l for l in rc.stderr.split('\n') if ': error: ' in l]
        if cl and cl[0] == rf.stderr.strip().split('\n')[0]:
            same += 1
        else:
            diff += 1; diffs.append((src, rf.stderr, rc.stderr))
        if errs:
            e = errs[0]
            key = e['message']
            key = re.sub(r"'[^']*'", "'X'", key)
            codes.setdefault((e['code'], e['family']), set()).add(key)
print('fmt-error vs compile first error: same %d, diff %d' % (same, diff))
for (c, f), ms in sorted(codes.items()):
    print(c, f)
    for m in sorted(ms):
        print('    ', m)
for src, a, b in diffs[:5]:
    print('=====\n', src, '\n--- fmt:', a, '\n--- compile:', b)

