78	        "bad-escape"
79	    } else if msg.starts_with("unexpected character") {
80	        "unexpected-char"
81	    } else {
82	        "lex"
83	    };
84	    Diag::error(family, msg, Span::new(s, e))
85	}
86	
87	pub fn lex(src: &str) -> Result<Lexed, Diag> {
88	    let cs: Vec<(usize, char)> = src.char_indices().collect();
89	    let n = cs.len();
90	    let at = |i: usize| -> char { if i < n { cs[i].1 } else { '\0' } };
91	    let off = |i: usize| -> usize { if i < n { cs[i].0 } else { src.len() } };
92	    let mut toks: Vec<Tok> = Vec::new();
93	    let mut comments: Vec<Comment> = Vec::new();
94	    // a leading byte-order mark is skipped
95	    let mut i = if n > 0 && cs[0].1 == '\u{feff}' { 1 } else { 0 };
96	    let mut depth: usize = 0;
97	    let mut sp = true;
98	    let mut line_start = true;
99	    // a run of newlines yields one Newline token; a comment ends the run
100	    let mut in_nl_run = false;
101	    // trivia waiting for the next token, and where the last token or
102	    // comment ended (blank lines are counted from there)
103	    let mut pending: Vec<Triv> = Vec::new();
104	    let mut content_end = 0usize;
105	    let blank_between = |a: usize, b: usize| -> bool { src[a..b].matches('\n').count() >= 2 };
106	    while i < n {
107	        let c = at(i);
108	        match c {
109	            ' ' | '\t' | '\r' => {
110	                i += 1;
111	                sp = true;
112	                continue;
113	            }
114	            '\n' => {
115	                // inside ( ) a line break is plain whitespace
116	                if !in_nl_run && depth == 0 {
117	                    let pre = std::mem::take(&mut pending);
118	                    toks.push(Tok { k: K::Newline, s: off(i), e: off(i + 1), sp, v: 0.0, text: String::new(), pre });
119	                    in_nl_run = true;
120	                }
121	                i += 1;
122	                sp = true;
123	                line_start = true;
124	                continue;
125	            }
126	            '/' if at(i + 1) == '/' => {
127	                let mut j = i;
128	                while j < n && at(j) != '\n' {
129	                    j += 1;
130	                }
131	                let text: String = src[off(i)..off(j)].trim_end().to_string();
132	                if blank_between(content_end, off(i)) {
133	                    pending.push(Triv::Blank);
134	                }
135	                pending.push(Triv::Comment { text: text.clone(), own: line_start });
136	                content_end = off(j);
137	                comments.push(Comment { s: off(i), e: off(j), text, own_line: line_start });
138	                in_nl_run = false;
139	                i = j;
140	                sp = true;
141	                continue;
142	            }
143	            _ => {}
144	        }
145	        line_start = false;
146	        in_nl_run = false;
147	        let start = i;
148	        let mut text = String::new();
149	        let mut v = 0.0;
150	        let k: K;
151	        if c == '"' {
152	            let mut s = String::new();
153	            let mut j = i + 1;
154	            loop {
155	                if j >= n {
156	                    return Err(err("unterminated string literal", off(i), src.len()));
157	                }
158	                let d = at(j);
159	                if d == '"' {
160	                    j += 1;
161	                    break;
162	                }
163	                if d == '\\' {
164	                    if j + 1 >= n {
165	                        return Err(err("unterminated escape sequence", off(j), off(j + 1)));
166	                    }
167	                    match at(j + 1) {
168	                        'n' => s.push('\n'),
169	                        't' => s.push('\t'),
170	                        '"' => s.push('"'),
171	                        '\\' => s.push('\\'),
172	                        e => {
173	                            return Err(err(
174	                                &format!("invalid escape sequence '\\{}'", e),
175	                                off(j),
176	                                off(j + 2),
177	                            ));
178	                        }
179	                    }
180	                    j += 2;
181	                    continue;
182	                }
183	                s.push(d);
184	                j += 1;
185	            }
186	            k = K::Str;
187	            text = s;
188	            i = j;
189	        } else if c == '\'' {
190	            return Err(err("single quotes are not strings — use \"…\"", off(i), off(i + 1)));
191	        } else if c.is_ascii_digit() && depth == 0 && after_path_dot(&toks, sp) {
192	            // a copy index: `a.2` (digits only)
193	            let mut j = i;
194	            while at(j).is_ascii_digit() {
195	                j += 1;
196	            }
197	            k = K::Num;
198	            text = src[off(i)..off(j)].to_string();
199	            v = text.parse().unwrap_or(0.0);
200	            i = j;
201	        } else if c.is_ascii_digit() || (c == '.' && at(i + 1).is_ascii_digit() && !(depth == 0 && glued_to_ident(&toks, sp))) {
202	            let (kk, j, val) = lex_number(&cs, i, depth > 0);
203	            k = kk;
204	            v = val;
205	            text = src[off(i)..off(j)].to_string();
206	            i = j;
207	        } else if (c == '-' || c == '+')
208	            && (at(i + 1).is_ascii_digit() || (at(i + 1) == '.' && at(i + 2).is_ascii_digit()))
209	        {
210	            let (kk, j, val) = lex_number(&cs, i + 1, depth > 0);
211	            k = kk;
212	            v = if c == '-' { -val } else { val };
213	            text = src[off(i)..off(j)].to_string();
214	            i = j;
215	        } else if is_ident_start(c) {
216	            let mut j = i;
217	            while j < n && is_ident_char(at(j)) {
218	                j += 1;
219	            }
220	            k = K::Ident;
221	            text = src[off(i)..off(j)].to_string();
222	            i = j;
223	        } else if c == '#' {
224	            let mut j = i + 1;
225	            while j < n && is_ident_char(at(j)) {
226	                j += 1;
227	            }
228	            k = K::Hash;
229	            text = src[off(i + 1)..off(j)].to_string();
230	            i = j;
231	        } else if c == '-' && at(i + 1) == '-' && is_ident_start(at(i + 2)) {
232	            let mut j = i + 2;
233	            while j < n && is_ident_char(at(j)) {
234	                j += 1;
235	            }
236	            k = K::Var;
237	            text = src[off(i + 2)..off(j)].to_string();
238	            i = j;
239	        } else if c == '.' {
240	            k = K::Dot;
241	            i += 1;
242	        } else if c == '|' {
243	            // '||' is two bars; the parser reads glued bars as the operator
244	            k = K::Bar;
245	            i += 1;
246	        } else if c == '{' {
247	            k = K::LBrace;
248	            i += 1;
249	        } else if c == '}' {
250	            k = K::RBrace;
251	            i += 1;
252	        } else if c == '[' {
253	            k = K::LBrack;
254	            i += 1;
255	        } else if c == ']' {
256	            k = K::RBrack;
257	            i += 1;
258	        } else if c == '(' {
259	            let c1 = at(i + 1);
260	            let call_paren = !sp && matches!(toks.last().map(|t| t.k), Some(K::Ident) | Some(K::Num) | Some(K::Percent) | Some(K::Str) | Some(K::Hash) | Some(K::Var) | Some(K::RParen));
261	            if !call_paren && at(i + 2) == ')' && (c1 == '-' || c1 == 'o' || c1 == '<') {
262	                k = K::Dim;
263	                text = format!("({})", c1);
264	                i += 3;
265	            } else if !call_paren && at(i + 2) == ')' && c1 == '>' {
266	                return Err(err("'(>)' is reserved — the angle op is '(<)'", off(i), off(i + 3)));
267	            } else {
268	                depth += 1;
269	                k = K::LParen;
270	                i += 1;
271	            }
272	        } else if c == ')' {
273	            depth = depth.saturating_sub(1);
274	            k = K::RParen;
275	            i += 1;
276	        } else if c == ';' {
277	            k = K::Semi;
278	            i += 1;
279	        } else if c == ',' {
280	            k = K::Comma;
281	            i += 1;
282	        } else if c == ':' {
283	            if at(i + 1) == ':' {
284	                k = K::DColon;
285	                i += 2;
286	            } else {
287	                k = K::Colon;
288	                i += 1;
289	            }
290	        } else if c == '&' {
291	            if depth > 0 && at(i + 1) == '&' {
292	                k = K::Math;
293	                text = "&&".into();
294	                i += 2;
295	            } else {
296	                k = K::Amp;
297	                i += 1;
298	            }
299	        } else if c == '=' {
300	            if at(i + 1) == '=' && depth > 0 {
301	                k = K::Math;
302	                text = "==".into();
303	                i += 2;
304	            } else {
305	                k = K::Eq;
306	                i += 1;
307	            }
308	        } else if depth > 0 && "+-*/^?<>!".contains(c) {
309	            let two: String = [c, at(i + 1)].iter().collect();
310	            if two == "<=" || two == ">=" || two == "!=" {
311	                k = K::Math;
312	                text = two;
313	                i += 2;
314	            } else if c == '!' {
315	                return Err(err(&format!("unexpected character '{}'", c.escape_debug()), off(i), off(i + 1)));
316	            } else {
317	                k = K::Math;
318	                text = c.to_string();
319	                i += 1;
320	            }
321	        } else if "-<>~+*".contains(c) {
322	            match lex_link_op(&cs, i, src)? {
323	                Some(j) => {
324	                    k = K::Link;
325	                    text = src[off(i)..off(j)].to_string();
326	                    i = j;
327	                }
328	                None => {
329	                    // only '*' falls through: math outside a group
330	                    return Err(err(MATH_ERR, off(i), off(i + 1)));
331	                }
332	            }
333	        } else if c == '/' || c == '^' {
334	            return Err(err(MATH_ERR, off(i), off(i + 1)));
335	        } else {
336	            return Err(err(&format!("unexpected character '{}'", c.escape_debug()), off(i), off(i + 1)));
337	        }
338	        if blank_between(content_end, off(start)) {
339	            pending.push(Triv::Blank);
340	        }
341	        let pre = std::mem::take(&mut pending);
342	        content_end = off(i);
343	        toks.push(Tok { k, s: off(start), e: off(i), sp, v, text, pre });
344	        sp = false;
345	    }
346	    if blank_between(content_end, src.len()) {
347	        pending.push(Triv::Blank);
348	    }
349	    // the end-of-input token reports at the last real token
350	    let (s, e) = match toks.last() {
351	        Some(t) => (t.s, t.e),
352	        None => (0, 0),
353	    };
354	    toks.push(Tok { k: K::Eof, s, e, sp: true, v: 0.0, text: String::new(), pre: pending });
355	    Ok(Lexed { toks, comments })
356	}
357	
358	// '.5' right after a word ('a.5') is a path index, not a number
359	fn glued_to_ident(toks: &[Tok], sp: bool) -> bool {
360	    !sp && matches!(toks.last().map(|t| t.k), Some(K::Ident))
361	}
362	
363	// right after `name.` (no spaces)
364	fn after_path_dot(toks: &[Tok], sp: bool) -> bool {
365	    if sp || toks.len() < 2 {
366	        return false;
367	    }
368	    let (a, b) = (&toks[toks.len() - 2], &toks[toks.len() - 1]);
369	    b.k == K::Dot && !b.sp && a.k == K::Ident
370	}
371	
372	// digits ['.' digits] | '.' digits, then an optional '%'. Inside ( ) an
373	// exponent may follow: 1e3, 2.5E-2.
374	fn lex_number(cs: &[(usize, char)], digits_at: usize, exp: bool) -> (K, usize, f64) {
375	    let n = cs.len();
376	    let at = |k: usize| -> char { if k < n { cs[k].1 } else { '\0' } };
377	    let mut j = digits_at;
378	    let mut body = String::new();
379	    while at(j).is_ascii_digit() {
380	        body.push(at(j));
381	        j += 1;
382	    }
383	    if at(j) == '.' && at(j + 1).is_ascii_digit() {
384	        body.push('.');
385	        j += 1;
386	        while at(j).is_ascii_digit() {
387	            body.push(at(j));
388	            j += 1;
389	        }
390	    }
391	    if exp && (at(j) == 'e' || at(j) == 'E') {
392	        let mut k = j + 1;
393	        let mut e = String::from("e");
394	        if at(k) == '+' || at(k) == '-' {
395	            e.push(at(k));
396	            k += 1;
397	        }
398	        if at(k).is_ascii_digit() {
399	            while at(k).is_ascii_digit() {
400	                e.push(at(k));
401	                k += 1;
402	            }
403	            body.push_str(&e);
404	            j = k;
405	        }
406	    }
407	    let v: f64 = body.parse().unwrap_or(0.0);
408	    if at(j) == '%' {
409	        return (K::Percent, j + 1, v);
410	    }
411	    (K::Num, j, v)
412	}
413	
414	// Link operators: [left end] line [right end]. Returns the end index, or None
415	// when a lone '*' is not followed by a line.
416	fn lex_link_op(cs: &[(usize, char)], i: usize, src: &str) -> Result<Option<usize>, Diag> {
417	    let n = cs.len();
418	    let at = |k: usize| -> char { if k < n { cs[k].1 } else { '\0' } };
419	    let off = |k: usize| -> usize { if k < n { cs[k].0 } else { src.len() } };
420	    let mut j = i;
421	    let mut left = String::new();
422	    match at(j) {
423	        '<' | '*' => {
424	            left.push(at(j));
425	            j += 1;
426	            if left == "<" && at(j) == '>' {
427	                left.push('>');
428	                j += 1;
429	            }
430	        }
431	        '>' => {
432	            left.push('>');
433	            j += 1;
434	            if at(j) == 'o' || at(j) == '+' {
435	                left.push(at(j));
436	                j += 1;
437	            }
438	        }
439	        '+' => {
440	            left.push('+');
441	            j += 1;
442	            if at(j) == 'o' || at(j) == '+' {
443	                left.push(at(j));
444	                j += 1;
445	            }
446	        }
447	        _ => {}
448	    }
449	    let line_start = j;
450	    // `--name` is a variable, not a line
451	    let var_next = at(j) == '-' && at(j + 1) == '-' && is_ident_start(at(j + 2));
452	    if at(j) == '-' && !var_next {
453	        while at(j) == '-' && j - line_start < 3 {
454	            j += 1;
455	        }
456	    } else if at(j) == '~' {
457	        j += 1;
458	    }
459	    if j == line_start {
460	        if left == "*" && at(line_start) != '-' {
461	            return Ok(None);
462	        }
463	        return Err(err(&format!("expected link-op line after '{}'", left), off(i), off(j)));
464	    }
465	    let line_end = j;
466	    match at(j) {
467	        '>' | '*' | '<' => {
468	            j += 1;
469	        }
470	        '+' => {
471	            j += 1;
472	            if at(j) == '<' {
473	                j += 1;
474	            }
475	        }
476	        'o' => {
477	            if at(j + 1) == '<' || at(j + 1) == '+' {
478	                j += 2;
479	            } else {
480	                return Err(err(
481	                    "'-o' needs a max glyph — write '-o<' or '-o+'; the hollow ring is an ER component only",
482	                    off(line_end - 1),
483	                    off(line_end + 1),
484	                ));
485	            }
486	        }
487	        _ => {}
488	    }
489	    Ok(Some(j))
490	}
