25	// the diagnostic family (and so the code) a parse message belongs to
26	pub fn family_of(msg: &str) -> &'static str {
27	    if msg.starts_with("expected ") {
28	        "expected-token"
29	    } else if msg.starts_with("'| |' needs") {
30	        "empty-bars"
31	    } else if msg.contains("is not a valid id") {
32	        "invalid-id"
33	    } else if msg.starts_with("a declaration belongs in") {
34	        "declaration-outside-block"
35	    } else if msg.starts_with("the stylesheet '{ }' must come first") {
36	        "stylesheet-after-canvas"
37	    } else if msg.starts_with("text content takes no") {
38	        "text-carries-children"
39	    } else if msg.starts_with("a call's '('") {
40	        "spaced-call-paren"
41	    } else {
42	        "parse"
43	    }
44	}
