77	pub fn render_string(s: &str) -> String {
78	    let t = s.trim();
79	    let mut o = String::with_capacity(t.len() + 2);
80	    o.push('"');
81	    for c in t.chars() {
82	        match c {
83	            '"' => o.push_str("\\\""),
84	            '\\' => o.push_str("\\\\"),
85	            '\n' => o.push_str("\\n"),
86	            '\t' => o.push_str("\\t"),
87	            c => o.push(c),
88	        }
89	    }
90	    o.push('"');
91	    o
92	}
