99	    fn peek(&self) -> K {
100	        self.toks[self.pos].k
101	    }
102	    fn peek_at(&self, k: usize) -> K {
103	        let i = (self.pos + k).min(self.toks.len() - 1);
104	        self.toks[i].k
105	    }
106	    fn tok(&self) -> &Tok {
107	        &self.toks[self.pos]
108	    }
109	    fn tok_at(&self, k: usize) -> &Tok {
110	        let i = (self.pos + k).min(self.toks.len() - 1);
111	        &self.toks[i]
112	    }
113	    fn bump(&mut self) -> Tok {
114	        let t = self.toks[self.pos].clone();
115	        if self.pos < self.toks.len() - 1 {
116	            self.pos += 1;
117	        }
118	        t
119	    }
120	    // end offset of the last consumed token
121	    fn last_end(&self) -> usize {
122	        if self.pos == 0 {
123	            0
124	        } else {
125	            self.toks[self.pos - 1].e
126	        }
127	    }
128	    fn skip_newlines(&mut self) {
129	        while self.peek() == K::Newline {
130	            self.bump();
131	        }
132	    }
133	    fn err_here(&self, msg: &str) -> Diag {
134	        perr(msg, self.tok())
135	    }
136	    fn decl_msg(&self) -> &'static str {
137	        if self.brackets > 0 {
138	            "declarations go in '{ }', not '[ ]'"
139	        } else {
140	            "a declaration belongs in a '{ }' block"
141	        }
142	    }
143	    // two glued bars: the '||' (flush) operator
144	    fn at_barbar(&self) -> bool {
145	        self.peek() == K::Bar && self.peek_at(1) == K::Bar && !self.tok_at(1).sp
146	    }
