148	    // ------------------------------------------------------------- trivia
149	    // Trivia rides on tokens (`Tok::pre`). An entry's leading trivia is all
150	    // the trivia from just after the previous entry's last token up to and
151	    // including its own first token; what falls inside an entry stays there.
152	    fn trivia_range(&self, after: Option<usize>, upto: usize) -> Vec<Triv> {
153	        let from = match after {
154	            Some(a) => a + 1,
155	            None => 0,
156	        };
157	        let mut out = Vec::new();
158	        for k in from..=upto.min(self.toks.len() - 1) {
159	            out.extend(self.toks[k].pre.iter().cloned());
160	        }
161	        out
162	    }
163	
164	    fn any_trivia(&self, after: usize, upto: usize) -> bool {
165	        (after + 1..=upto.min(self.toks.len() - 1)).any(|k| !self.toks[k].pre.is_empty())
166	    }
167	
168	    fn any_comment(&self, after: usize, upto: usize) -> bool {
169	        (after + 1..=upto.min(self.toks.len() - 1))
170	            .any(|k| self.toks[k].pre.iter().any(|t| matches!(t, Triv::Comment { .. })))
171	    }
