173	    // items: (first token, last token, item)
174	    fn build_block<T>(&self, open: Option<usize>, items: Vec<(usize, usize, T)>, close: usize) -> Block<T> {
175	        let o = open.unwrap_or(0);
176	        let any_trivia = match open {
177	            Some(o) => self.any_trivia(o, close),
178	            None => !self.trivia_range(None, close).is_empty(),
179	        };
180	        let any_comment = match open {
181	            Some(o) => self.any_comment(o, close),
182	            None => self.trivia_range(None, close).iter().any(|t| matches!(t, Triv::Comment { .. })),
183	        };
184	        let trivia_among = match (items.first(), items.last()) {
185	            (Some(f), Some(l)) => self.any_trivia(f.0, l.1),
186	            _ => false,
187	        };
188	        let _ = o;
189	        let mut entries: Vec<Entry<T>> = Vec::new();
190	        let mut prev = open;
191	        for (f, l, item) in items {
192	            let lead = self.trivia_range(prev, f);
193	            entries.push(Entry { lead, item });
194	            prev = Some(l);
195	        }
196	        let close = self.trivia_range(prev, close);
197	        Block { entries, close, any_trivia, any_comment, trivia_among }
198	    }
