201	    pub fn parse_doc(&mut self) -> R<Doc> {
202	        self.skip_newlines();
203	        let mut items: Vec<(usize, usize, Option<Stmt>)> = Vec::new();
204	        let mut sheet = None;
205	        if self.peek() == K::LBrace {
206	            let f = self.pos;
207	            let b = self.parse_sheet()?;
208	            sheet = Some(b);
209	            items.push((f, self.pos - 1, None));
210	        }
211	        loop {
212	            self.skip_newlines();
213	            if self.peek() == K::Eof {
214	                break;
215	            }
216	            if self.peek() == K::LBrace {
217	                return Err(Diag::error(
218	                    "stylesheet-after-canvas",
219	                    "the stylesheet '{ }' must come first, before any instance",
220	                    Span::new(self.tok().s, self.tok().e),
221	                ));
222	            }
223	            let f = self.pos;
224	            let st = self.parse_stmt(Ctx::Top)?;
225	            items.push((f, self.pos - 1, Some(st)));
226	            self.after_stmt()?;
227	        }
228	        let eof = self.pos;
229	        let blk = self.build_block(None, items, eof);
230	        let mut entries = blk.entries.into_iter();
231	        let mut sheet_lead = Vec::new();
232	        let mut stmts = Vec::new();
233	        if sheet.is_some() {
234	            let e = entries.next().unwrap();
235	            sheet_lead = e.lead;
236	        }
237	        for e in entries {
238	            stmts.push(Entry { lead: e.lead, item: e.item.unwrap() });
239	        }
240	        let stmts = Block {
241	            entries: stmts,
242	            close: blk.close,
243	            any_trivia: blk.any_trivia,
244	            any_comment: blk.any_comment,
245	            trivia_among: blk.trivia_among,
246	        };
247	        let types = resolve_types(&self.defines);
248	        Ok(Doc { sheet, sheet_lead, stmts, types })
249	    }
