259	    // ------------------------------------------------------------- sheet
260	    fn parse_sheet(&mut self) -> R<Block<SheetItem>> {
261	        let open_idx = self.pos;
262	        self.bump();
263	        let mut items = Vec::new();
264	        loop {
265	            self.skip_newlines();
266	            match self.peek() {
267	                K::RBrace => break,
268	                K::Eof => return Err(self.err_here("expected '}'")),
269	                _ => {}
270	            }
271	            let f = self.pos;
272	            let (item, l) = self.parse_sheet_item()?;
273	            items.push((f, l, item));
274	            if self.toks[self.pos - 1].k == K::Semi {
275	                continue;
276	            }
277	            match self.peek() {
278	                K::Semi => {
279	                    self.bump();
280	                }
281	                K::Newline | K::RBrace | K::Str => {}
282	                K::Eof => {}
283	                _ => return Err(self.err_here(SEP_ERR)),
284	            }
285	        }
286	        let close = self.pos;
287	        self.bump();
288	        Ok(self.build_block(Some(open_idx), items, close))
289	    }
