291	    // -> (item, index of its last token; a closing ';' is not part of it)
292	    fn parse_sheet_item(&mut self) -> R<(SheetItem, usize)> {
293	        match self.peek() {
294	            K::Var => {
295	                let t = self.bump();
296	                if self.peek() != K::Colon {
297	                    return Err(self.err_here(&format!("expected ':' after '--{}'", t.text)));
298	                }
299	                self.bump();
300	                let (d, l) = self.parse_decl_rest(format!("--{}", t.text))?;
301	                Ok((SheetItem::Var(d), l))
302	            }
303	            K::Ident => match self.peek_at(1) {
304	                K::Colon => {
305	                    let (d, l) = self.parse_decl()?;
306	                    Ok((SheetItem::Decl(d), l))
307	                }
308	                K::Eq => self.parse_binding(),
309	                K::LParen => self.parse_binding(),
310	                _ => Err(self.err_here("a type only appears in bars — write '|box| { }' to style every box")),
311	            },
312	            K::Bar | K::Dot | K::Hash | K::Dim => {
313	                let it = self.parse_rule_or_define()?;
314	                Ok((it, self.pos - 1))
315	            }
316	            K::Link => Err(self.err_here(
317	                "'->' draws a link on the canvas — style every link with '|-| { stroke: … }' in a '{ }' block",
318	            )),
319	            _ => Err(self.err_here("the stylesheet holds declarations, rules, and defines")),
320	        }
321	    }
