323	    fn parse_binding(&mut self) -> R<(SheetItem, usize)> {
324	        let name = self.bump().text;
325	        let mut params: Option<Vec<String>> = None;
326	        if self.peek() == K::LParen {
327	            self.bump();
328	            let mut ps = Vec::new();
329	            loop {
330	                match self.peek() {
331	                    K::Ident => {
332	                        ps.push(self.bump().text);
333	                    }
334	                    K::RParen if ps.is_empty() => {}
335	                    _ => return Err(self.err_here("expected identifier")),
336	                }
337	                match self.peek() {
338	                    K::Comma => {
339	                        self.bump();
340	                    }
341	                    K::RParen => {
342	                        self.bump();
343	                        break;
344	                    }
345	                    _ => return Err(self.err_here("expected ')'")),
346	                }
347	            }
348	            params = Some(ps);
349	        }
350	        if self.peek() != K::Eq {
351	            return Err(self.err_here("expected '=' — a binding is 'name = value'"));
352	        }
353	        self.bump();
354	        let rhs = self.parse_binding_rhs()?;
355	        let last = self.pos - 1;
356	        if self.peek() == K::Semi {
357	            self.bump();
358	        }
359	        let head = match params {
360	            Some(ps) if !ps.is_empty() => format!("{}({})", name, ps.join(", ")),
361	            _ => name,
362	        };
363	        Ok((SheetItem::Binding(format!("{} = {};", head, rhs)), last))
364	    }
365	
366	    fn parse_binding_rhs(&mut self) -> R<String> {
367	        match self.peek() {
368	            K::Semi | K::Newline | K::RBrace | K::Eof => {
369	                return Err(self.err_here("a binding needs a value — 'name = value'"));
370	            }
371	            _ => {}
372	        }
373	        if self.peek() == K::LParen {
374	            let open = self.bump();
375	            let close_end = self.skip_group(&open)?;
376	            match self.peek() {
377	                K::Semi | K::Newline | K::RBrace | K::Eof => {}
378	                _ => return Err(self.err_here(SEP_ERR)),
379	            }
380	            let inner = self.src[open.e..close_end - 1].trim();
381	            return Ok(expr::binding_group(inner));
382	        }
383	        let start = self.tok().s;
384	        let mut end = start;
385	        let mut depth = 0usize;
386	        loop {
387	            match self.peek() {
388	                K::Semi | K::Eof => break,
389	                K::Newline | K::RBrace if depth == 0 => break,
390	                K::Math if depth == 0 => return Err(self.err_here(MATH_ERR)),
391	                K::LParen => depth += 1,
392	                K::RParen => depth = depth.saturating_sub(1),
393	                _ => {}
394	            }
395	            end = self.bump().e;
396	        }
397	        let text = &self.src[start..end];
398	        Ok(expr::binding_bare(text))
399	    }
