401	    fn parse_rule_or_define(&mut self) -> R<SheetItem> {
402	        // define: |name::base|
403	        if self.peek() == K::Bar
404	            && ((self.peek_at(1) == K::Ident && self.peek_at(2) == K::DColon) || self.peek_at(1) == K::DColon)
405	        {
406	            self.bump();
407	            if self.peek() == K::DColon {
408	                return Err(self.err_here("'| |' needs a type or an '#id'"));
409	            }
410	            let name = self.bump().text;
411	            self.bump(); // ::
412	            if self.peek() != K::Ident {
413	                return Err(self.err_here("expected identifier"));
414	            }
415	            let base = self.bump().text;
416	            if self.peek() != K::Bar {
417	                return Err(self.err_here("expected '|'"));
418	            }
419	            self.bump();
420	            self.defines.push((name.clone(), base.clone()));
421	            let mut style = None;
422	            let mut anchor = self.pos - 1;
423	            if self.peek() == K::LBrace {
424	                let before = self.pos - 1;
425	                let b = self.parse_style_block()?;
426	                anchor = if b.entries.is_empty() { before } else { self.pos - 1 };
427	                style = Some(b);
428	            }
429	            let body = if self.peek() == K::LBrack {
430	                self.parse_children(Ctx::Define, Some(anchor))?
431	            } else {
432	                // no body: a comment left in an empty style block still
433	                // brings one into being
434	                let end = self.pos - 1;
435	                Block {
436	                    entries: Vec::new(),
437	                    close: self.trivia_range(Some(anchor), end),
438	                    any_trivia: self.any_trivia(anchor, end),
439	                    any_comment: self.any_comment(anchor, end),
440	                    trivia_among: false,
441	                }
442	            };
443	            let style = style.filter(|b| !b.entries.is_empty());
444	            let body = if !body.entries.is_empty() || body.close.iter().any(|t| matches!(t, Triv::Comment { .. })) {
445	                Some(body)
446	            } else {
447	                None
448	            };
449	            return Ok(SheetItem::Define { head: format!("|{}::{}|", name, base), style, body });
450	        }
451	        let mut parts: Vec<String> = Vec::new();
452	        loop {
453	            match self.peek() {
454	                K::LBrace => break,
455	                K::Bar => {
456	                    parts.push(self.parse_selector_bars()?);
457	                }
458	                K::Dot => {
459	                    self.bump();
460	                    if self.peek() != K::Ident {
461	                        return Err(self.err_here("expected identifier"));
462	                    }
463	                    parts.push(format!(".{}", self.bump().text));
464	                }
465	                K::Hash => {
466	                    let h = self.bump();
467	                    if !valid_id(&h.text) {
468	                        return Err(perr(&format!("'#{}' is not a valid id — an id starts with a letter or '_'", h.text), &h));
469	                    }
470	                    parts.push(format!("#{}", h.text));
471	                }
472	                K::Dim if !parts.is_empty() && self.tok().text != "(-)" => {
473	                    return Err(self.err_here("expected '{'"))
474	                }
475	                K::Dim => {
476	                    let t = self.bump();
477	                    if t.text != "(-)" {
478	                        return Err(perr(
479	                            "'(-)' selects every dimension — per-kind '(o)' / '(<)' selectors are deferred (SPEC 24)",
480	                            &t,
481	                        ));
482	                    }
483	                    parts.push(t.text);
484	                }
485	                _ => return Err(self.err_here("expected '{'")),
486	            }
487	        }
488	        let block = self.parse_style_block()?;
489	        Ok(SheetItem::Rule { selector: parts.join(" "), block })
490	    }
