492	    fn parse_selector_bars(&mut self) -> R<String> {
493	        self.bump();
494	        let mut ty = None;
495	        if self.peek() == K::Dot {
496	            return Err(self.err_here(
497	                "a selector unit can't glue a type and a class — space them (descendant) or style '.hot'",
498	            ));
499	        }
500	        match self.peek() {
501	            K::Ident => ty = Some(self.bump().text),
502	            K::Link if self.tok().text == "-" && self.peek_at(1) == K::Bar => {
503	                self.bump();
504	                ty = Some("-".to_string());
505	            }
506	            _ => {}
507	        }
508	        let mut id = None;
509	        if self.peek() == K::Hash && !(ty.is_some() && self.tok().sp) {
510	            let h = self.bump();
511	            if !valid_id(&h.text) {
512	                return Err(perr(&format!("'#{}' is not a valid id — an id starts with a letter or '_'", h.text), &h));
513	            }
514	            id = Some(h.text);
515	        }
516	        if ty.is_none() && id.is_none() {
517	            return Err(self.err_here("'| |' needs a type or an '#id'"));
518	        }
519	        if self.peek() == K::Dot && !self.tok().sp {
520	            return Err(self.err_here(
521	                "a selector unit can't glue a type and a class — space them (descendant) or style '.hot'",
522	            ));
523	        }
524	        if self.peek() != K::Bar {
525	            return Err(self.err_here("expected '|'"));
526	        }
527	        self.bump();
528	        let mut s = String::from("|");
529	        if let Some(t) = ty {
530	            s.push_str(&t);
531	        }
532	        if let Some(i) = id {
533	            s.push('#');
534	            s.push_str(&i);
535	        }
536	        s.push('|');
537	        Ok(s)
538	    }
