541	    fn parse_style_block(&mut self) -> R<Block<Decl>> {
542	        let open_idx = self.pos;
543	        self.bump(); // {
544	        let mut items = Vec::new();
545	        loop {
546	            self.skip_newlines();
547	            match self.peek() {
548	                K::RBrace => break,
549	                K::Eof => return Err(self.err_here("expected '}'")),
550	                K::Ident if self.peek_at(1) == K::Colon => {
551	                    let f = self.pos;
552	                    let (d, l) = self.parse_decl()?;
