    depth = 0; cur = []
    for l in lines:
        cur.append(l)
        # crude bracket depth, ignoring strings/comments
        code = l.split('//')[0]
        depth += code.count('{') + code.count('[') - code.count('}') - code.count(']')
        if depth <= 0:
            chunk = '\n'.join(cur).strip('\n')
