#!/usr/bin/env python3
# usage: recomb.py MINE N [seed0] -> recombine top-level chunks of sample files into new docs; differential fmt test
import subprocess, sys, os, tempfile, random, glob
mine = sys.argv[1]; n = int(sys.argv[2]); seed0 = int(sys.argv[3]) if len(sys.argv) > 3 else 1
W = '/workspace/.claude/worktrees/agent-aab11fa07c95ee199/assets'
files = glob.glob(W + '/test_doc_examples/*.lini') + glob.glob(W + '/test_samples/*.lini')
sheets = []; stmts = []
for f in files:
    lines = open(f, encoding='utf-8').read().split('\n')
    depth = 0; cur = []
    for l in lines:
        cur.append(l)
        # crude bracket depth, ignoring strings/comments
        code = l.split('//')[0]
        depth += code.count('{') + code.count('[') - code.count('}') - code.count(']')
        if depth <= 0:
            chunk = '\n'.join(cur).strip('\n')
            cur = []; depth = 0
            if not chunk.strip():
                continue
            if chunk.lstrip().startswith('{'):
                sheets.append(chunk)
            else:
                stmts.append(chunk)
d = tempfile.mkdtemp(dir='/tmp/fmt')
outdir = '/tmp/fmt/recombout'
os.makedirs(outdir, exist_ok=True)
for f in os.listdir(outdir):
    os.remove(os.path.join(outdir, f))
def run(b, src):
    p = os.path.join(d, 'in.lini'); open(p, 'w').write(src)
    r = subprocess.run([b, 'fmt', '--stdout', 'in.lini'], capture_output=True, cwd=d, timeout=20)
    return r.stdout + b'\n--stderr--\n' + r.stderr + b'\n--exit %d--' % r.returncode
bad = []; nerr = 0
for i in range(n):
    r = random.Random(seed0 + i)
    parts = []
    if r.random() < 0.5 and sheets:
        parts.append(r.choice(sheets))
    for _ in range(r.randint(1, 8)):
        c = r.choice(stmts)
        if r.random() < 0.15:
            c = '|group#w%d| [\n' % i + '\n'.join('  ' + x for x in c.split('\n')) + '\n]'
        if r.random() < 0.1:
            c = c + '  // trailing'
        parts.append(c)
        if r.random() < 0.2:
            parts.append('')
    src = '\n'.join(parts) + '\n'
    o1 = run('/workspace/executable', src); o2 = run(mine, src)
    if b'error' in o1.split(b'--stderr--')[1]:
        nerr += 1
    if o1 != o2:
        bad.append((len(src), src, o1, o2))
bad.sort(key=lambda x: x[0])
for k, (l, src, o1, o2) in enumerate(bad):
    open(os.path.join(outdir, 'case%03d.lini' % k), 'w').write(src)
    open(os.path.join(outdir, 'case%03d.orig' % k), 'wb').write(o1)
    open(os.path.join(outdir, 'case%03d.mine' % k), 'wb').write(o2)
print('chunks: %d sheets, %d stmts; mismatches %d / %d (orig errors %d)' % (len(sheets), len(stmts), len(bad), n, nerr))

#!/usr/bin/env python3
# Compare `--json` compile output on documents whose first error is a syntax error (L*/P* codes).
import subprocess, sys, os, tempfile, random, json
sys.path.insert(0, '/tmp/fmt')
from gen import G
mine = sys.argv[1]; n = int(sys.argv[2]); seed0 = int(sys.argv[3]) if len(sys.argv) > 3 else 1
CH = list('{}[]();:,.|#"-><&=*/+~^%!?@$\'\\ \n\t') + ['//', '->', '::', '..', '(-)', '(o)', '"x"', '|box|', '#id', '.c', '--v', '1.5', 'é']
def damage(s, r):
    k = r.randint(0, 5)
    if not s: return s
    if k == 0:
        i = r.randrange(len(s)); return s[:i] + s[i+1:]
    if k == 1:
        i = r.randrange(len(s) + 1); return s[:i] + r.choice(CH) + s[i:]
    if k == 2:
        return s[:r.randrange(len(s))]
    if k == 3:
        ls = s.split('\n'); i = r.randrange(len(ls)); del ls[i]; return '\n'.join(ls)
    if k == 4:
        i = r.randrange(len(s)); j = min(len(s), i + r.randint(1, 6)); return s[:i] + s[j:]
    ls = s.split('\n'); i = r.randrange(len(ls)); j = r.randrange(len(ls)); ls[i], ls[j] = ls[j], ls[i]; return '\n'.join(ls)
d = tempfile.mkdtemp(dir='/tmp/fmt')
def run(b, src, args):
    p = os.path.join(d, 'in.lini'); open(p, 'w').write(src)
    r = subprocess.run([b] + args + ['in.lini'], capture_output=True, cwd=d, timeout=20)
    return r.stdout.decode('utf-8', 'replace'), r.returncode
tot = 0; ok = 0; shown = 0
for i in range(n):
    r = random.Random(seed0 + i)
    src = G(seed0 + i).doc()
    for _ in range(r.randint(1, 2)):
        src = damage(src, r)
    o, rc = run('/workspace/executable', src, ['--json'])
    try:
        j = json.loads(o)
    except Exception:
        continue
    errs = [x for x in j['diagnostics'] if x['severity'] == 'error']
    if not errs or errs[0]['code'][0] not in 'LP':
        continue
    tot += 1
    m, rc2 = run(mine, src, ['--json'])
    if m == o and rc == rc2:
        ok += 1
    elif shown < 5:
        shown += 1
        print('=====', repr(src[:300]))
        print('orig:', o[:600])
        print('mine:', m[:600])
print('syntax-error docs: %d, json identical: %d' % (tot, ok))

