1	// The canonical printer: walks the concrete tree and lays it out line by line.
2	
3	use super::cst::*;
4	
5	pub const WIDTH: usize = 80;
6	
7	pub struct Out {
8	    lines: Vec<String>,
9	    types: Option<std::collections::HashMap<String, String>>,
10	    // a blank line waits for the next line of its own; trailing comments
11	    // that come first still attach to the line above it
12	    pending_blank: bool,
13	}
14	
15	fn pad(n: usize) -> String {
16	    " ".repeat(n)
17	}
18	
19	// an untagged `move(…)` command opens a new subpath
20	fn is_move(t: &str) -> bool {
21	    t.starts_with("move(") && t.ends_with(')')
22	}
23	
24	impl Out {
25	    pub fn new() -> Self {
26	        Out { lines: Vec::new(), pending_blank: false, types: None }
27	    }
28	
29	    pub fn finish(mut self) -> String {
30	        self.flush_blank();
31	        if self.lines.is_empty() {
32	            return String::new();
33	        }
34	        let mut s = self.lines.join("\n");
35	        s.push('\n');
36	        s
37	    }
38	
39	    fn flush_blank(&mut self) {
40	        if self.pending_blank {
41	            self.pending_blank = false;
42	            if !self.lines.is_empty() {
43	                self.lines.push(String::new());
44	            }
45	        }
46	    }
47	
48	    fn push(&mut self, s: String) {
49	        self.flush_blank();
50	        self.lines.push(s);
51	    }
52	
53	    fn line(&mut self, indent: usize, text: &str) {
54	        self.push(format!("{}{}", pad(indent), text));
55	    }
56	
57	    fn blank(&mut self) {
58	        if !self.lines.is_empty() {
59	            self.pending_blank = true;
60	        }
61	    }
62	
63	    fn trail(&mut self, indent: usize, c: &str) {
64	        match self.lines.last_mut() {
65	            Some(l) => {
66	                l.push_str("  ");
67	                l.push_str(c);
68	            }
69	            None => self.line(indent, c),
70	        }
71	    }
72	
73	    fn trivia(&mut self, indent: usize, ts: &[Triv]) {
74	        for t in ts {
75	            match t {
76	                Triv::Blank => self.blank(),
77	                Triv::Comment { text, own: true } => self.line(indent, text),
78	                Triv::Comment { text, own: false } => self.trail(indent, text),
79	            }
80	        }
81	    }
82	
83	    // ------------------------------------------------------------- document
84	    // grid columns a node's bare strings fill: its own `columns:`, else the
85	    // built-in default of its type (entity: 2), followed through defines
86	    fn node_columns(&self, n: &Node) -> Option<i64> {
87	        if n.columns.is_some() {
88	            return n.columns;
89	        }
90	        let types = self.types.as_ref()?;
91	        let mut t: &str = n.ty.as_deref()?;
92	        for _ in 0..64 {
93	            if t == "entity" {
94	                return Some(2);
95	            }
96	            t = types.get(t)?;
97	        }
98	        None
99	    }
100	
101	    pub fn doc(&mut self, d: &Doc) {
102	        self.types = d.types.clone();
103	        let mut sheet_printed = false;
104	        if let Some(sheet) = &d.sheet {
105	            self.trivia(0, &d.sheet_lead);
106	            if sheet.entries.is_empty() {
107	                self.trivia(0, &sheet.close);
108	            } else {
109	                self.line(0, "{");
110	                self.sheet_items(sheet, 2);
111	                self.line(0, "}");
112	                sheet_printed = true;
113	            }
114	        }
115	        let entries = &d.stmts.entries;
116	        // when every link follows every node, a blank line sets the links off
117	        let last_non_link = entries.iter().rposition(|e| !matches!(e.item, Stmt::Link(_)));
118	        let first_link = entries.iter().position(|e| matches!(e.item, Stmt::Link(_)));
119	        let link_break = match (last_non_link, first_link) {
120	            (Some(n), Some(l)) if l > n => Some(l),
121	            _ => None,
122	        };
123	        for (i, e) in entries.iter().enumerate() {
124	            if (i == 0 && sheet_printed) || Some(i) == link_break {
125	                self.blank();
126	            }
127	            self.trivia(0, &e.lead);
128	            self.stmt(&e.item, 0);
129	        }
130	        self.trivia(0, &d.stmts.close);
131	    }
132	
133	    // ---------------------------------------------------------------- sheet
134	    fn sheet_items(&mut self, b: &Block<SheetItem>, indent: usize) {
135	        let es = &b.entries;
136	        let mut i = 0;
137	        while i < es.len() {
138	            let e = &es[i];
139	            self.trivia(indent, &e.lead);
140	            match &e.item {
141	                SheetItem::Decl(d) if !d.draw => {
142	                    let mut j = i;
143	                    while j + 1 < es.len()
144	                        && es[j + 1].lead.is_empty()
145	                        && matches!(&es[j + 1].item, SheetItem::Decl(d2) if !d2.draw)
146	                    {
147	                        j += 1;
148	                    }
149	                    let text: Vec<String> = es[i..=j]
150	                        .iter()
151	                        .map(|x| match &x.item {
152	                            SheetItem::Decl(d) => d.text(),
153	                            _ => unreachable!(),
154	                        })
155	                        .collect();
156	                    self.line(indent, &text.join(" "));
157	                    i = j + 1;
158	                    continue;
159	                }
160	                SheetItem::Decl(d) => self.draw(indent, d),
161	                SheetItem::Var(d) => self.line(indent, &d.text()),
162	                SheetItem::Binding(s) => self.line(indent, s),
163	                SheetItem::Rule { selector, block } => {
164	                    if block.entries.is_empty() {
165	                        // an empty rule keeps its braces — unless a comment
166	                        // sat in them
167	                        if block.any_comment {
168	                            self.line(indent, selector);
169	                        } else {
170	                            self.line(indent, &format!("{} {{}}", selector));
171	                        }
172	                    } else {
173	                        self.composite(indent, selector.clone(), Some(block), Kids::None);
174	                    }
175	                }
176	                SheetItem::Define { head, style, body } => {
177	                    let kids = match body {
178	                        Some(b) => Kids::Define(b),
179	                        None => Kids::None,
180	                    };
181	                    self.composite(indent, head.clone(), style.as_ref(), kids);
182	                }
183	            }
184	            i += 1;
185	        }
186	        self.trivia(indent, &b.close);
187	    }
188	
189	    // `draw:` on its own line(s): every subpath (`move(…)`) starts a line,
190	    // long runs wrap under the first command; commas are dropped.
191	    fn draw(&mut self, indent: usize, d: &Decl) {
192	        let prefix = format!("{}: ", d.name);
193	        let col = indent + prefix.len();
194	        let pieces: Vec<&String> = d.groups.iter().flatten().collect();
195	        if pieces.is_empty() {
196	            self.line(indent, &format!("{} ;", prefix.trim_end()));
197	            return;
198	        }
199	        let mut cur = format!("{}{}{}", pad(indent), prefix, pieces[0]);
200	        for p in pieces.iter().skip(1) {
201	            // one column stays free for the ';' or the next separator
202	            if is_move(p) || cur.len() + 1 + p.len() + 1 > WIDTH {
203	                self.push(cur);
204	                cur = format!("{}{}", pad(col), p);
205	            } else {
206	                cur.push(' ');
207	                cur.push_str(p);
208	            }
209	        }
210	        cur.push(';');
211	        self.push(cur);
212	    }
213	
214	    fn decls(&mut self, b: &Block<Decl>, indent: usize) {
215	        let es = &b.entries;
216	        let mut i = 0;
217	        while i < es.len() {
218	            let e = &es[i];
219	            self.trivia(indent, &e.lead);
220	            if e.item.draw {
221	                self.draw(indent, &e.item);
222	                i += 1;
223	                continue;
224	            }
225	            let mut j = i;
226	            while j + 1 < es.len() && es[j + 1].lead.is_empty() && !es[j + 1].item.draw {
227	                j += 1;
228	            }
229	            let text: Vec<String> = es[i..=j].iter().map(|x| x.item.text()).collect();
230	            self.line(indent, &text.join(" "));
231	            i = j + 1;
232	        }
233	        self.trivia(indent, &b.close);
234	    }
235	
236	    fn style_inline(b: &Block<Decl>) -> Option<String> {
237	        if b.any_trivia {
238	            return None;
239	        }
240	        // a drawing with several subpaths never fits one line
241	        if b.entries.iter().any(|e| e.item.draw && e.item.groups.iter().flatten().skip(1).any(|t| is_move(t))) {
242	            return None;
243	        }
244	        let parts: Vec<String> = b.entries.iter().map(|e| e.item.text()).collect();
245	        Some(format!("{{ {} }}", parts.join(" ")))
246	    }
247	
248	    // `prefix { style } [ kids ]`
249	    fn composite(&mut self, indent: usize, prefix: String, style: Option<&Block<Decl>>, kids: Kids) {
250	        let mut cur = prefix;
251	        if let Some(b) = style {
252	            let inline = Self::style_inline(b).map(|s| format!("{} {}", cur, s));
253	            match inline {
254	                Some(l) if indent + l.len() <= WIDTH => cur = l,
255	                _ => {
256	                    self.line(indent, &format!("{} {{", cur));
257	                    self.decls(b, indent + 2);
258	                    cur = "}".to_string();
259	                }
260	            }
261	        }
262	        match kids {
263	            Kids::None => self.line(indent, &cur),
264	            Kids::Define(b) => {
265	                self.line(indent, &format!("{} [", cur));
266	                self.stmt_entries(b, indent + 2);
267	                self.line(indent, "]");
268	            }
269	            Kids::Node(b, cols) => self.children(indent, cur, b, cols),
270	            Kids::Labels(b) => self.children(indent, cur, b, None),
271	        }
272	    }
273	
274	    fn plain_texts<'b>(b: &'b Block<Stmt>) -> Option<Vec<&'b Text>> {
275	        let mut v = Vec::new();
276	        for e in &b.entries {
277	            match &e.item {
278	                Stmt::Text(t) => v.push(t),
279	                _ => return None,
280	            }
281	        }
282	        Some(v)
283	    }
284	
285	    fn children(&mut self, indent: usize, cur: String, b: &Block<Stmt>, cols: Option<i64>) {
286	        if let Some(texts) = Self::plain_texts(b) {
287	            if let Some(n) = cols {
288	                if !b.trivia_among {
289	                    // rows: what precedes the first cell is dropped
290	                    self.line(indent, &format!("{} [", cur));
291	                    self.rows(&texts, n, indent + 2);
292	                    self.trivia(indent + 2, &b.close);
293	                    self.line(indent, "]");
294	                    return;
295	                }
296	            } else if !b.any_trivia && texts.iter().all(|t| t.classes.is_empty() && t.style.is_none()) {
297	                let items: Vec<&str> = texts.iter().map(|t| t.text.as_str()).collect();
298	                let l = format!("{} [ {} ]", cur, items.join(" "));
299	                if indent + l.len() <= WIDTH {
300	                    self.line(indent, &l);
301	                    return;
302	                }
303	            }
304	        }
305	        self.line(indent, &format!("{} [", cur));
306	        self.stmt_entries(b, indent + 2);
307	        self.line(indent, "]");
308	    }
309	
310	    fn rows(&mut self, texts: &[&Text], n: i64, indent: usize) {
311	        let n = if n < 1 { 1 } else { n.min(1_000_000) as usize };
312	        let rows: Vec<&[&Text]> = texts.chunks(n).collect();
313	        let lifted = |r: &[&Text]| r.iter().any(|t| !t.classes.is_empty() || t.style.is_some());
314	        let mut widths = vec![0usize; n.min(texts.len().max(1))];
315	        for r in &rows {
316	            if lifted(r) {
317	                continue;
318	            }
319	            for (c, t) in r.iter().enumerate() {
320	                widths[c] = widths[c].max(t.text.len());
321	            }
322	        }
323	        for r in &rows {
324	            if lifted(r) {
325	                // cells follow one another; a style that will not fit opens
326	                // up and the row continues after its '}'
327	                let mut cur = String::new();
328	                for (c, t) in r.iter().enumerate() {
329	                    if c > 0 {
330	                        cur.push(' ');
331	                    }
332	                    cur.push_str(&t.text);
333	                    if !t.classes.is_empty() {
334	                        cur.push(' ');
335	                        cur.push_str(&t.classes);
336	                    }
337	                    if let Some(st) = &t.style {
338	                        match Self::style_inline(st) {
339	                            Some(s) if indent + cur.len() + 1 + s.len() <= WIDTH => {
340	                                cur.push(' ');
341	                                cur.push_str(&s);
342	                            }
343	                            _ => {
344	                                self.line(indent, &format!("{} {{", cur));
345	                                self.decls(st, indent + 2);
346	                                cur = "}".to_string();
347	                            }
348	                        }
349	                    }
350	                }
351	                self.line(indent, &cur);
352	                continue;
353	            }
354	            let mut s = String::new();
355	            let last = r.len() - 1;
356	            for (c, t) in r.iter().enumerate() {
357	                s.push_str(&t.text);
358	                if c < last {
359	                    s.push_str(&pad(widths[c] - t.text.len() + 1));
360	                }
361	            }
362	            self.line(indent, &s);
363	        }
364	    }
365	
366	    fn stmt_entries(&mut self, b: &Block<Stmt>, indent: usize) {
367	        for e in &b.entries {
368	            self.trivia(indent, &e.lead);
369	            self.stmt(&e.item, indent);
370	        }
371	        self.trivia(indent, &b.close);
