#!/usr/bin/env python3
# Differential test of binding right-hand sides.
import subprocess, os, tempfile, random, sys
mine = sys.argv[1]; n = int(sys.argv[2])
d = tempfile.mkdtemp(dir='/tmp/fmt')
ATOMS = ['1', '1.50', '-2', '.5', '1e3', 'a', 'x_y', 'k-2', '--v', '"s"', '#fff', '5%', 'pi', 'u']
OPS = [' + ', '+', ' - ', '-', ' * ', '*', ' / ', ' ^ ', '^', ' < ', ' == ', ' != ', ' && ', ' || ', ' ? ']
def expr(r, depth):
    k = r.randint(0, 9)
    if depth > 2 or k < 4:
        return r.choice(ATOMS)
    if k < 6:
        return expr(r, depth + 1) + r.choice(OPS) + expr(r, depth + 1)
    if k == 6:
        return r.choice(['(', '( ']) + expr(r, depth + 1) + r.choice([')', ' )'])
    if k == 7:
        name = r.choice(['f', 'min', 'max', 'sin', 'rgb', 'g'])
        args = [expr(r, depth + 1) for _ in range(r.randint(0, 3))]
        return name + r.choice(['(', ' (']) + r.choice([', ', ',']).join(args) + ')'
    if k == 8:
        return r.choice(['-', '- ']) + expr(r, depth + 1)
    return expr(r, depth + 1) + ' ' + expr(r, depth + 1)
bad = []
for i in range(n):
    r = random.Random(i)
    rhs = expr(r, 0)
    if r.random() < 0.3:
        rhs = '(' + rhs + ')'
    if r.random() < 0.2:
        rhs = '(' + 'x = 1; ' + rhs + ')'
    head = r.choice(['k', 'f(a)', 'g(a, b)', 'h()'])
    src = '{\n  %s = %s;\n}\n' % (head, rhs)
    p = os.path.join(d, 'in.lini'); open(p, 'w').write(src)
    outs = []
    for b in ('/workspace/executable', mine):
        res = subprocess.run([b, 'fmt', '--stdout', 'in.lini'], capture_output=True, cwd=d, timeout=10)
        outs.append((res.stdout, res.stderr, res.returncode))
    if outs[0] != outs[1]:
        bad.append((src, outs))
for src, outs in bad[:15]:
    print('====', src.strip())
    print('  orig:', outs[0][0] or outs[0][1])
    print('  mine:', outs[1][0] or outs[1][1])
print('mismatches %d / %d' % (len(bad), n))

