WORDS = ['red', 'auto', 'a-b', 'x_y', 'none', 'e', 'top', 'move', 'right']
def sp(r):
    return r.choice(['', ' ', '  '])
def term(r, depth, inargs):
    k = r.randint(0, 12)
    if k < 3: return r.choice(NUMS) + (r.choice(['%', '']) if r.random() < 0.2 else '')
