    if k == 5: return r.choice(['"s"', '" t "', '"a\\"b"', '"x\\ny"', '""'])
    if k == 6: return r.choice(['#fff', '#0a84ff', '#FFFF', '#12345678'])
    if k == 7: return r.choice(['--v', '--teal-ink'])
    if k == 8: return '(' + sp(r) + r.choice(['1+2', '1 + 2', 'a*b', 'x', '(y)', 'u * 300, 20 * sin(u)', '-1']) + sp(r) + ')'
    if k <= 11 and depth < 2:
        name = r.choice(['f', 'g', 'rgb', 'min', 'repeat', 'move', 'gradient', 'hatch'])
        args = []
        for _ in range(r.randint(0, 3)):
            if r.random() < 0.25:
                args.append(term(r, depth + 1, True) + r.choice([' + ', '*', ' - ', '-', ' / ']) + term(r, depth + 1, True))
            else:
                args.append(' '.join(term(r, depth + 1, True) for _ in range(r.randint(1, 2))))
        return name + '(' + sp(r) + (sp(r) + ',' + sp(r)).join(args) + sp(r) + ')'
    return r.choice(NUMS)
def value(r):
    groups = []
    for _ in range(r.randint(1, 3)):
        groups.append(r.choice([' ', '  ', '\n  ']).join(term(r, 0, False) for _ in range(r.randint(1, 3))))
    return (sp(r) + ',' + sp(r)).join(groups)
