    k = r.randint(0, 3)
    for _ in range(r.randint(0, 10)):
        if r.random() < 0.08:
            items.append('|box| "n"' + (' [ "x" "y" ]' if r.random() < 0.3 else ''))
        else:
            items.append(cell(r))
    out = '['
    first = True
    for it in items:
        sep = r.choice([' ', ' ', ' ', '\n' + ' ' * (indent + 2), '\n\n' + ' ' * (indent + 2), '; ' if not first else ' '])
