import subprocess, os, tempfile, random, sys
mine = sys.argv[1]; n = int(sys.argv[2]); seed0 = int(sys.argv[3]) if len(sys.argv) > 3 else 0
d = tempfile.mkdtemp(dir='/tmp/fmt')
DECLS = ['gap: 5', 'layout: grid', 'columns: repeat(2)', 'padding: 20', 'fill: --bg', 'direction: column',
         'draw: move(0, 0) up(5) move(1, 1) right(2)', 'draw: move(0,0) right(40) down(20) close()', 'unit: mm', 'scale: 0.02',
         'font-size: 12', 'routing: orthogonal', 'clearance: 12', 'categories: "a", "b", "c"']
SELS = ['|box|', '|-|', '.hot', '#g |-|', '|box#a|', '(-)', '.a.b', '|cyl| .x', '.loud']
def style(r, ind):
    ds = [r.choice(DECLS) for _ in range(r.randint(0, 4))]
    if r.random() < 0.6:
        inner = '; '.join(ds)
        if ds and r.random() < 0.7: inner += ';'
        return '{ ' + inner + (' ' if inner else '') + '}'
    out = '{' + ('  // open' if r.random() < 0.2 else '')
    for x in ds:
        out += '\n' + ' ' * (ind + 2) + x + ';' + ('  // t' if r.random() < 0.2 else '')
        if r.random() < 0.1: out += '\n'
    return out + '\n' + ' ' * ind + '}'
def item(r):
    k = r.randint(0, 9)
    if k < 3:
        return '; '.join(r.choice(DECLS) for _ in range(r.randint(1, 3))) + ';'
