                         'h = "s";', 'z = a b;', 'm = min(1, 2);', 'ramp(s) = min(100, 25 + 1.572*(x/s));'])
    if k < 8:
        return r.choice(SELS) + ' ' + style(r, 2)
    s = '|%s::%s|' % (r.choice(['room', 'card', 'svc']), r.choice(['box', 'group', 'entity', 'table']))
    if r.random() < 0.6: s += ' ' + style(r, 2)
    if r.random() < 0.5:
        body = []
        for _ in range(r.randint(0, 3)):
            body.append(r.choice(['|box#in| "in"', '|box#out| "out"', 'in -> out "flows"', '"x" "y"', '|box| [ "a" "b" ]', '// c']))
